    #[test]
    fn shared_templates_do_not_prove_unrelated_dates() {
        let dir = tempfile::tempdir().unwrap();
        let naming = PostNamingContext::new(
            "Artist",
            Some("2026-07-23T00:00:00Z"),
            Some("Bundle"),
            "12345",
            Some("patreon"),
        );
        for template in ["固定目录", "{year}/{month}", "{title}", "{day}"] {
            let expected = dir
                .path()
                .join(naming.format_folder_path_with_template(template));
            fs::create_dir_all(&expected).unwrap();
            fs::write(expected.join("other.rar"), b"unrelated date").unwrap();
            let resolved = resolve_post_folder(
                dir.path().to_str().unwrap(),
                &naming,
                template,
                &naming.date,
                &[],
            );
            assert_eq!(resolved.observation.state, OBSERVED_AMBIGUOUS, "{template}");
            assert_eq!(resolved.source, FOLDER_SHARED_TEMPLATE);
        }
        for template in ["{user}/{date} {title}", "{date}/{id}", "{id}", ""] {
            assert!(template_scopes_post(&naming, template), "{template}");
        }
        // Reliable full-day evidence still wins under arbitrary custom templates.
        let dated = dir.path().join("2026-07-23 historical");
        fs::create_dir_all(&dated).unwrap();
        fs::write(dated.join("a.rar"), b"archive").unwrap();
        let resolved = resolve_post_folder(
            dir.path().to_str().unwrap(),
            &naming,
            "固定目录",
            &naming.date,
            &[],
        );
        assert_eq!(resolved.observation.state, OBSERVED_CONTENT);
        assert_eq!(resolved.source, FOLDER_FROM_DAY);
    }

    #[test]
    fn generated_text_files_are_not_a_delivery() {
        let dir = tempfile::tempdir().unwrap();
        let post_dir = dir.path().join("2026-09-11 a title");
        fs::create_dir_all(&post_dir).unwrap();
        let naming = PostNamingContext::new(
            "artist",
            Some("2026-09-11T00:00:00"),
            Some("a title"),
            "12345",
            Some("fanbox"),
        );
        let derived = derived_text_names(&naming);
        fs::write(post_dir.join(naming.format_content_filename()), b"Title: a title\nPost ID: 12345\nUser ID: artist\nService: fanbox\n\n=== Content ===\nbody").unwrap();
        fs::write(post_dir.join(naming.format_links_filename()), b"Title: a title\nPost ID: 12345\nUser ID: artist\nService: fanbox\n\n=== External Links (1) ===\nhttps://example.test").unwrap();
        assert_eq!(
            observe_post_folder(&post_dir, &[]).state,
            OBSERVED_EMPTY,
            "even without the derived-name list, generic helper text files are recognized and not treated as media"
        );
        assert_eq!(
            observe_post_folder(&post_dir, &derived).state,
            OBSERVED_EMPTY,
            "the post's own generated text files are not its media"
        );
        // A source attachment that happens to be a .txt is still a delivery:
        // the exclusion is by exact generated name, not by extension.
        fs::write(
            post_dir.join(naming.format_attachment_filename("notes.txt")),
            b"real attachment",
        )
        .unwrap();
        assert_eq!(
            observe_post_folder(&post_dir, &derived).state,
            OBSERVED_CONTENT
        );
    }

    #[test]
    fn extracted_content_nested_in_a_folder_is_observed() {
        let dir = tempfile::tempdir().unwrap();
        let post_dir = dir.path().join("2026-09-11 a title");
        // What an extracted archive looks like: the zip is gone and a folder
        // stands in its place. This used to read as an empty post.
        fs::create_dir_all(post_dir.join("set/deeper")).unwrap();
        assert_eq!(observe_post_folder(&post_dir, &[]).state, OBSERVED_EMPTY);
        fs::write(post_dir.join("set/deeper/01.jpg"), b"x").unwrap();
        assert_eq!(observe_post_folder(&post_dir, &[]).state, OBSERVED_CONTENT);
    }

    /// A folder written by the historical naming rule must still be recognised
    /// as this post's.
    ///
    /// Measured on the live library: the day folder reads
    /// `2026-07-21 17-302026／7／21 木偶2 8P 差分` — it carries a `HH-MM` segment
    /// the current `{date}` never renders, and keeps the full-width `／` that
    /// `sanitize_path_component` rewrites to `-`. A literal prefix comparison
    /// rejected it, so a folder holding 15 delivered files read as missing and
    /// the work went back to the download queue for a 404.
    #[test]
    fn a_historical_folder_name_still_matches_its_post() {
        let day = "2026-07-21";
        let title = "2026/7/21 木偶2 8P 差分";
        for folder_name in [
            // The current rule.
            "2026-07-21 2026-7-21 木偶2 8P 差分",
            // The historical rule: `{date} {HH-MM}{original title}`, with the
            // original full-width separator preserved.
            "2026-07-21 17-302026／7／21 木偶2 8P 差分",
            // The same name with the separator already folded.
            "2026-07-21 17-302026-7-21 木偶2 8P 差分",
            // No clock segment, but the title kept its own date.
            "2026-07-21 2026／7／21 木偶2 8P 差分",
        ] {
            assert!(
                folder_name_matches_post(folder_name, day, title),
                "{folder_name} is the same work's folder"
            );
        }
    }

    /// The relaxation is the clock segment and the separator, never the numbers
    /// that tell two of one artist's works apart.
    #[test]
    fn a_folder_for_another_work_on_the_same_day_does_not_match() {
        assert!(
            !folder_name_matches_post(
                "2026-07-21 17-302026／7／21 維琳娜3 9P 差分",
                "2026-07-21",
                "2026/7/21 維琳娜2 9P 差分",
            ),
            "9P is the same but the sequence number differs"
        );
        assert!(
            !folder_name_matches_post(
                "2026-07-22 17-302026／7／22 木偶2 8P 差分",
                "2026-07-21",
                "2026/7/21 木偶2 8P 差分",
            ),
            "another day is another folder"
        );
        assert!(
            !folder_name_matches_post("2026-07-210", "2026-07-21", "木偶2"),
            "a longer number is not a day prefix"
        );
        assert!(
            !folder_name_matches_post("", "2026-07-21", "2026/7/21 木偶2 8P 差分"),
            "an empty name matches nothing"
        );
    }

    /// The clock cut is by shape, so a title that opens with a real number keeps
    /// it: `4K 修正版` must not be read as the clock `4K` plus `修正版`.
    #[test]
    fn a_title_starting_with_a_number_keeps_that_number() {
        assert_eq!(strip_leading_clock_segment("17-30木偶2"), "木偶2");
        assert_eq!(strip_leading_clock_segment("17:30 木偶2"), "木偶2");
        assert_eq!(
            strip_leading_clock_segment("4K 修正版"),
            "4K 修正版",
            "no HH-MM boundary to cut at"
        );
        assert_eq!(
            strip_leading_clock_segment("17-302026／7／21 木偶2"),
            "2026／7／21 木偶2"
        );
    }

    /// The date a source title carries is a naming artifact on either side of
    /// the comparison, and the two rules render its month and day differently.
    #[test]
    fn a_leading_date_is_removed_however_wide_its_month_and_day_are() {
        for (raw, want) in [
            ("2026-7-21 木偶2", "木偶2"),
            ("2026/07/21 木偶2", "木偶2"),
            ("20260914 木偶2", "木偶2"),
            ("2026-09 木偶2", "木偶2"),
        ] {
            assert_eq!(normalize_folder_title(raw), want, "raw=[{raw}]");
        }
        // A year alone, a pair of numbers, or a work whose title opens with
        // digits is not a date and keeps its text.
        for raw in ["2026 木偶2", "4K 修正版", "8P 差分", "12345 木偶2"] {
            assert_eq!(
                normalize_folder_title(raw),
                raw.to_lowercase(),
                "raw=[{raw}]"
            );
        }
    }

    /// Either side may carry the date, and only one side may: a post whose title
    /// opens with its source's date has to match a folder name that dropped it,
    /// and the reverse.
    #[test]
    fn a_date_or_clock_prefix_never_hides_a_match() {
        for title in [
            "2026/7/21 木偶2 8P 差分",
            "木偶2 8P 差分",
            "2026-07-21 木偶2 8P 差分",
        ] {
            for folder_name in [
                "2026-07-21 木偶2 8P 差分",
                "2026-07-21 2026-7-21 木偶2 8P 差分",
                "2026-07-21 17-302026／7／21 木偶2 8P 差分",
                "2026-07-21 17-30 木偶2 8P 差分",
            ] {
                assert!(
                    folder_name_matches_post(folder_name, "2026-07-21", title),
                    "post title [{title}] and folder [{folder_name}] are one work"
                );
            }
        }
    }

    /// The pair measured on the development NAS.
    ///
    /// Post `2486` of the `f 飯桶君 ricerice` subscription is titled
    /// `2026/7/21 木偶2 8P 差分`, and the legacy pipeline wrote its 15 files into
    /// `2026-07-21 17-302026／7／21 木偶2 8P 差分`. Before this rule the folder
    /// matched neither the rendered prefix nor a name comparison, so every one of
    /// the 15 candidates was reported `same_day`, the observation read a path that
    /// does not exist, and the finished post was offered for download again.
    #[test]
    fn the_nas_folder_name_that_was_reported_as_missing_matches_again() {
        let day = "2026-07-21";
        let title = "2026/7/21 木偶2 8P 差分";
        let folder = "2026-07-21 17-302026／7／21 木偶2 8P 差分";
        assert!(folder_name_matches_post(folder, day, title));
        // The same work under the other artists' naming, to be sure the day and
        // title are what decide this and not a coincidence of the literals.
        assert!(folder_name_matches_post(
            "2026-07-21 木偶2 8P 差分",
            day,
            title
        ));
        assert!(!folder_name_matches_post(
            "2026-07-21 17-302026／7／21 木偶3 8P 差分",
            day,
            title
        ));
        assert!(!folder_name_matches_post(
            "2026-07-20 17-30木偶2 8P 差分",
            day,
            title
        ));
    }

    /// Classification, not just the name comparison, against the two layouts the
    /// development NAS actually has.
    ///
    /// The unit tests above drive `folder_name_matches_post` directly and passed
    /// while the feature was still broken, because the name comparison was never
    /// the part that failed. What failed was reaching it: `classify` looked for
    /// the folder name one level under `rendered_prefix`'s parent, and that
    /// parent is the artist directory *only* when the saved template's leading
    /// `{user}/` is not already the last segment of `target_dir`. The fanbox
    /// artist's library happens to repeat that segment and the patreon artist's
    /// does not, so one worked and one did not, on the same build.
    #[test]
    fn a_folder_is_recognised_with_or_without_the_repeated_artist_level() {
        let day = "2026-07-21";
        let title = "2026/7/21 木偶2 8P 差分";

        // The measured patreon layout: `target_dir` ends with the artist name and
        // the post's folder sits directly under it, one level deep.
        let scope = PostFolderScope {
            rendered_prefix: "/vol1/artist/f 飯桶君 ricerice/2026-07-21 2026_7_21 木偶2 8P 差分"
                .to_string(),
            artist_dir: "/vol1/artist/f 飯桶君 ricerice".to_string(),
            day: day.to_string(),
            title: title.to_string(),
            post_id: None,
            derived: Vec::new(),
        };
        assert_eq!(
            scope.classify(
                "/vol1/artist/f 飯桶君 ricerice/\
                 2026-07-21 17-302026／7／21 木偶2 8P 差分/飯桶君 2026-07-21 17-30 0.jpeg"
            ),
            "folder",
            "the post's own folder, one level under a single-layer artist directory"
        );

        // The measured fanbox layout: the artist directory repeats, so the
        // post's folder is two levels deep.
        let nested = PostFolderScope {
            rendered_prefix: "/vol1/artist/s 升天/s 升天/2026-07-22 小鳥遊ホシノ& 空崎ヒナ"
                .to_string(),
            artist_dir: "/vol1/artist/s 升天".to_string(),
            day: "2026-07-22".to_string(),
            title: "2026/7/22 小鳥遊ホシノ& 空崎ヒナ".to_string(),
            post_id: None,
            derived: Vec::new(),
        };
        assert_eq!(
            nested.classify(
                "/vol1/artist/s 升天/s 升天/2026-07-22 小鳥遊ホシノ& 空崎ヒナ/\
                 升天 2026-07-22 22-47 1.jpeg"
            ),
            "folder",
            "the post's own folder, two levels under a repeated artist directory"
        );

        // A different work by the same artist on the same day stays a candidate.
        assert_eq!(
            scope.classify(
                "/vol1/artist/f 飯桶君 ricerice/\
                 2026-07-21 17-30別の作品 4P 差分/飯桶君 2026-07-21 17-30 0.jpeg"
            ),
            "same_day",
            "another work on the same day is not this post's folder"
        );
        // And so does a file directly in the artist directory, with no folder.
        assert_eq!(
            scope.classify("/vol1/artist/f 飯桶君 ricerice/loose.jpeg"),
            "same_day"
        );
    }

    /// The observation read has to find the same directory the candidate
    /// classification points at, or the post still reads as missing.
    #[test]
    fn the_observation_finds_a_folder_under_the_artist_directory() {
        fn find(
            artist_dir: &Path,
            user: &str,
            published: &str,
            title: &str,
            service: &str,
        ) -> ResolvedFolder {
            find_alone(artist_dir, user, published, title, service)
        }

        fn find_alone(
            artist_dir: &Path,
            user: &str,
            published: &str,
            title: &str,
            service: &str,
        ) -> ResolvedFolder {
            let ctx =
                PostNamingContext::new(user, Some(published), Some(title), "1", Some(service));
            let day = ctx.date.clone();
            let derived = derived_text_names(&ctx);
            resolve_post_folder(
                &artist_dir.to_string_lossy(),
                &ctx,
                "{user}/{date} {title}/",
                &day,
                &derived,
            )
        }

        let dir = tempfile::tempdir().unwrap();

        // The measured patreon layout: the post's folder is directly in the
        // artist directory, which the rendered path would not have predicted.
        let artist = dir.path().join("f 飯桶君 ricerice");
        let folder = artist.join("2026-07-21 17-302026／7／21 木偶2 8P 差分");
        fs::create_dir_all(&folder).unwrap();
        fs::write(folder.join("0.jpeg"), b"x").unwrap();
        // Another work on the same day, which must not be chosen over it.
        fs::create_dir_all(artist.join("2026-07-21 17-30別の作品 4P 差分")).unwrap();

        let resolved = find(
            &artist,
            "f 飯桶君 ricerice",
            "2026-07-21T07:24:45",
            "2026/7/21 木偶2 8P 差分",
            "patreon",
        );
        assert_eq!(
            resolved.path, folder,
            "the historical folder name must be found"
        );
        assert_eq!(
            resolved.source, FOLDER_FROM_NAME,
            "a folder paired by day and title is recorded as such: it is not \
             where the template says the post's folder is"
        );

        // The repeated-artist layout, one level deeper.
        let nested_root = dir.path().join("s 升天");
        let nested = nested_root.join("s 升天/2026-07-22 小鳥遊ホシノ& 空崎ヒナ");
        fs::create_dir_all(&nested).unwrap();
        assert_eq!(
            find(
                &nested_root,
                "s 升天",
                "2026-07-22T22:47:00+09:00",
                "2026/7/22 小鳥遊ホシノ& 空崎ヒナ",
                "fanbox"
            )
            .path,
            nested,
            "the nested layout must still be found"
        );
    }

    /// A2 — "the folder is not there" has to mean the search looked.
    ///
    /// The resolver skipped a base directory it could not enumerate and fell
    /// through to the rendered template path, which does not exist, so an
    /// unreadable share produced `missing` and an automatic pass fetched the
    /// work again. The search now reports whether it finished, and a `missing`
    /// reading taken from an unfinished one is unknown.
    #[test]
    fn a_missing_reading_from_an_unfinished_search_is_unknown() {
        let missing = FolderObservation {
            state: OBSERVED_MISSING,
            files: 0,
        };
        let finished = ResolvedFolder::new(
            PathBuf::from("/none/2026-01-01 a"),
            FOLDER_FROM_TEMPLATE,
            false,
            missing,
        );
        assert_eq!(
            observation_after_search(missing, &finished).state,
            OBSERVED_MISSING,
            "a search that read every directory it needed may report absent"
        );
        let unfinished = ResolvedFolder {
            incomplete: true,
            ..finished
        };
        assert_eq!(
            observation_after_search(missing, &unfinished).state,
            OBSERVED_UNREADABLE,
            "a search that could not read a directory has not shown absence"
        );
        // The other readings are facts about the folder, not about the search,
        // so an unfinished search must not overwrite them.
        let content = FolderObservation {
            state: OBSERVED_CONTENT,
            files: 3,
        };
        assert_eq!(
            observation_after_search(content, &unfinished).state,
            OBSERVED_CONTENT,
            "content that was really read stays content"
        );
    }

    /// A2 — an absent directory is a complete answer, not a hole.
    ///
    /// If a directory that does not exist yet counted as an unreadable one, the
    /// first download of every new artist would be blocked by the unknown rule:
    /// there is nothing on disk and the search did in fact finish. The counter-
    /// example to the fix above, and the reason `list_subdirectories` separates
    /// the three answers instead of collapsing them into "could not list".
    #[test]
    fn an_absent_directory_is_a_complete_answer_not_a_hole_in_the_search() {
        let dir = tempfile::tempdir().unwrap();

        let absent = dir.path().join("no-such-artist");
        let (found, complete) = list_subdirectories(&absent);
        assert!(found.is_empty());
        assert!(complete, "an absent directory is not an unreadable one");

        let present = dir.path().join("artist");
        fs::create_dir_all(present.join("2026-01-01 a")).unwrap();
        let (found, complete) = list_subdirectories(&present);
        assert_eq!(found.len(), 1);
        assert!(complete, "a directory that was read is complete");

        // A file where a directory should be holds no subdirectories, and it is
        // not a permission failure either.
        let file = dir.path().join("a-file");
        fs::write(&file, b"x").unwrap();
        let (found, complete) = list_subdirectories(&file);
        assert!(found.is_empty());
        assert!(complete);
    }

    /// A2 — a round that could not read is not a round that read nothing.
    ///
    /// The round used to answer `(0, false)` for both "the library has nothing
    /// to observe" and "the query never ran", and a caller reassessing
    /// subscriptions off that would present a silence as a completed check.
    #[test]
    fn an_observation_round_that_could_not_read_reports_failure() {
        let dir = tempfile::tempdir().unwrap();
        let pool = Arc::new(
            crate::db::DbPool::with_config(
                dir.path().join("gallery.db"),
                crate::db::DbConfig {
                    read_only: false,
                    pool_size: 1,
                },
            )
            .unwrap(),
        );
        {
            let conn = pool.get().unwrap();
            // Taking the table away makes the round's query fail, which is the
            // cheapest honest reproduction. It is also the shape of the real
            // failure: a query that never ran, not a library with nothing in it.
            let _ = conn.execute_batch("DROP TABLE kemono_posts");
        }
        assert!(
            matches!(observe_post_folders(&pool, None), ObserveRound::Failed),
            "a round whose query failed must not report an empty completed library"
        );
    }

    /// C7 — the search hands back what it already read.
    ///
    /// The resolver has to open every candidate to classify it, so by the time
    /// it picks a path the reading exists. It used to be thrown away and the
    /// caller re-observed the chosen path, traversing the same directory twice
    /// per post per round. The reading must now travel with the path, and it
    /// must be the *raw* reading: whether an unfinished search may report
    /// absence stays a decision the caller makes through
    /// `observation_after_search`.
    #[test]
    fn the_search_returns_the_reading_it_took() {
        fn resolve_with(
            artist_dir: &Path,
            published: &str,
            title: &str,
            template: &str,
        ) -> ResolvedFolder {
            let ctx =
                PostNamingContext::new("artist", Some(published), Some(title), "1", Some("fanbox"));
            let day = ctx.date.clone();
            let derived = derived_text_names(&ctx);
            resolve_post_folder(
                &artist_dir.to_string_lossy(),
                &ctx,
                template,
                &day,
                &derived,
            )
        }

        fn resolve(artist_dir: &Path, published: &str, title: &str) -> ResolvedFolder {
            resolve_with(artist_dir, published, title, "{date} {title}/")
        }

        let dir = tempfile::tempdir().unwrap();
        let artist = dir.path().join("artist");
        fs::create_dir_all(&artist).unwrap();

        // A day folder whose name also carries the title: `named` wins over the
        // day fallback, because a name match is the stronger evidence. What
        // matters here is that the reading travelled back with the path.
        let day_dir = artist.join("2026-03-04 12-00 a title");
        fs::create_dir_all(&day_dir).unwrap();
        fs::write(day_dir.join("1.png"), b"x").unwrap();
        let resolved = resolve(&artist, "2026-03-04T12:00:00+00:00", "2026/3/4 a title");
        assert_eq!(resolved.observation.state, OBSERVED_CONTENT);
        assert_eq!(resolved.observation.files, 1, "the file count travels too");
        assert_eq!(resolved.source, FOLDER_FROM_NAME);

        // The fallback branch: the rendered path exists and is empty, and no
        // candidate is a name match for the post. The reading the search took is
        // `empty`, and a caller that re-derived it from the fallback path would
        // report absence instead. The `{date}`-only template is what keeps the
        // name rule out of the way so this branch is actually reached.
        let empty_artist = dir.path().join("empty-artist");
        fs::create_dir_all(empty_artist.join("2026-03-05")).unwrap();
        let resolved = resolve_with(
            &empty_artist,
            "2026-03-05T12:00:00+00:00",
            "2026/3/5 b title",
            "{date}",
        );
        assert_eq!(
            resolved.observation.state, OBSERVED_EMPTY,
            "a directory that exists and was read is empty, not missing"
        );
        assert_eq!(resolved.source, FOLDER_FROM_TEMPLATE);

        // Nothing on disk at all: a genuine absence.
        let absent_artist = dir.path().join("absent-artist");
        fs::create_dir_all(&absent_artist).unwrap();
        let resolved = resolve(
            &absent_artist,
            "2026-03-06T12:00:00+00:00",
            "2026/3/6 c title",
        );
        assert_eq!(resolved.observation.state, OBSERVED_MISSING);
        assert_eq!(resolved.source, FOLDER_FROM_TEMPLATE);
    }

    /// C7 — an unfinished search still cannot turn its own reading into absence.
    ///
    /// Returning the reading must not let the resolver skip the search-quality
    /// rule: a `missing` reading taken from a search that could not finish is
    /// unknown, and that is decided after the reading comes back.
    #[test]
    fn a_returned_missing_reading_is_still_subject_to_the_search_rule() {
        let missing = FolderObservation {
            state: OBSERVED_MISSING,
            files: 0,
        };
        let unfinished = ResolvedFolder::new(
            PathBuf::from("/none/2026-01-01 a"),
            FOLDER_FROM_TEMPLATE,
            true,
            missing,
        );
        assert_eq!(
            observation_after_search(unfinished.observation, &unfinished).state,
            OBSERVED_UNREADABLE,
            "a reading that travelled back through an unfinished search is unknown"
        );

        let content = FolderObservation {
            state: OBSERVED_CONTENT,
            files: 2,
        };
        let finished = ResolvedFolder::new(
            PathBuf::from("/none/2026-01-01 a"),
            FOLDER_FROM_DAY,
            false,
            content,
        );
        assert_eq!(
            observation_after_search(finished.observation, &finished).state,
            OBSERVED_CONTENT,
            "a real reading survives the rule unchanged"
        );
    }

    /// The measured case: the source renamed the work after it was downloaded,
    /// so the folder keeps the Japanese title it was written with while the post
    /// now carries a romanised one, and no title comparison can ever pair them.
    #[test]
    fn the_day_settles_a_folder_the_source_has_since_renamed() {
        fn resolve(artist_dir: &Path, published: &str, title: &str) -> ResolvedFolder {
            let ctx = PostNamingContext::new(
                "f 飯桶君 ricerice",
                Some(published),
                Some(title),
                "1",
                Some("patreon"),
            );
            let day = ctx.date.clone();
            let derived = derived_text_names(&ctx);
            resolve_post_folder(
                &artist_dir.to_string_lossy(),
                &ctx,
                "{user}/{date} {title}/",
                &day,
                &derived,
            )
        }

        let dir = tempfile::tempdir().unwrap();
        let artist = dir.path().join("f 飯桶君 ricerice");

        // post 2755: the post says `Raiden 4 R18 @3`, the folder on disk says
        // `將軍OL 4 R18 差分 @3`, and it is the only folder under the day.
        let raiden = artist.join("2022-05-13 18-482022／5／13 將軍OL 4 R18 差分 @3");
        fs::create_dir_all(&raiden).unwrap();
        fs::write(raiden.join("飯桶君 2022-05-13 18-48 1.png"), b"x").unwrap();
        let resolved = resolve(
            &artist,
            "2022-05-13T11:40:23+00:00",
            "2022/5/13 Raiden 4 R18 @3",
        );
        assert_eq!(
            resolved.path, raiden,
            "the day's only folder is this post's, whatever the source renamed it to"
        );
        assert_eq!(
            resolved.source, FOLDER_FROM_DAY,
            "a folder found by the day alone is recorded as such, so a later fix \
             to that search can still reach this post"
        );

        // post 2758, the same shape one month earlier.
        let nun = artist.join("2022-04-16 19-002022／4／16 シスター將軍  R18 差分 @3 祼足啦");
        fs::create_dir_all(&nun).unwrap();
        fs::write(nun.join("1.png"), b"x").unwrap();
        assert_eq!(
            resolve(
                &artist,
                "2022-04-16T11:27:25+00:00",
                "2022/4/9 Raiden nun R18 @3",
            )
            .path,
            nun,
            "a renamed work is still settled by its day"
        );

        // Under the date content rule, sharing a day with a sibling does not reject the folder.
        assert!(
            resolve(
                &artist,
                "2022-05-13T11:40:23+00:00",
                "2022/5/13 Raiden 4 R18 @3",
            )
            .path
            .is_dir(),
            "a post with a sibling on its day can claim the day's folder with content"
        );

        // Two folders on the day: any folder with content on that day satisfies the date content rule.
        let other = artist.join("2022-05-13 18-482022／5／13 別の作品 4P 差分");
        fs::create_dir_all(&other).unwrap();
        fs::write(other.join("1.png"), b"x").unwrap();
        assert!(
            resolve(
                &artist,
                "2022-05-13T11:40:23+00:00",
                "2022/5/13 Raiden 4 R18 @3",
            )
            .path
            .is_dir(),
            "folders with content on the day settle the day"
        );
        fs::remove_dir_all(&other).unwrap();

        // An empty folder of the right day is something this side created and
        // never filled. Answering with it would report "empty" over a real gap.
        fs::remove_dir_all(&raiden).unwrap();
        fs::create_dir_all(&raiden).unwrap();
        assert!(
            !resolve(
                &artist,
                "2022-05-13T11:40:23+00:00",
                "2022/5/13 Raiden 4 R18 @3",
            )
            .path
            .is_dir(),
            "an empty folder is not content and must not stand in"
        );
    }

    /// Under Section 9 date policy, a folder on the day with content settles the day
    /// even if its title was derived from another post.
    #[test]
    fn a_day_folder_named_after_a_sibling_post_is_never_this_posts() {
        fn resolve(artist_dir: &Path, published: &str, title: &str) -> ResolvedFolder {
            let ctx = PostNamingContext::new(
                "f 飯桶君 ricerice",
                Some(published),
                Some(title),
                "1",
                Some("patreon"),
            );
            let day = ctx.date.clone();
            let derived = derived_text_names(&ctx);
            resolve_post_folder(
                &artist_dir.to_string_lossy(),
                &ctx,
                "{user}/{date} {title}/",
                &day,
                &derived,
            )
        }

        let dir = tempfile::tempdir().unwrap();
        let artist = dir.path().join("f 飯桶君 ricerice");

        // post 2520 sits on 2026-01-01, and the only folder of that day is the
        // one post 2517's title names — 2517's own day moved to 2026-01-19 when
        // the source redated it, while the folder kept the day it was written
        // under.
        let neighbour = artist.join("2026-01-01 18-482026／1／1 大理花R18 6P 差分");
        fs::create_dir_all(&neighbour).unwrap();
        fs::write(neighbour.join("0.jpeg"), b"x").unwrap();

        let resolved = resolve(&artist, "2026-01-01T10:00:00+00:00", "2026/1/1 月城柳");
        assert_eq!(
            resolved.path, neighbour,
            "under date policy, a content folder on the day settles the day even if named after another title"
        );
        assert_eq!(
            resolved.source, FOLDER_FROM_DAY,
            "the day folder source is returned"
        );

        // The same folder still answers for a post no sibling names it after:
        // the guard must not withdraw the renamed-work reading it protects.
        assert_eq!(
            resolve(&artist, "2026-01-01T10:00:00+00:00", "2026/1/1 月城柳",).path,
            neighbour,
            "a day folder no sibling is named after still settles the post"
        );
    }

    #[test]
    fn only_a_whole_day_prefix_names_the_day() {
        assert!(folder_name_starts_with_day("2026-07-21", "2026-07-21"));
        assert!(folder_name_starts_with_day(
            "2026-07-21 17-302026／7／21 木偶2",
            "2026-07-21"
        ));
        assert!(folder_name_starts_with_day(
            "2026-07-21 木偶2",
            "2026-07-21"
        ));
        assert!(
            !folder_name_starts_with_day("2026-07-210", "2026-07-21"),
            "a longer date is a different day, not this one"
        );
        assert!(
            !folder_name_starts_with_day("2026-07-02 木偶2", "2026-07-21"),
            "a different day is not this day"
        );
        assert!(
            !folder_name_starts_with_day("2026-07-212", "2026-07-21"),
            "a digit straight after the day is a different day"
        );
    }

    #[test]
    fn a_name_match_alone_must_not_settle_a_post() {
        // Guard against the rule that shipped in 1.0.349 and was withdrawn: it
        // matched a post's source file names against every file anywhere under
        // the artist folder. One measured creator has a file name shared by 21
        // posts, so that settled posts which were never downloaded.
        let dir = tempfile::tempdir().unwrap();
        let artist_dir = dir.path().join("artist");
        let other_post = artist_dir.join("2026-01-01 someone else");
        fs::create_dir_all(&other_post).unwrap();
        fs::write(other_post.join("0.jpeg"), b"x").unwrap();

        let this_post = artist_dir.join("2026-09-11 a title");
        assert_eq!(
            observe_post_folder(&this_post, &[]).state,
            OBSERVED_MISSING,
            "a sibling folder holding the same file name must not count for this post"
        );
        fs::create_dir_all(&this_post).unwrap();
        assert_eq!(
            observe_post_folder(&this_post, &[]).state,
            OBSERVED_EMPTY,
            "an empty folder stays empty no matter what its siblings hold"
        );
    }

    #[test]
    fn date_variants_and_starts_with_day_support_all_naming_conventions() {
        let day = "2026-04-21";
        // Standard ISO hyphen
        assert!(folder_name_starts_with_day("2026-04-21 银狼", day));
        assert!(folder_name_starts_with_day("2026-04-21", day));
        // Underscore separator
        assert!(folder_name_starts_with_day("2026_04_21 银狼", day));
        assert!(folder_name_starts_with_day("2026_04_21_银狼", day));
        // Dot separator
        assert!(folder_name_starts_with_day("2026.04.21 银狼", day));
        // Compact 8-digit
        assert!(folder_name_starts_with_day("20260421 银狼", day));
        assert!(folder_name_starts_with_day("20260421", day));
        // Unpadded month / day
        assert!(folder_name_starts_with_day("2026-4-21 银狼", day));
        assert!(folder_name_starts_with_day(
            "2026_4_21 銀狼R18 6P 差分",
            day
        ));
        assert!(folder_name_starts_with_day("2026.4.21 银狼", day));
        // Bracketed date
        assert!(folder_name_starts_with_day("[2026-04-21] 银狼", day));
        assert!(folder_name_starts_with_day("(2026-04-21) 银狼", day));
        // Chinese date characters
        assert!(folder_name_starts_with_day("2026年4月21日 银狼", day));
        assert!(folder_name_starts_with_day("2026年04月21日 银狼", day));

        // Negative cases
        assert!(!folder_name_starts_with_day("2026-04-210", day));
        assert!(!folder_name_starts_with_day("2026-04-212 银狼", day));
        assert!(!folder_name_starts_with_day("2026-04-20 银狼", day));
        assert!(!folder_name_starts_with_day("2025-04-21 银狼", day));
    }

    #[test]
    fn folder_entry_matches_post_with_id_and_date_variants() {
        let day = "2026-04-21";
        let title = "2026_4_21 銀狼R18 6P 差分";
        let post_id = "156178527";

        // Exact match via post_id in brackets or delimiters
        assert!(folder_entry_matches_post(
            "[156178527] 银狼",
            day,
            title,
            Some(post_id),
            &[]
        ));
        assert!(folder_entry_matches_post(
            "2026-04-21 156178527 银狼",
            day,
            title,
            Some(post_id),
            &[]
        ));
        assert!(folder_entry_matches_post(
            "post_156178527",
            day,
            title,
            Some(post_id),
            &[]
        ));

        // Negative: short post_id (< 4 chars) does not do fuzzy match
        assert!(!folder_entry_matches_post(
            "2026-01-01 someone",
            day,
            title,
            Some("1"),
            &[]
        ));
    }

    #[test]
    fn intelligent_container_resolution_finds_archived_post_and_prefers_content() {
        let dir = tempfile::tempdir().unwrap();
        let target_dir = dir.path().join("f 飯桶君 ricerice");
        fs::create_dir_all(&target_dir).unwrap();

        // 1. Archived post in `2026/2026-04-21 银狼` with real media files
        let archived_post = target_dir.join("2026/2026-04-21 银狼");
        fs::create_dir_all(&archived_post).unwrap();
        for i in 0..6 {
            fs::write(archived_post.join(format!("{i}.jpg")), b"image_data").unwrap();
        }

        // 2. Download template path in `f 飯桶君 ricerice/2026-04-21 2026_4_21 銀狼R18 6P 差分`
        // which only contains helper text files (OBSERVED_EMPTY)
        let download_post =
            target_dir.join("f 飯桶君 ricerice/2026-04-21 2026_4_21 銀狼R18 6P 差分");
        fs::create_dir_all(&download_post).unwrap();
        fs::write(download_post.join("content 156178527.txt"), b"Title: title\nPost ID: 156178527\nUser ID: artist\nService: patreon\n\n=== Content ===\nmetadata").unwrap();
        fs::write(download_post.join("links 156178527.txt"), b"Title: title\nPost ID: 156178527\nUser ID: artist\nService: patreon\n\n=== External Links (1) ===\nhttps://example.test").unwrap();

        let ctx = PostNamingContext::new(
            "f 飯桶君 ricerice",
            Some("2026-04-21T12:00:00+00:00"),
            Some("2026_4_21 銀狼R18 6P 差分"),
            "156178527",
            Some("patreon"),
        );
        let derived = derived_text_names(&ctx);

        let resolved = resolve_post_folder(
            &target_dir.to_string_lossy(),
            &ctx,
            "{user}/{date} {title}/",
            &ctx.date,
            &derived,
        );

        // The resolver must discover the media-holding archived folder in `2026/2026-04-21 银狼`
        // rather than stopping at the empty download folder!
        assert_eq!(resolved.path, archived_post);
        assert_eq!(resolved.observation.state, OBSERVED_CONTENT);
        assert_eq!(resolved.observation.files, 6);
        assert_eq!(resolved.source, FOLDER_FROM_DAY);
    }

