    #[test]
    fn publish_post_text_files_respects_download_toggles() {
        let dir = tempfile::tempdir().unwrap();
        let roots = MediaRoots::identical(
            vec![dir.path().to_string_lossy().to_string()],
            vec!["Media".to_string()],
        );
        let target_dir = dir.path().join("artist/post");
        fs::create_dir_all(&target_dir).unwrap();

        let post = PawchivePost {
            id: "99999".to_string(),
            user: "creator".to_string(),
            service: "fanbox".to_string(),
            title: Some("Test Post".to_string()),
            content: Some("Here is content and https://mega.nz/file/12345#secret".to_string()),
            published: Some("2026-04-21T12:00:00".to_string()),
            added: None,
            edited: None,
            file: None,
            attachments: Vec::new(),
            attachments_present: true,
            file_present: true,
            content_present: true,
            has_full: None,
        };
        let naming = PostNamingContext::new(
            &post.user,
            post.published.as_deref(),
            post.title.as_deref(),
            &post.id,
            Some(&post.service),
        );

        // 1. Both disabled
        let pub_none =
            publish_post_text_files(&target_dir, &post, &naming, &roots, false, false).unwrap();
        assert_eq!(pub_none.len(), 0);
        assert!(!target_dir.join(naming.format_content_filename()).exists());
        assert!(!target_dir.join(naming.format_links_filename()).exists());

        // 2. Only content enabled
        let pub_content =
            publish_post_text_files(&target_dir, &post, &naming, &roots, true, false).unwrap();
        assert_eq!(pub_content.len(), 1);
        assert!(target_dir.join(naming.format_content_filename()).exists());
        assert!(!target_dir.join(naming.format_links_filename()).exists());

        // 3. Only links enabled
        let pub_links =
            publish_post_text_files(&target_dir, &post, &naming, &roots, false, true).unwrap();
        assert_eq!(pub_links.len(), 1);
        assert!(target_dir.join(naming.format_links_filename()).exists());
    }

    #[test]
    fn coverage_ignores_days_before_the_subscription_start() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures1/artist", None)
                .unwrap();
        for (post_id, day) in [("old", "2024-01-05"), ("fresh", "2025-06-01")] {
            let id = insert_test_post(&conn, sub_id, post_id);
            conn.execute(
                "UPDATE kemono_posts SET published_at = ?1 WHERE id = ?2",
                params![format!("{day}T00:00:00"), id],
            )
            .unwrap();
        }
        assert_eq!(
            refresh_subscription_coverage(&conn, sub_id).unwrap().len(),
            2
        );

        conn.execute(
            "UPDATE kemono_subscriptions SET since_date = '2025-01-01' WHERE id = ?1",
            params![sub_id],
        )
        .unwrap();
        let coverage = refresh_subscription_coverage(&conn, sub_id).unwrap();
        assert_eq!(
            coverage.len(),
            1,
            "rows before the start date are not reported"
        );
        assert_eq!(coverage[0].day, "2025-06-01");
        assert_eq!(pending_coverage_day_count(&conn, sub_id).unwrap(), 1);
    }

    #[test]
    fn a_check_round_summarises_gap_days_without_downloading() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures1/artist", None)
                .unwrap();
        let first = insert_test_post(&conn, sub_id, "1");
        conn.execute(
            "UPDATE kemono_posts SET published_at = '2026-09-11T00:00:00' WHERE id = ?1",
            params![first],
        )
        .unwrap();
        for (identity, status) in [("a", "done"), ("b", "pending")] {
            conn.execute(
                "INSERT INTO kemono_files
                     (post_id, source_identity, remote_path, file_name, file_type, status, created_at, updated_at)
                 VALUES (?1, ?2, ?3, ?3, 'image', ?4, 't', 't')",
                params![first, identity, format!("{identity}.png"), status],
            )
            .unwrap();
        }

        let pending = pending_coverage_days(&conn, sub_id).unwrap();
        assert_eq!(pending.len(), 1);
        assert_eq!(coverage_gap_summary(&pending), "2026-09-11 缺 1 个");
        assert!(coverage_gap_summary(&[]).is_empty());
        assert_eq!(pending_coverage_day_count(&conn, sub_id).unwrap(), 1);

        // Only a check skips the download phase; every other trigger keeps it.
        // The slot itself is asserted in `pawchive_sync_slot_is_single_flight`,
        // which owns that process-wide state.
        assert!(!SyncTrigger::Check.downloads());
        assert!(SyncTrigger::Manual.downloads());
        assert!(SyncTrigger::Scheduled.downloads());
        assert_eq!(SyncTrigger::Check.as_str(), "check");
    }

    #[test]
    fn the_reported_gap_count_is_not_capped_by_the_coverage_window() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures1/artist", None)
                .unwrap();

        // A long history must be reported in full. An earlier cap here made the
        // payload stop at the window size, so a backlog larger than the cap
        // reported exactly the cap — a truncation wearing the clothes of a
        // measurement.
        let day_count = 405;
        let base = chrono::NaiveDate::from_ymd_opt(2024, 1, 1).unwrap();
        for offset in 0..day_count {
            let day = base + chrono::Duration::days(offset as i64);
            let post_id = insert_test_post(&conn, sub_id, &format!("p{offset}"));
            conn.execute(
                "UPDATE kemono_posts SET published_at = ?1 WHERE id = ?2",
                params![format!("{day}T00:00:00"), post_id],
            )
            .unwrap();
        }

        let listed = pending_coverage_days(&conn, sub_id).unwrap();
        assert_eq!(
            listed.len(),
            day_count,
            "every day in the ledger is listed, not a truncated window"
        );
        assert_eq!(
            pending_coverage_day_count(&conn, sub_id).unwrap(),
            day_count
        );

        // Completing one day drops the exact count; already-downloaded days are
        // never counted, so an empty backlog reads zero rather than one.
        conn.execute(
            "UPDATE kemono_posts SET assessment_state = 'verified' WHERE post_id = 'p0'",
            [],
        )
        .unwrap();
        assert_eq!(
            pending_coverage_day_count(&conn, sub_id).unwrap(),
            day_count - 1
        );

        let empty =
            upsert_subscription(&conn, "fanbox", "1", None, "/pictures1/none", None).unwrap();
        assert_eq!(pending_coverage_day_count(&conn, empty).unwrap(), 0);
    }

    #[test]
    fn coverage_scores_days_by_post_not_by_file_row() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures1/artist", None)
                .unwrap();

        // Day one: the post is settled, so the day is covered even though it
        // still carries a file row that is not required any more — the leftover
        // rows of a type this install no longer fetches, or of an archive that
        // was extracted away, must not pin the day open. The state is written
        // by the evaluator, which is the only thing that decides it.
        let first = insert_test_post(&conn, sub_id, "1");
        conn.execute(
            "UPDATE kemono_posts SET published_at = '2026-09-10T00:00:00', assessment_state = 'verified' WHERE id = ?1",
            params![first],
        )
        .unwrap();
        insert_test_file(&conn, first, "0", "a.png", "image", "done");
        insert_test_file(&conn, first, "1", "b.zip", "archive", "pending");

        // Day two: two posts, one still open, so the day is a gap.
        let second = insert_test_post(&conn, sub_id, "2");
        let third = insert_test_post(&conn, sub_id, "3");
        for (id, state) in [(second, "verified"), (third, "pending")] {
            conn.execute(
                "UPDATE kemono_posts SET published_at = '2026-09-11T00:00:00', assessment_state = ?2 WHERE id = ?1",
                params![id, state],
            )
            .unwrap();
        }

        let coverage = refresh_subscription_coverage(&conn, sub_id).unwrap();
        assert_eq!(coverage.len(), 2);
        assert_eq!(coverage[0].day, "2026-09-11");
        assert_eq!(coverage[0].total_posts, 2);
        assert_eq!(coverage[0].downloaded_posts, 1);
        assert!(!coverage[0].complete());
        assert_eq!(coverage[1].day, "2026-09-10");
        assert!(coverage[1].complete(), "a settled post covers its day");

        let pending = pending_coverage_days(&conn, sub_id).unwrap();
        assert_eq!(pending.len(), 1);
        assert_eq!(pending[0].day, "2026-09-11");
        assert_eq!(coverage_gap_summary(&pending), "2026-09-11 缺 1 个");

        let record = get_subscription(&conn, sub_id).unwrap().unwrap();
        assert_eq!(record.coverage.len(), 2);
        assert!(!subscription_days_complete(&record.coverage));

        // Settling the last post closes the day, and no file row was touched.
        conn.execute(
            "UPDATE kemono_posts SET assessment_state = 'verified' WHERE post_id = '3'",
            [],
        )
        .unwrap();
        let coverage = refresh_subscription_coverage(&conn, sub_id).unwrap();
        assert!(subscription_days_complete(&coverage));
        assert!(pending_coverage_days(&conn, sub_id).unwrap().is_empty());
        assert!(pending_coverage_day_count(&conn, sub_id).unwrap() == 0);
    }

    /// One subscription plus one post, for the evaluator tests.
    fn evaluator_fixture() -> (Connection, i64, i64) {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures1/artist", None)
                .unwrap();
        let post_db_id = insert_test_post(&conn, sub_id, "900");
        (conn, sub_id, post_db_id)
    }

    /// Mark an observed folder state on one post.
    fn set_observed(conn: &Connection, post_db_id: i64, state: &str, files: i64) {
        conn.execute(
            "UPDATE kemono_posts SET observed_state = ?1, observed_files = ?2 WHERE id = ?3",
            params![state, files, post_db_id],
        )
        .unwrap();
    }

    /// Record how the folder that was read was chosen. Left alone, a row reads
    /// as one written before the column existed, which is the shape the sweep
    /// has to cope with on an upgraded database.
    fn set_observed_source(conn: &Connection, post_db_id: i64, source: &str) {
        conn.execute(
            "UPDATE kemono_posts SET observed_source = ?1 WHERE id = ?2",
            params![source, post_db_id],
        )
        .unwrap();
    }

    /// Give one asset a delivery receipt of the given strength.
    fn set_evidence(conn: &Connection, post_db_id: i64, path: &str, source: &str) {
        conn.execute(
            "UPDATE kemono_files SET delivery_source = ?1, status = 'done'
             WHERE post_id = ?2 AND source_identity = ?3",
            params![source, post_db_id, path],
        )
        .unwrap();
    }

    fn settings_with(archives: bool) -> PawchiveSettings {
        PawchiveSettings {
            download_archives: archives,
            ..PawchiveSettings::default()
        }
    }

    /// A folder holding only the post's own generated text files is not a
    /// download. This is the defect that let `publish_post_text_files` settle a
    /// whole post — media never fetched, day reported as complete.
    #[test]
    fn generated_text_files_alone_do_not_settle_a_post() {
        let (conn, _, post) = evaluator_fixture();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "pending");
        set_observed(&conn, post, OBSERVED_EMPTY, 0);

        let assessment = assess_post(&conn, post, &PawchiveSettings::default()).unwrap();
        assert_eq!(assessment.state, PostState::Pending);
        assert_eq!(assessment.missing_assets, 1);
        assert!(assessment.state.is_claimable());
        assert!(!assessment.state.is_settled());
    }

    /// A day that belongs to this post alone, whose folder holds files, counts
    /// as had: the date folder is where this post's delivery lands and nothing
    /// else could own what is in it. Presence is the rule the user asked for,
    /// and it must not be re-fetched.
    #[test]
    fn an_unshared_day_folder_counts_as_had() {
        let (conn, _, post) = evaluator_fixture();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "pending");
        set_observed(&conn, post, OBSERVED_CONTENT, 1);

        let assessment = assess_post(&conn, post, &PawchiveSettings::default()).unwrap();
        assert_eq!(assessment.state, PostState::Verified, "{assessment:?}");
        assert!(!assessment.state.is_claimable(), "must not re-download it");
        assert!(
            assessment.state.is_settled(),
            "a lone day folder counts as had"
        );
        assert_eq!(assessment.reason, "日期目录存在，按已下载计入");
    }

    /// The same lone day folder, on a post whose every resource is still
    /// waiting out a retry backoff. Nothing is claimable, so the download side
    /// has nothing left to say — but the folder is on disk, and that is the
    /// proof. This is the NAS case: the source 404s the originals, every asset
    /// is deferred, and the post used to read `unavailable` with its folder
    /// sitting right there.
    #[test]
    fn a_folder_still_counts_as_had_while_every_asset_waits_out_a_backoff() {
        let (conn, _, post) = evaluator_fixture();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "pending");
        set_observed(&conn, post, OBSERVED_CONTENT, 1);
        // No delivery receipt, no address ever obtained, backoff not yet due —
        // the exact shape `deferred_assets` counts.
        conn.execute(
            "UPDATE kemono_files
             SET delivery_source = '', next_attempt_at = '2999-01-01T00:00:00+00:00'
             WHERE post_id = ?1",
            params![post],
        )
        .unwrap();

        let assessment = assess_post(&conn, post, &PawchiveSettings::default()).unwrap();
        assert_eq!(assessment.deferred_assets, 1, "the asset is deferred");
        assert_eq!(assessment.missing_assets, 0, "and nothing is claimable");
        assert_eq!(
            assessment.state,
            PostState::Verified,
            "a backoff must not hide the folder: {assessment:?}"
        );
        assert!(!assessment.state.is_claimable(), "must not re-download it");
        assert!(
            assessment.state.is_settled(),
            "the folder still counts as had"
        );
        assert_eq!(assessment.reason, "日期目录存在，按已下载计入");
    }

    /// A shared day stays a question even when every asset is deferred: the
    /// backoff rule is not allowed to answer what the ambiguity rule refuses.
    #[test]
    fn a_shared_day_is_still_ambiguous_while_every_asset_waits_out_a_backoff() {
        let (conn, _, post) = evaluator_fixture();
        let subscription_id: i64 = conn
            .query_row(
                "SELECT subscription_id FROM kemono_posts WHERE id = ?1",
                params![post],
                |row| row.get(0),
            )
            .unwrap();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "pending");
        set_observed(&conn, post, OBSERVED_CONTENT, 1);
        let sibling = insert_test_post(&conn, subscription_id, "p-sibling");
        conn.execute(
            "UPDATE kemono_posts
             SET published_at = (SELECT published_at FROM kemono_posts WHERE id = ?1)
             WHERE id = ?2",
            params![post, sibling],
        )
        .unwrap();
        conn.execute(
            "UPDATE kemono_files
             SET delivery_source = '', next_attempt_at = '2999-01-01T00:00:00+00:00'
             WHERE post_id = ?1",
            params![post],
        )
        .unwrap();

        let assessment = assess_post(&conn, post, &PawchiveSettings::default()).unwrap();
        assert_eq!(assessment.deferred_assets, 1);
        assert_eq!(assessment.state, PostState::Verified, "{assessment:?}");
        assert!(!assessment.state.is_claimable(), "must not re-download it");
        assert!(
            assessment.state.is_settled(),
            "date folder with content settles the post"
        );
        assert_eq!(assessment.reason, "日期目录存在，按已下载计入");
    }

    /// With no folder to stand on, a fully deferred post still reports the
    /// backoff rather than claiming anything about delivery.
    #[test]
    fn a_deferred_post_without_a_folder_still_reports_the_backoff() {
        let (conn, _, post) = evaluator_fixture();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "pending");
        set_observed(&conn, post, OBSERVED_MISSING, 0);
        conn.execute(
            "UPDATE kemono_files
             SET delivery_source = '', next_attempt_at = '2999-01-01T00:00:00+00:00'
             WHERE post_id = ?1",
            params![post],
        )
        .unwrap();

        let assessment = assess_post(&conn, post, &PawchiveSettings::default()).unwrap();
        assert_eq!(assessment.state, PostState::Unavailable, "{assessment:?}");
        assert_eq!(assessment.reason, "1 个文件暂时取不到，稍后重试");
    }

    /// Under Section 9 date policy, content on disk settles the date even when multiple
    /// posts share the day; without date content on disk, the ambiguity requires human review.
    #[test]
    fn a_shared_day_folder_is_handed_to_a_human() {
        let (conn, _, post) = evaluator_fixture();
        let subscription_id: i64 = conn
            .query_row(
                "SELECT subscription_id FROM kemono_posts WHERE id = ?1",
                params![post],
                |row| row.get(0),
            )
            .unwrap();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "pending");
        set_observed(&conn, post, OBSERVED_CONTENT, 1);
        // A sibling post on the same day, same artist.
        let sibling = insert_test_post(&conn, subscription_id, "p-sibling");
        conn.execute(
            "UPDATE kemono_posts
             SET published_at = (SELECT published_at FROM kemono_posts WHERE id = ?1)
             WHERE id = ?2",
            params![post, sibling],
        )
        .unwrap();

        let assessment = assess_post(&conn, post, &PawchiveSettings::default()).unwrap();
        assert_eq!(assessment.state, PostState::Verified, "{assessment:?}");
        assert!(!assessment.state.is_claimable(), "must not re-download it");
        assert!(
            assessment.state.is_settled(),
            "date folder with content settles the post"
        );
        assert_eq!(assessment.reason, "日期目录存在，按已下载计入");
    }

    /// When the folders on disk match the posts one for one, the pairing is
    /// unambiguous and the count settles the day: each post got its own folder.
    /// Only a shortfall — folders shared between works — still needs a human.
    #[test]
    fn matching_folder_count_settles_a_shared_day() {
        let (conn, _, post) = evaluator_fixture();
        let subscription_id: i64 = conn
            .query_row(
                "SELECT subscription_id FROM kemono_posts WHERE id = ?1",
                params![post],
                |row| row.get(0),
            )
            .unwrap();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "pending");
        set_observed(&conn, post, OBSERVED_CONTENT, 1);
        let sibling = insert_test_post(&conn, subscription_id, "p-sibling");
        conn.execute(
            "UPDATE kemono_posts
             SET published_at = (SELECT published_at FROM kemono_posts WHERE id = ?1)
             WHERE id = ?2",
            params![post, sibling],
        )
        .unwrap();
        // Two posts on the day, and the sibling has its own folder too.
        set_observed(&conn, sibling, OBSERVED_CONTENT, 2);

        let assessment = assess_post(&conn, post, &PawchiveSettings::default()).unwrap();
        assert_eq!(assessment.state, PostState::Verified, "{assessment:?}");
        assert!(assessment.state.is_settled());
        assert_eq!(assessment.reason, "日期目录存在，按已下载计入");
    }

    /// A japanese post just after midnight is still the previous day in the
    /// skin the folder is named in. Reading the raw stamp would file it under a
    /// day whose folder never exists, and the work would look missing forever.
    #[test]
    fn a_jst_post_near_midnight_lands_on_the_folder_day() {
        let (conn, sub_id, post) = evaluator_fixture();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "pending");
        // 00:30 JST on the 11th is 23:30 on the 10th at UTC+8.
        conn.execute(
            "UPDATE kemono_posts SET published_at = '2026-09-11T00:30:00' WHERE id = ?1",
            params![post],
        )
        .unwrap();
        // Discovery re-runs the upsert for the same post, which is where the
        // derived day is written.
        let discovered = PawchivePost {
            id: "900".to_string(),
            user: "27212726".to_string(),
            service: "fanbox".to_string(),
            title: Some("post".to_string()),
            content: None,
            published: Some("2026-09-11T00:30:00".to_string()),
            added: None,
            edited: None,
            file: None,
            attachments: Vec::new(),
            attachments_present: false,
            file_present: false,
            content_present: false,
            has_full: None,
        };
        record_discovered_posts(&conn, sub_id, &[discovered], None).unwrap();

        let stored: String = conn
            .query_row(
                "SELECT published_local_date FROM kemono_posts WHERE id = ?1",
                params![post],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(stored, "2026-09-10", "the derived day is the folder's day");

        let coverage = refresh_subscription_coverage(&conn, sub_id).unwrap();
        assert_eq!(coverage.len(), 1);
        assert_eq!(
            coverage[0].day, "2026-09-10",
            "coverage must group by the folder's day, not the raw stamp"
        );
    }

    /// The backfill fills rows written before the derived column existed, and
    /// leaves a row whose source stamp is empty on the `created_at` fallback
    /// instead of freezing a day derived from nothing.
    #[test]
    fn the_backfill_fills_legacy_rows_and_skips_undated_ones() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures1/artist", None)
                .unwrap();
        let dated = insert_test_post(&conn, sub_id, "901");
        let undated = insert_test_post(&conn, sub_id, "902");
        // The upsert wrote the derived column; clear it to imitate a legacy row.
        conn.execute(
            "UPDATE kemono_posts SET published_at = '2026-09-11T00:30:00', published_local_date = ''
             WHERE id = ?1",
            params![dated],
        )
        .unwrap();
        conn.execute(
            "UPDATE kemono_posts SET published_at = '', published_local_date = ''
             WHERE id = ?1",
            params![undated],
        )
        .unwrap();

        // The schema ensure that built this database already recorded the
        // migration as done; clear the marker so the backfill actually runs.
        conn.execute(
            "DELETE FROM app_settings WHERE key = ?1",
            params![PAWCHIVE_LOCAL_DATE_MIGRATION_KEY],
        )
        .unwrap();

        backfill_published_local_date(&conn).unwrap();

        let filled: String = conn
            .query_row(
                "SELECT published_local_date FROM kemono_posts WHERE id = ?1",
                params![dated],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(filled, "2026-09-10");
        let skipped: String = conn
            .query_row(
                "SELECT published_local_date FROM kemono_posts WHERE id = ?1",
                params![undated],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(skipped, "", "an undated post keeps the created_at fallback");
    }

    /// One delivered file out of ten used to settle the whole post, and the nine
    /// that actually failed never got another chance.
    #[test]
    fn partial_success_keeps_the_missing_files_claimable() {
        let (conn, _, post) = evaluator_fixture();
        for index in 0..10 {
            insert_test_file(
                &conn,
                post,
                &format!("/data/{index}.png"),
                &format!("{index}.png"),
                "image",
                "failed",
            );
        }
        set_evidence(&conn, post, "/data/0.png", "download");
        // Under Section 9 date policy, having content on the date settles the post
        // with Verified and DAY_FOLDER_REASON while keeping asset counts truthful.
        set_observed(&conn, post, OBSERVED_CONTENT, 1);
        let assessment = assess_post(&conn, post, &PawchiveSettings::default()).unwrap();
        assert_eq!(assessment.state, PostState::Verified);
        assert_eq!(assessment.reason, "日期目录存在，按已下载计入");
        assert_eq!(assessment.proven_assets, 1);
        assert_eq!(assessment.missing_assets, 9);
        assert!(!assessment.state.is_claimable());

        // Without content on disk, the partial delivery remains claimable.
        set_observed(&conn, post, OBSERVED_MISSING, 0);
        let assessment = assess_post(&conn, post, &PawchiveSettings::default()).unwrap();
        assert_eq!(assessment.state, PostState::Partial);
        assert_eq!(assessment.proven_assets, 1);
        assert_eq!(assessment.missing_assets, 9);
        assert!(assessment.state.is_claimable());
    }

    /// The retired directory rule marked posts downloaded without any receipt.
    /// That verdict cannot be reproduced, so it is not trusted either: the post
    /// reads as needing review, and it is not re-fetched.
    #[test]
    fn a_legacy_completion_needs_review_instead_of_a_redownload() {
        let (conn, sub_id, post) = evaluator_fixture();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "done");
        set_evidence(&conn, post, "/data/a.png", "legacy");
        conn.execute(
            "UPDATE kemono_posts SET legacy_status = 'done' WHERE id = ?1",
            params![post],
        )
        .unwrap();
        let settings = PawchiveSettings::default();

        let assessment = reassess_post(&conn, post, &settings).unwrap();
        assert_eq!(assessment.state, PostState::Unverified);
        assert!(!assessment.state.is_claimable());

        // It must not be counted as a completed day either, or the panel would
        // report a library nobody verified as finished.
        conn.execute(
            "UPDATE kemono_posts SET published_at = '2026-09-10T00:00:00' WHERE id = ?1",
            params![post],
        )
        .unwrap();
        let coverage = refresh_subscription_coverage(&conn, sub_id).unwrap();
        assert_eq!(coverage[0].downloaded_posts, 0);
        assert_eq!(coverage[0].missing_posts(), 1);
        assert_eq!(pending_coverage_day_count(&conn, sub_id).unwrap(), 1);
    }

    /// The same legacy completion, now with a folder of its own on disk and no
    /// other work sharing the day. The retired verdict is still not trusted —
    /// the folder is what settles it, exactly as it settles a post whose assets
    /// are only waiting out a backoff. A folder cannot mean "had" in one branch
    /// and something weaker in another.
    #[test]
    fn a_legacy_completion_settles_on_its_own_unambiguous_folder() {
        let (conn, sub_id, post) = evaluator_fixture();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "done");
        set_evidence(&conn, post, "/data/a.png", "legacy");
        conn.execute(
            "UPDATE kemono_posts SET legacy_status = 'done' WHERE id = ?1",
            params![post],
        )
        .unwrap();
        set_observed(&conn, post, OBSERVED_CONTENT, 1);
        let settings = PawchiveSettings::default();

        let assessment = reassess_post(&conn, post, &settings).unwrap();
        assert_eq!(assessment.state, PostState::Verified);
        assert_eq!(assessment.reason, "日期目录存在，按已下载计入");
        assert!(!assessment.state.is_claimable(), "nothing left to fetch");

        // And the day reads done, because the folder is the proof the panel
        // reports rather than the verdict that could not be reproduced.
        conn.execute(
            "UPDATE kemono_posts SET published_at = '2026-09-10T00:00:00' WHERE id = ?1",
            params![post],
        )
        .unwrap();
        let coverage = refresh_subscription_coverage(&conn, sub_id).unwrap();
        assert_eq!(coverage[0].downloaded_posts, 1);
        assert_eq!(coverage[0].missing_posts(), 0);
        assert_eq!(pending_coverage_day_count(&conn, sub_id).unwrap(), 0);
    }

    /// Under Section 9 date policy, having content on disk settles the shared day;
    /// without content on disk, the ambiguity still requires human review.
    #[test]
    fn a_legacy_completion_on_a_shared_day_still_needs_a_human() {
        let (conn, sub_id, post) = evaluator_fixture();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "done");
        set_evidence(&conn, post, "/data/a.png", "legacy");
        set_observed(&conn, post, OBSERVED_CONTENT, 1);

        let sibling = insert_test_post(&conn, sub_id, "901");
        conn.execute(
            "UPDATE kemono_posts SET published_at = '2026-09-10T00:00:00' WHERE id IN (?1, ?2)",
            params![post, sibling],
        )
        .unwrap();
        let settings = PawchiveSettings::default();

        // When content is observed on disk, Section 9 date policy considers it settled
        let assessment = reassess_post(&conn, post, &settings).unwrap();
        assert_eq!(assessment.state, PostState::Verified);
        assert_eq!(assessment.reason, "日期目录存在，按已下载计入");
        assert!(!assessment.state.is_claimable());

        // Without content on disk, legacy status without verified receipts remains unverified
        set_observed(&conn, post, OBSERVED_MISSING, 0);
        let assessment = reassess_post(&conn, post, &settings).unwrap();
        assert_eq!(assessment.state, PostState::Unverified);
        assert_eq!(assessment.reason, "本地有内容，但缺少完成凭据");
        assert!(!assessment.state.is_claimable());
    }

    /// The measured counter-case to the day-folder rule: this post's own folder
    /// is not on disk, and the only directory its day holds is another post's.
    /// The read is recorded, and the evaluator reports it — reading the post as
    /// had would claim a neighbour's files, reading it as missing would fetch
    /// what is already on disk under a name this side cannot predict. 79 posts
    /// of one subscription sat in exactly this shape while reading `verified`.
    #[test]
    fn a_neighbours_folder_on_the_day_is_reported_to_a_human() {
        let (conn, _, post) = evaluator_fixture();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "pending");
        set_observed(&conn, post, OBSERVED_MISSING, 0);
        set_observed_source(&conn, post, FOLDER_FROM_SIBLING_DAY);

        let assessment = assess_post(&conn, post, &PawchiveSettings::default()).unwrap();
        assert_eq!(assessment.state, PostState::Unverified, "{assessment:?}");
        assert_eq!(assessment.reason, SIBLING_FOLDER_REASON);
        assert!(
            !assessment.state.is_claimable(),
            "a neighbour's folder must not send the work back to the download queue"
        );
        assert!(!assessment.state.is_settled());
    }

    /// The same finding on a post whose every asset is waiting out a backoff.
