    /// A verdict that rests on the day-only search has to stay reachable. The
    /// 1.0.362 sibling guard was correct and settled nothing at all for the
    /// opposite reason: the posts it was written for had already been marked
    /// had, and a marked post was never read again.
    #[test]
    fn a_post_the_day_rule_settled_is_read_again() {
        let (conn, sub_id, by_day) = evaluator_fixture();
        let settle = |post: i64, source: &str| {
            conn.execute(
                "UPDATE kemono_posts
                 SET assessment_state = 'verified', assessment_reason = ?1,
                     observed_source = ?2
                 WHERE id = ?3",
                params![DAY_FOLDER_REASON, source, post],
            )
            .unwrap();
        };
        settle(by_day, FOLDER_FROM_DAY);
        // Settled the same way by a build that did not record how it found the
        // folder — every row of an upgraded database looks like this.
        let legacy = insert_test_post(&conn, sub_id, "p-legacy");
        settle(legacy, "");
        // Paired with a folder by day and title: the day search never decided
        // it, so re-reading it would answer nothing new.
        let by_name = insert_test_post(&conn, sub_id, "p-named");
        settle(by_name, FOLDER_FROM_NAME);
        // Settled by the manifest, with no folder search involved at all.
        let manifest = insert_test_post(&conn, sub_id, "p-manifest");
        conn.execute(
            "UPDATE kemono_posts
             SET assessment_state = 'verified', assessment_reason = ?1, observed_source = ''
             WHERE id = ?2",
            params!["当前范围的文件已核验", manifest],
        )
        .unwrap();

        let queued: Vec<i64> = posts_to_observe(&conn, 100, None)
            .unwrap()
            .iter()
            .map(|row| row.post_db_id)
            .collect();
        assert!(
            queued.contains(&by_day),
            "a verdict the day rule produced is read again"
        );
        assert!(
            queued.contains(&legacy),
            "and so is one recorded before the source was kept"
        );
        assert!(
            !queued.contains(&by_name),
            "a folder found by name does not depend on the day search"
        );
        assert!(
            !queued.contains(&manifest),
            "a manifest verdict is not a folder search at all"
        );
    }

    /// C6 — a legacy day-family marker is converted by a bounded round.
    ///
    /// `sibling_day` is no longer written by any resolver, but a database
    /// upgraded from a build that did write it still carries the value. The
    /// sweep is what turns such a record into a current reading, so the row has
    /// to be in its scope whatever state the older build left next to the
    /// marker — otherwise the record keeps a verdict nobody can refresh.
    ///
    /// Conversion is self-emptying: the read overwrites `observed_source` with
    /// what the search actually found, and the row then leaves the queue.
    #[test]
    fn a_legacy_sibling_marker_is_converted_by_the_sweep() {
        let (conn, _, post) = evaluator_fixture();
        // The shape an upgraded database can carry: the marker with a settled
        // state, which the state arm alone would not pick up.
        conn.execute(
            "UPDATE kemono_posts
             SET assessment_state = 'verified', assessment_reason = ?1, observed_source = ?2
             WHERE id = ?3",
            params![SIBLING_FOLDER_REASON, FOLDER_FROM_SIBLING_DAY, post],
        )
        .unwrap();

        assert!(
            posts_to_observe(&conn, 100, None)
                .unwrap()
                .iter()
                .any(|row| row.post_db_id == post),
            "a legacy sibling marker must be refreshed by the sweep"
        );

        // One observation converts it: the marker is replaced by the reading.
        record_folder_observation(
            &conn,
            post,
            FolderObservation {
                state: OBSERVED_CONTENT,
                files: 1,
            },
            FOLDER_FROM_TEMPLATE,
        )
        .unwrap();
        let source: String = conn
            .query_row(
                "SELECT observed_source FROM kemono_posts WHERE id = ?1",
                params![post],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(
            source, FOLDER_FROM_TEMPLATE,
            "the converted record carries the current reading, not the legacy marker"
        );
        assert!(
            !posts_to_observe(&conn, 100, None)
                .unwrap()
                .iter()
                .any(|row| row.post_db_id == post),
            "a converted row whose reading no longer depends on the day search leaves the queue"
        );
    }

    /// C6 — a day-found reading stays reachable on purpose.
    ///
    /// The counterweight to the test above. A `day` reading depends on a rule
    /// this side can change, so it must keep being re-read: dropping it from the
    /// queue would strand every post the day rule settled if that rule is ever
    /// corrected. That is why the sweep carries a standing `day` arm rather than
    /// only the one-shot reason migration.
    #[test]
    fn a_day_found_reading_is_still_refreshed_every_round() {
        let (conn, _, post) = evaluator_fixture();
        conn.execute(
            "UPDATE kemono_posts
             SET assessment_state = 'verified', assessment_reason = ?1, observed_source = ?2
             WHERE id = ?3",
            params![DAY_FOLDER_REASON, FOLDER_FROM_DAY, post],
        )
        .unwrap();
        assert!(
            posts_to_observe(&conn, 100, None)
                .unwrap()
                .iter()
                .any(|row| row.post_db_id == post),
            "a rule-dependent reading must remain in the sweep's scope"
        );
    }

    /// The arm that reads `assessment_reason` is a migration, not a standing
    /// rule: once every row carries its source, nothing matches and the sweep
    /// stops re-reading the same posts every round.
    #[test]
    fn the_reason_arm_empties_once_the_source_is_recorded() {
        let (conn, _, post) = evaluator_fixture();
        conn.execute(
            "UPDATE kemono_posts
             SET assessment_state = 'verified', assessment_reason = ?1, observed_source = ''
             WHERE id = ?2",
            params![DAY_FOLDER_REASON, post],
        )
        .unwrap();
        assert_eq!(posts_to_observe(&conn, 100, None).unwrap().len(), 1);

        // The rendered name was there all along, so the day search never
        // decided this post — which is what the first read establishes.
        set_observed_source(&conn, post, FOLDER_FROM_TEMPLATE);
        assert!(
            posts_to_observe(&conn, 100, None).unwrap().is_empty(),
            "a settled post whose folder source is known is not read again"
        );
    }

    /// The source adds an attachment to a post the user already confirmed. The
    /// confirmation was about the list they saw, so it must not cover a resource
    /// it never saw.
    #[test]
    fn a_new_attachment_reopens_a_confirmed_post() {
        let (conn, _, post) = evaluator_fixture();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "pending");
        let settings = PawchiveSettings::default();
        let outcome =
            record_post_decision(&conn, post, PostDecisionAction::Confirm, "有", "", Some(1))
                .unwrap();
        assert!(matches!(outcome, DecisionOutcome::Applied(_)));
        assert_eq!(
            assess_post(&conn, post, &settings).unwrap().state,
            PostState::Confirmed
        );

        // A later discovery adds a resource and bumps the manifest version.
        conn.execute(
            "UPDATE kemono_posts SET manifest_version = 2 WHERE id = ?1",
            params![post],
        )
        .unwrap();
        let assessment = assess_post(&conn, post, &settings).unwrap();
        assert_eq!(
            assessment.state,
            PostState::Pending,
            "the old confirmation must not cover the new resource"
        );
        assert!(assessment.state.is_claimable());
    }

    /// Turning a file type on changed nothing before, because the discovery pass
    /// had already dropped the rows of the disabled types.
    #[test]
    fn a_type_switch_changes_what_a_post_requires() {
        let (conn, _, post) = evaluator_fixture();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "pending");
        insert_test_file(&conn, post, "/data/b.zip", "b.zip", "archive", "pending");
        set_evidence(&conn, post, "/data/a.png", "download");

        let without_archives = reassess_post(&conn, post, &settings_with(false)).unwrap();
        assert_eq!(without_archives.state, PostState::Verified);
        assert_eq!(without_archives.required_assets, 1);

        // Enabling 压缩包 requires more from a post that is already stored, with
        // no re-discovery: the row was kept all along.
        let with_archives = reassess_post(&conn, post, &settings_with(true)).unwrap();
        assert_eq!(with_archives.state, PostState::Partial);
        assert_eq!(with_archives.required_assets, 2);
        assert_eq!(with_archives.missing_assets, 1);
    }

    /// An unreadable folder is not an absent one: calling it missing would
