    #[test]
    fn nothing_required_is_counted_apart_from_downloaded() {
        let (conn, sub_id, post) = evaluator_fixture();
        conn.execute(
            "UPDATE kemono_posts SET published_at = '2026-09-10T00:00:00' WHERE id = ?1",
            params![post],
        )
        .unwrap();

        let assessment = reassess_post(&conn, post, &PawchiveSettings::default()).unwrap();
        assert_eq!(assessment.state, PostState::NotRequired);

        let coverage = refresh_subscription_coverage(&conn, sub_id).unwrap();
        assert_eq!(coverage[0].downloaded_posts, 0);
        assert_eq!(coverage[0].not_required_posts, 1);
        assert_eq!(coverage[0].missing_posts(), 0);
        assert!(coverage[0].complete());
    }

    /// A confirmation is a user decision, and the coverage keeps it apart from
    /// an automatic verification instead of folding both into one number.
    #[test]
    fn coverage_counts_a_confirmation_apart_from_a_verification() {
        let (conn, sub_id, fixture_post) = evaluator_fixture();
        // The fixture post carries no date, so give it one: every post on the
        // day has to be in scope for the counts to mean anything.
        let verified = insert_test_post(&conn, sub_id, "901");
        let confirmed = insert_test_post(&conn, sub_id, "902");
        for id in [fixture_post, verified, confirmed] {
            conn.execute(
                "UPDATE kemono_posts SET published_at = '2026-09-10T00:00:00' WHERE id = ?1",
                params![id],
            )
            .unwrap();
        }
        let settings = PawchiveSettings::default();
        reassess_post(&conn, fixture_post, &settings).unwrap();
        reassess_post(&conn, verified, &settings).unwrap();
        reassess_post(&conn, confirmed, &settings).unwrap();
        conn.execute(
            "UPDATE kemono_posts SET assessment_state = 'verified' WHERE id = ?1",
            params![verified],
        )
        .unwrap();
        conn.execute(
            "UPDATE kemono_posts SET assessment_state = 'confirmed' WHERE id = ?1",
            params![confirmed],
        )
        .unwrap();

        let coverage = refresh_subscription_coverage(&conn, sub_id).unwrap();
        let day = coverage
            .iter()
            .find(|row| row.day == "2026-09-10")
            .expect("the day the posts were published on");
        assert_eq!(day.total_posts, 3);
        assert_eq!(day.downloaded_posts, 2);
        assert_eq!(
            day.confirmed_posts, 1,
            "a user confirmation is never counted as an automatic verification"
        );
        assert_eq!(day.not_required_posts, 1);
    }

    /// A confirmation is reversible, and a stale one is refused rather than
    /// applied to a resource list the user never saw.
    #[test]
    fn decisions_are_versioned_and_reversible() {
        let (conn, _, post) = evaluator_fixture();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "pending");
        let settings = PawchiveSettings::default();

        let stale = record_post_decision(&conn, post, PostDecisionAction::Confirm, "", "", Some(7))
            .unwrap();
        assert!(
            matches!(
                stale,
                DecisionOutcome::Conflict {
                    current_manifest_version: 1
                }
            ),
            "a decision prepared for another manifest version must be refused"
        );

        record_post_decision(&conn, post, PostDecisionAction::Ignore, "", "", None).unwrap();
        let ignored = assess_post(&conn, post, &settings).unwrap();
        assert_eq!(ignored.state, PostState::Ignored);
        assert!(!ignored.state.is_claimable());
        assert!(ignored.state.is_settled());

        record_post_decision(&conn, post, PostDecisionAction::Revoke, "", "", None).unwrap();
        let revoked = assess_post(&conn, post, &settings).unwrap();
        assert_eq!(
            revoked.state,
            PostState::Pending,
            "revoking must return the post to what the evidence says"
        );
        assert!(revoked.state.is_claimable());
    }

    /// The manifest is what the work needs delivered, and the netdisk bundle is
    /// part of that. Swapping the link for a different one changes the
    /// requirement, so the version has to move — otherwise a confirmation or a
    /// receipt for the old bundle kept covering the new one.
    #[test]
    fn a_changed_external_link_is_a_new_manifest() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures1/artist", None)
                .unwrap();
        let post = |content: &str| PawchivePost {
            id: "600".to_string(),
            user: "27212726".to_string(),
            service: "fanbox".to_string(),
            title: Some("T".to_string()),
            content: Some(content.to_string()),
            published: Some("2026-02-01T12:00:00".to_string()),
            added: None,
            edited: None,
            file: None,
            attachments: Vec::new(),
            attachments_present: true,
            file_present: true,
            content_present: true,
            has_full: None,
        };
        let version = || -> i64 {
            conn.query_row(
                "SELECT manifest_version FROM kemono_posts WHERE post_id = '600'",
                [],
                |row| row.get(0),
            )
            .unwrap()
        };
        let post_db_id: i64 = {
            record_discovered_posts(
                &conn,
                sub_id,
                &[post("Mega: https://mega.nz/folder/one")],
                None,
            )
            .unwrap();
            conn.query_row(
                "SELECT id FROM kemono_posts WHERE post_id = '600'",
                [],
                |row| row.get(0),
            )
            .unwrap()
        };
        let first = version();
        // The same link again is the same manifest.
        record_discovered_posts(
            &conn,
            sub_id,
            &[post("Mega: https://mega.nz/folder/one")],
            None,
        )
        .unwrap();
        assert_eq!(version(), first, "an unchanged link is not a new manifest");

        // A different bundle is.
        record_discovered_posts(
            &conn,
            sub_id,
            &[post("Mega: https://mega.nz/folder/two")],
            None,
        )
        .unwrap();
        assert!(
            version() > first,
            "a replaced external link must move the manifest"
        );

        // A confirmation made against the old bundle does not cover the new one.
        let settings = PawchiveSettings::default();
        assert!(
            matches!(
                record_post_decision(
                    &conn,
                    post_db_id,
                    PostDecisionAction::Confirm,
                    "",
                    "",
                    Some(first)
                )
                .unwrap(),
                DecisionOutcome::Conflict { .. }
            ),
            "a decision for the replaced bundle is a conflict, not an answer"
        );
        let assessment = reassess_post(&conn, post_db_id, &settings).unwrap();
        assert_ne!(assessment.state, PostState::Confirmed, "{assessment:?}");
        assert!(assessment.external_pending, "the new bundle is undelivered");
    }

    /// An attachment the source has withdrawn leaves the current requirement.
    /// It used to stay in the denominator forever, so a work could never read as
    /// complete even after everything still listed had arrived.
    #[test]
    fn a_withdrawn_attachment_leaves_the_current_requirement() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures1/artist", None)
                .unwrap();
        let refs = |paths: &[&str]| PawchivePost {
            id: "700".to_string(),
            user: "27212726".to_string(),
            service: "fanbox".to_string(),
            title: Some("T".to_string()),
            content: None,
            published: Some("2026-02-01T12:00:00".to_string()),
            added: None,
            edited: None,
            file: None,
            attachments: paths
                .iter()
                .map(|path| PawchiveFileRef {
                    id: None,
                    name: Some(path.rsplit('/').next().unwrap().to_string()),
                    path: Some((*path).to_string()),
                })
                .collect(),
            attachments_present: true,
            file_present: true,
            content_present: true,
            has_full: None,
        };
        let settings = PawchiveSettings::default();

        record_discovered_posts(
            &conn,
            sub_id,
            &[refs(&["/data/a.png", "/data/b.png"])],
            None,
        )
        .unwrap();
        let post_db_id: i64 = conn
            .query_row(
                "SELECT id FROM kemono_posts WHERE post_id = '700'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        set_evidence(&conn, post_db_id, "/data/a.png", "download");
        let partial = reassess_post(&conn, post_db_id, &settings).unwrap();
        assert_eq!(partial.required_assets, 2);
        assert_eq!(partial.missing_assets, 1);

        // The source drops b.png. Its row and its delivered state stay; it just
        // stops being required.
        record_discovered_posts(&conn, sub_id, &[refs(&["/data/a.png"])], None).unwrap();
        let after_removal = reassess_post(&conn, post_db_id, &settings).unwrap();
        assert_eq!(after_removal.required_assets, 1, "{after_removal:?}");
        assert_eq!(after_removal.missing_assets, 0);
        assert_eq!(after_removal.state, PostState::Verified);
        let kept: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM kemono_files WHERE post_id = ?1",
                params![post_db_id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(kept, 2, "the withdrawn resource keeps its history");

        // The source lists it again: it is required again, and the download that
        // arrived earlier still counts.
        record_discovered_posts(
            &conn,
            sub_id,
            &[refs(&["/data/a.png", "/data/b.png"])],
            None,
        )
        .unwrap();
        let restored = reassess_post(&conn, post_db_id, &settings).unwrap();
        assert_eq!(restored.required_assets, 2);
        assert_eq!(restored.missing_assets, 1, "b.png is still undelivered");
        assert_eq!(restored.state, PostState::Partial);

        // Every attachment gone: the work requires nothing, and the withdrawn
        // rows are still on file.
        record_discovered_posts(&conn, sub_id, &[refs(&[])], None).unwrap();
        let emptied = reassess_post(&conn, post_db_id, &settings).unwrap();
        assert_eq!(emptied.required_assets, 0);
        assert_eq!(emptied.state, PostState::NotRequired, "{emptied:?}");
    }

    /// Identity is the source path, not the attachment's position: inserting one
    /// attachment used to renumber every later one and store it twice.
    #[test]
    fn attachment_reordering_does_not_duplicate_a_resource() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures1/artist", None)
                .unwrap();
        let refs = |paths: &[(&str, &str)]| PawchivePost {
            id: "500".to_string(),
            user: "27212726".to_string(),
            service: "fanbox".to_string(),
            title: Some("T".to_string()),
            content: None,
            published: Some("2026-02-01T12:00:00".to_string()),
            added: None,
            edited: None,
            file: None,
            attachments: paths
                .iter()
                .map(|(name, path)| PawchiveFileRef {
                    id: None,
                    name: Some((*name).to_string()),
                    path: Some((*path).to_string()),
                })
                .collect(),
            attachments_present: true,
            file_present: true,
            content_present: true,
            has_full: None,
        };

        record_discovered_posts(
            &conn,
            sub_id,
            &[refs(&[("a.png", "/data/a.png"), ("b.png", "/data/b.png")])],
            None,
        )
        .unwrap();
        let first_version: i64 = conn
            .query_row(
                "SELECT manifest_version FROM kemono_posts WHERE post_id = '500'",
                [],
                |row| row.get(0),
            )
            .unwrap();

        // Same two resources, listed in the other order.
        record_discovered_posts(
            &conn,
            sub_id,
            &[refs(&[("b.png", "/data/b.png"), ("a.png", "/data/a.png")])],
            None,
        )
        .unwrap();

        let rows: i64 = conn
            .query_row("SELECT COUNT(*) FROM kemono_files", [], |row| row.get(0))
            .unwrap();
        assert_eq!(rows, 2, "reordering is not a new resource");
        let second_version: i64 = conn
            .query_row(
                "SELECT manifest_version FROM kemono_posts WHERE post_id = '500'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(
            first_version, second_version,
            "an unchanged resource set is not a new manifest"
        );

        // A genuinely new attachment is.
        record_discovered_posts(
            &conn,
            sub_id,
            &[refs(&[
                ("a.png", "/data/a.png"),
                ("b.png", "/data/b.png"),
                ("c.png", "/data/c.png"),
            ])],
            None,
        )
        .unwrap();
        let third_version: i64 = conn
            .query_row(
                "SELECT manifest_version FROM kemono_posts WHERE post_id = '500'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(third_version, second_version + 1);
    }

    /// The start date bounds the queue, not just the report. A post whose date
    /// was moved past the boundary used to vanish from the gap list while
    /// staying claimable.
    #[test]
    fn a_post_before_the_start_date_is_out_of_scope_for_every_reader() {
        let (conn, sub_id, post) = evaluator_fixture();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "pending");
        conn.execute(
            "UPDATE kemono_posts SET published_at = '2024-01-05T00:00:00' WHERE id = ?1",
            params![post],
        )
        .unwrap();
        conn.execute(
            "UPDATE kemono_subscriptions SET since_date = '2025-01-01' WHERE id = ?1",
            params![sub_id],
        )
        .unwrap();

        let assessment = reassess_post(&conn, post, &PawchiveSettings::default()).unwrap();
        assert_eq!(assessment.state, PostState::NotRequired);
        assert_eq!(assessment.reason, "超出订阅起始日期");
        assert!(!assessment.state.is_claimable());

        // Moving the boundary earlier brings it back into scope with everything
        // it still needs.
        conn.execute(
            "UPDATE kemono_subscriptions SET since_date = '2020-01-01' WHERE id = ?1",
            params![sub_id],
        )
        .unwrap();
        assert_eq!(
            reassess_post(&conn, post, &PawchiveSettings::default())
                .unwrap()
                .state,
            PostState::Pending
        );
    }

    /// Two works whose template renders one name must not take each other's
    /// file, and the suffix has to survive a retry.
    #[test]
    fn a_target_another_resource_holds_gets_a_stable_suffix() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures1/artist", None)
                .unwrap();
        let first_post = insert_test_post(&conn, sub_id, "1");
        let second_post = insert_test_post(&conn, sub_id, "2");
        insert_test_file(
            &conn,
            first_post,
            "/data/shared.png",
            "shared.png",
            "image",
            "pending",
        );
        insert_test_file(
            &conn,
            second_post,
            "/data/shared.png",
            "shared.png",
            "image",
            "pending",
        );
        let first_file: i64 = conn
            .query_row(
                "SELECT id FROM kemono_files WHERE post_id = ?1",
                params![first_post],
                |row| row.get(0),
            )
            .unwrap();
        let second_file: i64 = conn
            .query_row(
                "SELECT id FROM kemono_files WHERE post_id = ?1",
                params![second_post],
                |row| row.get(0),
            )
            .unwrap();
        let desired = PathBuf::from("/pictures1/artist/2026-09-10 shared.png");

        let reserved_first = reserve_target_path(&conn, first_file, &desired).unwrap();
        assert_eq!(reserved_first, desired, "the first resource keeps the name");
        let reserved_second = reserve_target_path(&conn, second_file, &desired).unwrap();
        assert_ne!(reserved_second, desired);
        let name = reserved_second
            .file_name()
            .unwrap()
            .to_string_lossy()
            .to_string();
        assert!(
            name.starts_with("2026-09-10 shared_") && name.ends_with(".png"),
            "{name}"
        );

        // A retry renders the same suffix rather than walking to a new name.
        let stored: String = conn
            .query_row(
                "SELECT target_path FROM kemono_files WHERE id = ?1",
                params![second_file],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(stored, reserved_second.to_string_lossy());
        assert_eq!(
            reserve_target_path(&conn, second_file, &desired).unwrap(),
            reserved_second
        );
    }

    /// Turning the master switch off mid-round stops new claims; it does not
    /// touch what has already been published.
    #[test]
    fn a_disabled_master_switch_stops_claims_that_were_already_queued() {
        let (conn, sub_id, post) = evaluator_fixture();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "pending");
        let mut on = PawchiveSettings::default();
        on.enabled = true;
        save_pawchive_settings(&conn, &on).unwrap();
        conn.execute(
            "UPDATE kemono_subscriptions SET enabled = 1, mode = 'auto' WHERE id = ?1",
            params![sub_id],
        )
        .unwrap();
        let allowed = |conn: &Connection| claim_scope(conn, post).unwrap().unwrap().enabled;
        assert!(allowed(&conn));

        let mut stored = PawchiveSettings::default();
        stored.enabled = false;
        save_pawchive_settings(&conn, &stored).unwrap();
        assert!(
            !allowed(&conn),
            "the master switch has to reach a claim already in the queue"
        );

        // The per-subscription switch is the same gate.
        let mut back_on = PawchiveSettings::default();
        back_on.enabled = true;
        save_pawchive_settings(&conn, &back_on).unwrap();
        conn.execute(
            "UPDATE kemono_subscriptions SET enabled = 0 WHERE id = ?1",
            params![sub_id],
        )
        .unwrap();
        assert!(!allowed(&conn));

        let status: String = conn
            .query_row(
                "SELECT status FROM kemono_files WHERE post_id = ?1",
                params![post],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(
            status, "pending",
            "a refused claim leaves the row untouched"
        );
    }

    /// Admission is read when the file is claimed, not when the round was
    /// queued. A start date moved past the post, or a type switched off, has to
    /// stop the claim even though the stored assessment still says otherwise.
    #[test]
    fn a_claim_reads_the_start_date_and_the_type_selection_as_they_stand_now() {
        let (conn, sub_id, post) = evaluator_fixture();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "pending");
        conn.execute(
            "UPDATE kemono_posts SET published_at = '2026-02-01T12:00:00' WHERE id = ?1",
            params![post],
        )
        .unwrap();
        let mut on = PawchiveSettings::default();
        on.enabled = true;
        save_pawchive_settings(&conn, &on).unwrap();
        conn.execute(
            "UPDATE kemono_subscriptions SET enabled = 1, mode = 'auto' WHERE id = ?1",
            params![sub_id],
        )
        .unwrap();

        let scope = claim_scope(&conn, post).unwrap().unwrap();
        assert!(scope.enabled && scope.in_range);
        assert!(wants_type(&scope.settings, "image"));

        // A subscription switched to manual is not claimable by an automatic
        // round, even with both switches on: the user took the decision back.
        conn.execute(
            "UPDATE kemono_subscriptions SET mode = 'manual' WHERE id = ?1",
            params![sub_id],
        )
        .unwrap();
        assert!(
            !claim_scope(&conn, post).unwrap().unwrap().enabled,
            "manual mode must stop the automatic claim"
        );
        conn.execute(
            "UPDATE kemono_subscriptions SET mode = 'auto' WHERE id = ?1",
            params![sub_id],
        )
        .unwrap();
        assert!(claim_scope(&conn, post).unwrap().unwrap().enabled);

        // The start date moves past the post after it was queued.
        conn.execute(
            "UPDATE kemono_subscriptions SET since_date = '2099-01-01' WHERE id = ?1",
            params![sub_id],
        )
        .unwrap();
        assert!(
            !claim_scope(&conn, post).unwrap().unwrap().in_range,
            "a claim has to honour the start date the subscription carries now"
        );

        // An empty start date means the whole history is in scope again.
        conn.execute(
            "UPDATE kemono_subscriptions SET since_date = '' WHERE id = ?1",
            params![sub_id],
        )
        .unwrap();
        assert!(claim_scope(&conn, post).unwrap().unwrap().in_range);

        // The type selection is part of admission too, and it is read fresh:
        // the round's own snapshot still says images are wanted.
        let mut images_off = PawchiveSettings::default();
        images_off.enabled = true;
        images_off.download_images = false;
        save_pawchive_settings(&conn, &images_off).unwrap();
        let scope = claim_scope(&conn, post).unwrap().unwrap();
        assert!(scope.enabled, "the switches are still on");
        assert!(
            !wants_type(&scope.settings, "image"),
            "a type switched off must not be claimed from a stale round snapshot"
        );
        // The other types are untouched by that switch.
        assert!(wants_type(&scope.settings, "video"));
        assert!(wants_type(&PawchiveSettings::default(), "image"));
    }

    /// A downloading round walks the queue oldest gap first, so an unfinished
    /// round still closes the days that have been reported missing the longest.
    /// A post the source gave no date for never jumps ahead of a dated one.
    #[test]
    fn the_queue_is_claimed_oldest_gap_first() {
        let (conn, sub_id, _) = evaluator_fixture();
        conn.execute(
            "UPDATE kemono_subscriptions SET enabled = 1, mode = 'auto' WHERE id = ?1",
            params![sub_id],
        )
        .unwrap();
        let mut seeded: Vec<(&str, i64)> = Vec::new();
        for (post_id, published, state) in [
            ("901", "2026-03-02T10:00:00", "pending"),
            ("902", "2026-01-05T10:00:00", "pending"),
            ("903", "2026-02-10T10:00:00", "partial"),
            ("904", "2026-02-11T10:00:00", "verified"),
        ] {
            let id = insert_test_post(&conn, sub_id, post_id);
            conn.execute(
                "UPDATE kemono_posts SET published_at = ?1, assessment_state = ?2 WHERE id = ?3",
                params![published, state, id],
            )
            .unwrap();
            seeded.push((post_id, id));
        }
        // Neither date column carries a value: this post has no day to sort by.
        let undated = insert_test_post(&conn, sub_id, "905");
        conn.execute(
            "UPDATE kemono_posts
             SET published_at = '', created_at = '', assessment_state = 'pending'
             WHERE id = ?1",
            params![undated],
        )
        .unwrap();

        let id_of = |post_id: &str| {
            seeded
                .iter()
                .find(|(name, _)| *name == post_id)
                .map(|(_, id)| *id)
                .unwrap()
        };
        let order = claimable_posts(&conn, false)
            .unwrap()
            .into_iter()
            .map(|(id, _)| id)
            .collect::<Vec<_>>();
        assert_eq!(
            order,
            vec![id_of("902"), id_of("903"), id_of("901"), undated],
            "oldest gap first, then the undated post, and never the verified one"
        );

        // The scheduled round's query is the same queue with one more gate: a
        // manual subscription is not part of it. The operator-triggered round
        // still sees the whole queue, which is what the `false` above asserts.
        conn.execute(
            "UPDATE kemono_subscriptions SET mode = 'manual' WHERE id = ?1",
            params![sub_id],
        )
        .unwrap();
        assert!(
            claimable_posts(&conn, true).unwrap().is_empty(),
            "a scheduled round claims nothing from a manual subscription"
        );
        assert_eq!(
            claimable_posts(&conn, false).unwrap().len(),
            4,
            "the operator's own round still covers it"
        );
    }

    /// A subscription that automatic rounds may claim from.
    fn auto_subscription(conn: &Connection, service: &str, user_id: &str, dir: &str) -> i64 {
        let id = upsert_subscription(conn, service, user_id, None, dir, None).unwrap();
        conn.execute(
            "UPDATE kemono_subscriptions SET enabled = 1, mode = 'auto' WHERE id = ?1",
            params![id],
        )
        .unwrap();
        id
    }

    /// A post with a readable day and a state, seeded for the list and the queue.
    fn seed_listed_post(
        conn: &Connection,
        sub_id: i64,
        post_id: &str,
        day: &str,
        state: &str,
    ) -> i64 {
        let id = insert_test_post(conn, sub_id, post_id);
        conn.execute(
            "UPDATE kemono_posts SET published_at = ?1, assessment_state = ?2 WHERE id = ?3",
            params![format!("{day}T12:00:00"), state, id],
        )
        .unwrap();
        id
    }

    /// Two creators, one with a backlog and one with a single work: the round
    /// alternates instead of draining the bigger queue first.
    ///
    /// Plan §7.2 — 自动公平调度按画师轮转 … 不让一个大作者或失败文件占满队列.
    #[test]
    fn a_round_alternates_between_subscriptions() {
        let conn = test_conn();
        let big = auto_subscription(&conn, "fanbox", "1001", "/pictures/big");
        let small = auto_subscription(&conn, "fanbox", "1002", "/pictures/small");

        let mut big_ids = Vec::new();
        for (index, day) in [
            "2026-01-01",
            "2026-01-02",
            "2026-01-03",
            "2026-01-04",
            "2026-01-05",
        ]
        .into_iter()
        .enumerate()
        {
            big_ids.push(seed_listed_post(
                &conn,
                big,
                &format!("big{index}"),
                day,
                "pending",
            ));
        }
        let small_id = seed_listed_post(&conn, small, "small0", "2026-02-01", "pending");

        let queue = schedule_round_order(&conn, false).unwrap();
        assert_eq!(
            queue.posts.len(),
            6,
            "every outstanding post is in the round"
        );
        assert_eq!(
            queue.outstanding, 6,
            "and the round covers all of them, so nothing was left behind"
        );
        assert!(!queue.truncated());
        let order = queue.posts;
        assert_eq!(order[0].post_id, big_ids[0]);
        assert_eq!(order[0].subscription_id, big);
        assert_eq!(order[0].day.as_deref(), Some("2026-01-01"));
        assert_eq!(order[1].post_id, small_id);
        assert_eq!(order[1].subscription_id, small);
        assert_ne!(
            order[0].subscription_id, order[1].subscription_id,
            "the first two entries come from different subscriptions"
        );
        let small_position = order
            .iter()
            .position(|post| post.post_id == small_id)
            .unwrap();
        let big_third_position = order
            .iter()
            .position(|post| post.post_id == big_ids[2])
            .unwrap();
        assert!(
            small_position < big_third_position,
            "the small creator's only work must not wait behind the big backlog"
        );
        // Within one subscription the older rule still holds.
        assert_eq!(
            order
                .iter()
                .filter(|post| post.subscription_id == big)
                .map(|post| post.post_id)
                .collect::<Vec<_>>(),
            big_ids,
            "oldest gap first, then stable id"
        );
        // Same database state, same round: nothing hash-ordered reaches the result.
        assert_eq!(order, schedule_round_order(&conn, false).unwrap().posts);

        // The automatic gate is still the automatic gate.
        conn.execute(
            "UPDATE kemono_subscriptions SET mode = 'manual' WHERE id = ?1",
            params![big],
        )
        .unwrap();
        let auto_only_round = schedule_round_order(&conn, true).unwrap().posts;
        assert_eq!(auto_only_round.len(), 1);
        assert_eq!(auto_only_round[0].subscription_id, small);
    }

    /// A subscription with nothing outstanding is not a turn in the rotation, so
    /// its presence cannot move where the other subscriptions' posts land.
    #[test]
    fn an_empty_subscription_does_not_shift_the_rotation() {
        let conn = test_conn();
        let first = auto_subscription(&conn, "fanbox", "2001", "/pictures/first");
        let second = auto_subscription(&conn, "fanbox", "2002", "/pictures/second");
        let first_ids = (0..3)
            .map(|index| {
                seed_listed_post(
                    &conn,
                    first,
                    &format!("f{index}"),
                    &format!("2026-01-0{}", index + 1),
                    "pending",
                )
            })
            .collect::<Vec<_>>();
        let second_id = seed_listed_post(&conn, second, "s0", "2026-01-01", "partial");

        let before = schedule_round_order(&conn, false).unwrap().posts;
        assert_eq!(before.len(), 4);
        assert_eq!(
            before.iter().map(|post| post.post_id).collect::<Vec<_>>(),
            vec![first_ids[0], second_id, first_ids[1], first_ids[2]],
            "turn one takes one from each, then the backlog continues"
        );

        // A third creator joins with a subscription that has no outstanding work
        // at all: everything it has is already settled.
        let idle = auto_subscription(&conn, "fanbox", "2003", "/pictures/idle");
        let settled = seed_listed_post(&conn, idle, "idle0", "2025-06-01", "verified");
        assert!(!claimable_posts(&conn, false)
            .unwrap()
            .iter()
            .any(|(id, _)| *id == settled));

        let after = schedule_round_order(&conn, false).unwrap().posts;
        assert_eq!(
            after, before,
            "a subscription with no outstanding post is not a turn"
        );
        assert!(
            !after.iter().any(|post| post.subscription_id == idle),
            "and it contributes nothing to the round"
        );
    }

    /// `count` outstanding posts on one day, seeded in bulk: a backlog large
    /// enough to reach the round's per-subscription cap would make the per-post
    /// helper the slowest thing in the suite.
    fn seed_pending_backlog(conn: &Connection, sub_id: i64, count: usize, day: &str) -> Vec<i64> {
        let mut stmt = conn
            .prepare(
                "INSERT INTO kemono_posts (
                     subscription_id, post_id, status, created_at, updated_at,
                     published_at, assessment_state, manifest_version, manifest_fingerprint
                 ) VALUES (?1, ?2, 'pending', 't', 't', ?3, 'pending', 1, 'seed')",
            )
            .unwrap();
        let mut ids = Vec::with_capacity(count);
        for index in 0..count {
            stmt.execute(params![
                sub_id,
                format!("bulk{index:06}"),
                format!("{day}T12:00:00")
            ])
            .unwrap();
            ids.push(conn.last_insert_rowid());
        }
        ids
    }

    /// A creator with more outstanding works than one round takes is cut, and the
    /// round reports the cut instead of looking complete.
    ///
    /// The queue used to be built from every outstanding post in the database, so
    /// a 200k backlog was materialized in full before the first file was fetched.
    /// The cut is per subscription and not a global `LIMIT`: a global one takes
    /// the globally oldest posts, so a creator whose backlog is all recent drops
    /// out of the round entirely — the unfairness the rotation exists to remove.
    #[test]
    fn a_round_takes_a_bounded_share_of_a_backlog_and_reports_what_it_left() {
        let conn = test_conn();
        let cap = PAWCHIVE_ROUND_MAX_POSTS_PER_SUBSCRIPTION;
        let big = auto_subscription(&conn, "fanbox", "3101", "/pictures/big");
        let recent = auto_subscription(&conn, "fanbox", "3102", "/pictures/recent");
        let big_ids = seed_pending_backlog(&conn, big, cap + 5, "2026-01-01");
        let recent_id = seed_listed_post(&conn, recent, "recent0", "2026-06-01", "pending");

        let queue = schedule_round_order(&conn, false).unwrap();

        assert_eq!(
            queue.outstanding,
            cap + 6,
            "the count is the whole backlog, before the cut"
        );
        assert_eq!(
            queue.posts.len(),
            cap + 1,
            "one round takes the cap from the big creator and all of the small one"
        );
        assert!(
            queue.truncated(),
            "a backlog larger than one round is reported, not silently shortened"
        );
        assert_eq!(
            queue
                .posts
                .iter()
                .filter(|post| post.subscription_id == big)
                .count(),
            cap,
            "the big creator is cut at the cap, not at the backlog"
        );
        assert_eq!(
            queue.posts[0].post_id, big_ids[0],
            "and the cut keeps the oldest gap first"
        );
        assert_eq!(
            queue.posts[1].post_id, recent_id,
            "the newer creator still gets the first turn, because the cut is per subscription"
        );
    }

    /// A backlog that ends exactly at the cap is not a cut backlog.
    #[test]
    fn a_backlog_that_ends_at_the_cap_is_not_reported_as_cut() {
        let conn = test_conn();
        let cap = PAWCHIVE_ROUND_MAX_POSTS_PER_SUBSCRIPTION;
        let sub = auto_subscription(&conn, "fanbox", "3201", "/pictures/exact");
        seed_pending_backlog(&conn, sub, cap, "2026-01-01");

        let queue = schedule_round_order(&conn, false).unwrap();

        assert_eq!(queue.posts.len(), cap);
        assert_eq!(queue.outstanding, cap);
        assert!(
            !queue.truncated(),
            "a backlog that fits in one round is not a backlog that was cut"
        );
    }

    /// The cut is derived from the two numbers rather than carried as a flag, so
    /// it cannot contradict them. A stored flag could say `truncated` over a
    /// difference of zero, and then the count and the flag disagree about the
    /// same backlog.
    #[test]
    fn a_queue_is_cut_exactly_when_it_holds_fewer_posts_than_the_backlog() {
        let post = ScheduledPost {
            post_id: 1,
            subscription_id: 1,
            artist_id: None,
            day: Some("2026-01-01".to_string()),
        };
        assert!(!RoundQueue {
            posts: vec![post.clone()],
            outstanding: 1,
        }
        .truncated());
        assert!(
            !RoundQueue {
                posts: Vec::new(),
                outstanding: 0,
            }
            .truncated(),
            "an empty library is not a cut round"
        );
        assert!(RoundQueue {
            posts: vec![post],
            outstanding: 2,
        }
        .truncated());
    }

    /// Seven rows, three pages of three: the walk reaches every row exactly once,
    /// the total stays the whole filtered set, and the revision does not move
    /// under the walk.
    #[test]
    fn a_page_walk_reaches_every_row_once_under_one_revision() {
        let conn = test_conn();
        let sub = auto_subscription(&conn, "fanbox", "3001", "/pictures/a");
        let ids = (0..7)
            .map(|index| {
                seed_listed_post(
                    &conn,
                    sub,
                    &format!("p{index}"),
                    &format!("2026-01-0{}", index + 1),
                    "pending",
                )
            })
            .collect::<Vec<_>>();

        let mut cursor: Option<String> = None;
        let mut seen: Vec<i64> = Vec::new();
        let mut revisions: Vec<String> = Vec::new();
        let mut truncated_flags: Vec<bool> = Vec::new();
        loop {
            let page = list_artist_posts_page(
                &conn,
                Some(sub),
                cursor.as_deref(),
                Some(3),
                PostListFilter::default(),
            )
            .unwrap();
            assert_eq!(
                page.total, 7,
                "the total counts the whole filtered set on every page"
            );
            revisions.push(page.snapshot_revision.clone());
            truncated_flags.push(page.truncated);
            seen.extend(page.posts.iter().map(|row| row.id));
            match page.next_cursor {
                Some(next) => cursor = Some(next),
                None => break,
            }
        }
        assert_eq!(seen, ids, "all seven, once each, in order");
        assert_eq!(truncated_flags, vec![true, true, false]);
        assert_eq!(
            revisions.len(),
            3,
            "the revision must not end the walk early"
        );
        assert!(
            revisions.iter().all(|value| *value == revisions[0]),
            "an unchanged set keeps one revision"
        );
        assert!(revisions[0].starts_with("snap_"));
    }

    /// A post discovered between two pages is not a row the walk repeats and not
    /// one it skips past.
    ///
    /// Implemented behaviour, tested as implemented: `snapshot_revision` is a
    /// digest of the filtered set, so it *does* change once the set changes. The
    /// cursor is a sort key rather than a row id or an offset, which is what keeps
    /// the in-flight walk continuous across that change.
    #[test]
    fn a_post_inserted_mid_walk_never_repeats_or_skips_a_row() {
        let conn = test_conn();
        let sub = auto_subscription(&conn, "fanbox", "3101", "/pictures/a");
        let ids = (0..7)
            .map(|index| {
                seed_listed_post(
                    &conn,
                    sub,
                    &format!("p{index}"),
                    &format!("2026-01-0{}", index + 1),
                    "pending",
                )
            })
            .collect::<Vec<_>>();

        let first =
            list_artist_posts_page(&conn, Some(sub), None, Some(3), PostListFilter::default())
                .unwrap();
        assert_eq!(
            first.posts.iter().map(|row| row.id).collect::<Vec<_>>(),
            ids[0..3]
        );
        assert_eq!(first.total, 7);
        let first_revision = first.snapshot_revision.clone();

        // A post arrives that sorts *before* everything the walk has passed, so
        // the rows already shown shift down one position.
        let inserted = seed_listed_post(&conn, sub, "p-new", "2025-12-31", "pending");

        let mut walked = first.posts.iter().map(|row| row.id).collect::<Vec<i64>>();
        let mut cursor = first.next_cursor.clone();
        let mut revisions = Vec::new();
        while let Some(token) = cursor {
            let page = list_artist_posts_page(
                &conn,
                Some(sub),
                Some(&token),
                Some(3),
                PostListFilter::default(),
            )
            .unwrap();
            assert_eq!(page.total, 8, "a fresh page counts the set as it is now");
            assert_ne!(
                page.snapshot_revision, first_revision,
                "the revision describes the set, and the set changed"
            );
            revisions.push(page.snapshot_revision.clone());
            walked.extend(page.posts.iter().map(|row| row.id));
            cursor = page.next_cursor.clone();
        }
        assert_eq!(
            walked, ids,
            "the seven rows the walk had to reach, once each and in order"
        );
        assert!(
            !walked.contains(&inserted),
            "the new row sorts behind the cursor, so it is not inserted into the middle of the walk"
        );
        assert!(revisions.iter().all(|value| *value == revisions[0]));

        // A walk that starts now sees the new set, new row first.
        let fresh =
            list_artist_posts_page(&conn, Some(sub), None, Some(50), PostListFilter::default())
                .unwrap();
        assert_eq!(fresh.total, 8);
        assert_eq!(fresh.posts[0].id, inserted);
        assert_eq!(fresh.snapshot_revision, revisions[0]);
        assert!(!fresh.truncated);
    }

    /// Day, state, search and artist each narrow the set, and each narrows the
    /// total with it.
    #[test]
    fn day_state_search_and_artist_each_narrow_the_set_and_its_total() {
        let conn = test_conn();
        conn.execute("INSERT INTO artists (id, name) VALUES (7, 'Alice')", [])
            .unwrap();
        let bound =
            upsert_subscription(&conn, "fanbox", "4001", Some(7), "/pictures/alice", None).unwrap();
        conn.execute(
            "UPDATE kemono_subscriptions SET enabled = 1, mode = 'auto' WHERE id = ?1",
            params![bound],
        )
        .unwrap();
        let unbound = auto_subscription(&conn, "fanbox", "4002", "/pictures/bob");

        let harbour = seed_listed_post(&conn, bound, "1001", "2026-03-01", "pending");
        let market = seed_listed_post(&conn, bound, "1002", "2026-03-02", "verified");
        let sketch = seed_listed_post(&conn, unbound, "2002", "2026-03-02", "pending");
        for (id, title) in [
            (harbour, "Sunset over the harbour"),
            (market, "Night market"),
            (sketch, "Sunset sketch"),
        ] {
            conn.execute(
                "UPDATE kemono_posts SET title = ?1 WHERE id = ?2",
                params![title, id],
            )
            .unwrap();
        }

        let ids = |filter: PostListFilter| {
            let page = list_artist_posts_page(&conn, None, None, Some(50), filter).unwrap();
            (
                page.posts.iter().map(|row| row.id).collect::<Vec<_>>(),
                page.total,
            )
        };

        assert_eq!(
            ids(PostListFilter::default()),
            (vec![harbour, market, sketch], 3)
        );

        let by_day = PostListFilter {
            day: Some("2026-03-02".to_string()),
            ..PostListFilter::default()
        };
        assert_eq!(ids(by_day), (vec![market, sketch], 2));

        let by_state = PostListFilter {
            state: Some("pending".to_string()),
            ..PostListFilter::default()
        };
        assert_eq!(ids(by_state), (vec![harbour, sketch], 2));

        let by_title = PostListFilter {
            search: Some("sunset".to_string()),
            ..PostListFilter::default()
        };
        assert_eq!(ids(by_title), (vec![harbour, sketch], 2));

        // The search also reads the source post id, as text.
        let by_post_id = PostListFilter {
            search: Some("002".to_string()),
            ..PostListFilter::default()
        };
        assert_eq!(ids(by_post_id), (vec![market, sketch], 2));

        // A bare numeric query also matches the internal row id when that id
        // exists: the netdisk dispatch form and the works list speak that id.
        // Text matches (a post_id embedding the same digits) keep answering
        // too — the id match is an addition, not a replacement.
        let by_internal_id = PostListFilter {
            search: Some(format!("{}", harbour)),
            ..PostListFilter::default()
        };
        let mut got_ids = ids(by_internal_id).0;
        got_ids.sort();
        let mut expected_id_search = vec![harbour];
        // "1002" embeds a "1", so market answers a search for id 1 as text.
        if "1002".contains(&harbour.to_string()) {
            expected_id_search.push(market);
        }
        expected_id_search.sort();
        assert_eq!(got_ids, expected_id_search);

        // An id search with no textual collisions returns exactly one row.
        let by_wide_id = PostListFilter {
            search: Some(format!("{}", sketch)),
            ..PostListFilter::default()
        };
        assert_eq!(ids(by_wide_id), (vec![sketch], 1));

        // A numeric query matching no id, title, or post_id stays empty.
        let no_hit = PostListFilter {
            search: Some("999999".to_string()),
            ..PostListFilter::default()
        };
        assert_eq!(ids(no_hit), (Vec::<i64>::new(), 0));

        let by_artist = PostListFilter {
            artist_id: Some(7),
            ..PostListFilter::default()
        };
        assert_eq!(ids(by_artist), (vec![harbour, market], 2));

        let combined = PostListFilter {
            day: Some("2026-03-02".to_string()),
            state: Some("pending".to_string()),
            ..PostListFilter::default()
        };
        assert_eq!(ids(combined), (vec![sketch], 1));

        // An empty string is not a filter, it is an unset field.
        let blank = PostListFilter {
            day: Some("  ".to_string()),
            state: Some(String::new()),
            search: Some(String::new()),
            artist_id: None,
        };
        assert_eq!(ids(blank), (vec![harbour, market, sketch], 3));

        // The row carries the artist it was filtered by.
        let page =
            list_artist_posts_page(&conn, Some(bound), None, Some(1), PostListFilter::default())
                .unwrap();
        assert_eq!(page.posts[0].artist_id, Some(7));
        assert_eq!(page.posts[0].artist_name.as_deref(), Some("Alice"));
        assert_eq!(page.posts[0].post_id, "1001");
        assert_eq!(page.posts[0].day, "2026-03-01");
        assert_eq!(page.posts[0].state, "pending");
        assert_eq!(page.posts[0].manifest_version, 1);

        // The asset counts come from the live evidence through the evaluator's
        // own predicates: one required image, nothing proven, one missing.
        insert_test_file(&conn, harbour, "/data/h.png", "h.png", "image", "pending");
        let counted =
            list_artist_posts_page(&conn, Some(bound), None, Some(1), PostListFilter::default())
                .unwrap();
        assert_eq!(counted.posts[0].id, harbour);
        assert_eq!(counted.posts[0].required_assets, 1);
        assert_eq!(counted.posts[0].proven_assets, 0);
        assert_eq!(counted.posts[0].missing_assets, 1);
    }

    /// The limit is clamped the way the rest of the pagination is, and the last
    /// page says so by having no cursor.
    #[test]
    fn the_page_limit_is_clamped_and_the_last_page_has_no_cursor() {
        let conn = test_conn();
        let sub = auto_subscription(&conn, "fanbox", "5001", "/pictures/a");
        for index in 0..3 {
            seed_listed_post(
                &conn,
                sub,
                &format!("p{index}"),
                &format!("2026-04-0{}", index + 1),
                "pending",
            );
        }
        let page = |limit: Option<i64>| {
            list_artist_posts_page(&conn, Some(sub), None, limit, PostListFilter::default())
                .unwrap()
        };

        let clamped_low = page(Some(0));
        assert_eq!(clamped_low.posts.len(), 1, "0 clamps up to 1");
        assert!(clamped_low.truncated);
        assert!(clamped_low.next_cursor.is_some());
        assert_eq!(clamped_low.total, 3);

        assert_eq!(
            page(Some(-9)).posts.len(),
            1,
            "a negative limit clamps to 1"
        );

        let wide = page(Some(9_999));
        assert_eq!(
            wide.posts.len(),
            3,
            "a huge limit is capped at the set, not 200"
        );
        assert!(!wide.truncated);
        assert_eq!(wide.next_cursor, None, "the last page has no cursor");

        let defaulted = page(None);
        assert_eq!(defaulted.posts.len(), 3, "the default is 50, above the set");
        assert_eq!(defaulted.next_cursor, None);

        // A cursor that does not decode is an error, not a page-one restart.
        assert!(list_artist_posts_page(
            &conn,
            Some(sub),
            Some("not-a-cursor"),
            Some(3),
            PostListFilter::default()
        )
        .is_err());
        assert!(list_artist_posts_page(
            &conn,
            Some(sub),
            Some("v2\u{1f}2026-01-01\u{1f}1"),
            Some(3),
            PostListFilter::default()
        )
        .is_err());
    }

    /// The list says whether a work has ever had an explicit manual attempt,
    /// without hiding it or disabling it.
    #[test]
    fn a_recorded_manual_attempt_is_reported_without_hiding_the_row() {
        let conn = test_conn();
        let sub = auto_subscription(&conn, "fanbox", "6001", "/pictures/a");
        let attempted = seed_listed_post(&conn, sub, "p0", "2026-05-01", "verified");
        let untouched = seed_listed_post(&conn, sub, "p1", "2026-05-02", "verified");
        conn.execute(
            "INSERT INTO pawchive_attempts
                 (attempt_id, selection_id, request_id, intent, state, posts, resources,
                  created_at, updated_at)
             VALUES ('a1', 's1', 'r1', 'manual', 'done', 1, 1, 't', 't')",
            [],
        )
        .unwrap();
        conn.execute(
            "INSERT INTO pawchive_attempt_posts
                 (attempt_id, post_id, work_id, state, fetched, error, updated_at)
             VALUES ('a1', ?1, 'w', 'done', 1, '', 't')",
            params![attempted],
        )
        .unwrap();

        let page =
            list_artist_posts_page(&conn, Some(sub), None, Some(50), PostListFilter::default())
                .unwrap();
        assert_eq!(page.total, 2, "an attempt does not remove the row");
        let flag = |id: i64| {
            page.posts
                .iter()
                .find(|row| row.id == id)
                .unwrap()
                .manual_attempt
        };
        assert!(flag(attempted));
        assert!(!flag(untouched));
    }

    /// A new subscription starts manual, and its mode is a stored decision.
    ///
    /// The plan's default is manual so that adding a creator does not begin
    /// fetching before the user has looked at what the source has. Existing
    /// subscriptions get the intent they already carried: `enabled = 1` was the
    /// user asking for automatic rounds, and reading it as manual would quietly
    /// stop a running install — hence the one-time migration asserted here.
    #[test]
    fn a_new_subscription_is_manual_and_an_existing_one_keeps_its_intent() {
        let conn = test_conn();
        let id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures/a", None).unwrap();
        let record = get_subscription(&conn, id).unwrap().unwrap();
        assert_eq!(record.mode, SubscriptionMode::Manual);
        assert!(!record.mode.is_auto());
        assert!(!record.enabled, "and it starts disabled too");

        // The round-trip through the API shape carries the mode as a word.
        let json = serde_json::to_value(&record).unwrap();
        assert_eq!(json["mode"], "manual");
        let parsed: SubscriptionRecord = serde_json::from_value(json).unwrap();
        assert_eq!(parsed.mode, SubscriptionMode::Manual);
        // A record written before the field existed reads as manual.
        assert_eq!(SubscriptionMode::parse(""), SubscriptionMode::Manual);
        assert_eq!(SubscriptionMode::parse("AUTO"), SubscriptionMode::Auto);
        assert_eq!(
            SubscriptionMode::parse("nonsense"),
            SubscriptionMode::Manual
        );

        // Switching modes is what the route does: it changes the claim rule and
        // nothing else.
        assert!(set_subscription_mode(&conn, id, SubscriptionMode::Auto).unwrap());
        assert_eq!(
            get_subscription(&conn, id).unwrap().unwrap().mode,
            SubscriptionMode::Auto
        );
        assert!(!set_subscription_mode(&conn, 999_999, SubscriptionMode::Auto).unwrap());

        // A database whose rows predate the column: enabling a subscription was
        // the automatic intent, so the one-time migration has to say so.
        let legacy = Connection::open_in_memory().unwrap();
        legacy
            .execute_batch(
                "CREATE TABLE app_settings (
                     key TEXT PRIMARY KEY,
                     value TEXT NOT NULL,
                     updated_at REAL NOT NULL DEFAULT (strftime('%s','now'))
                 );
                 CREATE TABLE artists (id INTEGER PRIMARY KEY, name TEXT, path TEXT);
                 CREATE TABLE kemono_subscriptions (
                     id INTEGER PRIMARY KEY AUTOINCREMENT,
                     site_id TEXT NOT NULL DEFAULT 'pawchive',
                     service TEXT NOT NULL,
                     user_id TEXT NOT NULL,
                     artist_id INTEGER REFERENCES artists(id),
                     target_dir TEXT NOT NULL,
                     enabled INTEGER NOT NULL DEFAULT 0,
                     since_date TEXT,
                     check_interval_hours INTEGER NOT NULL DEFAULT 6,
                     last_discovery_at TEXT,
                     last_error TEXT,
                     created_at TEXT NOT NULL,
                     updated_at TEXT NOT NULL,
                     discovery_offset INTEGER NOT NULL DEFAULT 0,
                     discovery_complete INTEGER NOT NULL DEFAULT 0,
                     UNIQUE(site_id, service, user_id)
                 );",
            )
            .unwrap();
        legacy
            .execute_batch(
                "INSERT INTO kemono_subscriptions
                     (site_id, service, user_id, target_dir, enabled, created_at, updated_at)
                 VALUES ('pawchive', 'fanbox', 'legacy-on', '/pictures/on', 1, 't', 't'),
                        ('pawchive', 'fanbox', 'legacy-off', '/pictures/off', 0, 't', 't');",
            )
            .unwrap();
        // Migrating this install: the column arrives (in production via
        // `ensure_columns`, replayed here), and the enabled flag has to survive
        // as the mode it always was.
        legacy
            .execute(
                "ALTER TABLE kemono_subscriptions ADD COLUMN mode TEXT NOT NULL DEFAULT 'manual'",
                [],
            )
            .unwrap();
        migrate_subscription_modes(&legacy).unwrap();
        let modes: Vec<(String, String)> = legacy
            .prepare("SELECT user_id, mode FROM kemono_subscriptions ORDER BY user_id")
            .unwrap()
            .query_map([], |row| Ok((row.get(0)?, row.get(1)?)))
            .unwrap()
            .collect::<rusqlite::Result<Vec<_>>>()
            .unwrap();
        assert_eq!(
            modes,
            vec![
                ("legacy-off".to_string(), "manual".to_string()),
                ("legacy-on".to_string(), "auto".to_string()),
            ]
        );

        // A user who then chooses manual keeps it: the migration is keyed on a
        // marker, not re-run at every startup.
        set_subscription_mode(&legacy, 1, SubscriptionMode::Manual).unwrap();
        migrate_subscription_modes(&legacy).unwrap();
        let kept: String = legacy
            .query_row(
                "SELECT mode FROM kemono_subscriptions WHERE user_id = 'legacy-on'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(
            kept, "manual",
            "re-running the migration must not overwrite the user's own choice"
        );

        // And a subscription added after the migration is manual even with the
        // enable switch on, because manual is what the user chose to keep.
        legacy
            .execute(
                "INSERT INTO kemono_subscriptions
                     (site_id, service, user_id, target_dir, enabled, mode, created_at, updated_at)
                 VALUES ('pawchive', 'fanbox', 'added-later', '/pictures/new', 1, 'manual', 't', 't')",
                [],
            )
            .unwrap();
        migrate_subscription_modes(&legacy).unwrap();
        let later: String = legacy
            .query_row(
                "SELECT mode FROM kemono_subscriptions WHERE user_id = 'added-later'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(later, "manual");
    }

    /// An explicit selection is frozen per request id, and it names what the
    /// evaluator would say is still owed — a resource with strong evidence is
    /// reported as covered rather than as a gap.
    #[test]
    fn a_selection_freezes_what_the_user_reviewed() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures/artist", None)
                .unwrap();
        let post = insert_test_post(&conn, sub_id, "900");
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "pending");
        insert_test_file(&conn, post, "/data/b.png", "b.png", "image", "pending");
        let settings = PawchiveSettings::default();

        // One file already has a fetch behind it: the plan reports the split.
        let work_id = record_work_observation(&conn, post, ManifestCompleteness::Complete)
            .unwrap()
            .unwrap();
        let a_version = resource_version_id_for(&work_id, "/a.png", UNKNOWN_VERSION);
        conn.execute(
            "INSERT INTO pawchive_acquisition_events
                 (event_id, idempotency_key, work_id, resource_version_id, attempt_id,
                  evidence_source, evidence_strength, publish_job_id, acquired_at,
                  historical_path, created_at)
             VALUES ('e1', 'k1', ?1, ?2, '', 'publish_ledger', 'strong', NULL, 't', '', 't')",
            params![work_id, a_version],
        )
        .unwrap();

        let plan = plan_manual_post(&conn, post, &settings).unwrap().unwrap();
        assert_eq!(plan.post_id_value, "900");
        assert_eq!(plan.work_id, work_id);
        assert_eq!(plan.resources.len(), 2);
        let by_key = |key: &str| {
            plan.resources
                .iter()
                .find(|resource| resource.resource_key == key)
                .unwrap()
                .clone()
        };
        assert_eq!(by_key("/a.png").planned_state, "covered");
        assert_eq!(by_key("/b.png").planned_state, "fetch");
        assert!(!plan.no_direct_resources);

        // Freezing the same request twice is the same selection.
        let first = record_selection(&conn, "req-1", &[post], &[], &settings).unwrap();
        assert!(!first.reused);
        assert_eq!(first.posts, 1);
        assert_eq!(first.resources, 2);
        let again = record_selection(&conn, "req-1", &[post], &[], &settings).unwrap();
        assert!(again.reused, "the same request id is the same task");
        assert_eq!(again.selection_id, first.selection_id);

        // The same id with a different body is a conflict, not a new selection.
        assert!(matches!(
            record_selection(&conn, "req-1", &[post, post], &[1], &settings),
            Err(SelectionError::RequestConflict)
        ));

        // A request id with no posts, or a post the ledger does not know, is
        // refused rather than recorded as an empty selection.
        assert!(matches!(
            record_selection(&conn, "req-2", &[], &[], &settings),
            Err(SelectionError::UnknownPosts(_))
        ));
        assert!(matches!(
            record_selection(&conn, "req-3", &[9_999], &[], &settings),
            Err(SelectionError::UnknownPosts(ids)) if ids == vec![9_999]
        ));

        // A resource list narrows the frozen selection, and a file that belongs
        // to another post cannot be smuggled in.
        let only_a: i64 = conn
            .query_row(
                "SELECT id FROM kemono_files WHERE post_id = ?1 AND remote_path = '/a.png'",
                params![post],
                |row| row.get(0),
            )
            .unwrap();
        let narrowed = record_selection(&conn, "req-4", &[post], &[only_a], &settings).unwrap();
        assert_eq!(narrowed.resources, 1);
        // A second request id asking for the other file gets its own row, and
        // re-sending it is still the same selection.
        let other: i64 = conn
            .query_row(
                "SELECT id FROM kemono_files WHERE post_id = ?1 AND remote_path = '/b.png'",
                params![post],
                |row| row.get(0),
            )
            .unwrap();
        let other_selection =
            record_selection(&conn, "req-5", &[post], &[other], &settings).unwrap();
        assert_eq!(other_selection.resources, 1);
        assert_ne!(other_selection.selection_id, narrowed.selection_id);
        assert!(
            record_selection(&conn, "req-5", &[post], &[other], &settings)
                .unwrap()
                .reused
        );

        // The type selection is part of the plan: a type switched off does not
        // appear as a resource to fetch.
        let mut images_off = PawchiveSettings::default();
        images_off.download_images = false;
        let narrowed_plan = plan_manual_post(&conn, post, &images_off).unwrap().unwrap();
        assert!(narrowed_plan.resources.is_empty());
        assert!(narrowed_plan.no_direct_resources);
    }

    /// "全选当前筛选" is one request that names a filter, not the tens of thousands
    /// of ids that filter stands for.
    ///
    /// The panel cannot post the id list it is standing in for: a creator with a
    /// hundred thousand works would put the whole review into one request body,
    /// which is exactly what the filter form exists to avoid. So the server
    /// resolves the filter into the same works the manual list shows and freezes
    /// them, and the request body stays a filter.
    #[test]
    fn a_filter_selection_freezes_the_works_the_filter_shows() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures1/artist", None)
                .unwrap();
        let mut ids = Vec::new();
        for (post_id, published, title, state) in [
            ("901", "2026-01-05T10:00:00", "alpha", "pending"),
            ("902", "2026-02-10T10:00:00", "beta", "pending"),
            ("903", "2026-03-02T10:00:00", "gamma", "verified"),
        ] {
            let id = insert_test_post(&conn, sub_id, post_id);
            conn.execute(
                "UPDATE kemono_posts SET published_at = ?1, title = ?2, assessment_state = ?3
                 WHERE id = ?4",
                params![published, title, state, id],
            )
            .unwrap();
            insert_test_file(
                &conn,
                id,
                &format!("/data/{post_id}.png"),
                "a.png",
                "image",
                "pending",
            );
            ids.push(id);
        }
        let settings = PawchiveSettings::default();

        // No filter at all means the whole list, which is the list's own answer
        // to an empty filter rather than a second meaning invented here.
        let (all, truncated) =
            list_filtered_post_ids(&conn, None, &PostListFilter::default(), 50).unwrap();
        assert_eq!(all, ids, "the whole filtered set, in the list's own order");
        assert!(!truncated);

        // A state filter narrows it exactly as the list's `state` filter does.
        let pending = PostListFilter {
            state: Some("pending".to_string()),
            ..PostListFilter::default()
        };
        let (pending_ids, _) = list_filtered_post_ids(&conn, None, &pending, 50).unwrap();
        assert_eq!(pending_ids, vec![ids[0], ids[1]]);

        // The subscription the works belong to is not the filter: a request
        // scoped to another subscription resolves to nothing rather than to
        // every work in the library.
        let (scoped, _) = list_filtered_post_ids(&conn, Some(sub_id + 1000), &pending, 50).unwrap();
        assert!(
            scoped.is_empty(),
            "a filter scoped elsewhere matches nothing"
        );

        // Freezing by filter reaches the same outcome an explicit list would.
        let frozen =
            record_selection_for_filter(&conn, "req-filter-1", None, &pending, &[], &settings)
                .unwrap();
        assert_eq!(frozen.matched, 2);
        assert!(!frozen.truncated);
        assert_eq!(frozen.outcome.posts, 2, "both works were planned");
        assert_eq!(frozen.outcome.resources, 2, "one image each");
        assert!(
            conn.query_row(
                "SELECT COUNT(*) FROM pawchive_selection_members WHERE selection_id = ?1",
                params![frozen.outcome.selection_id],
                |row| row.get::<_, i64>(0),
            )
            .unwrap()
                > 0,
            "the selection is materialised, not just counted"
        );
        // Re-sending the same request id is the same selection, so the filter
        // form is idempotent the way the explicit form is.
        let again =
            record_selection_for_filter(&conn, "req-filter-1", None, &pending, &[], &settings)
                .unwrap();
        assert!(again.outcome.reused);
        assert_eq!(again.outcome.selection_id, frozen.outcome.selection_id);

        // A filter that matches nothing is refused: an empty selection is not a
        // task, and answering with one would look accepted.
        let none = PostListFilter {
            search: Some("no such title anywhere".to_string()),
            ..PostListFilter::default()
        };
        assert!(matches!(
            record_selection_for_filter(&conn, "req-filter-2", None, &none, &[], &settings),
            Err(SelectionError::UnknownPosts(ids)) if ids.is_empty()
        ));
    }

    /// The cap is a bound on the freeze, and the caller learns when it bit.
    ///
    /// Without it the read materialises the entire backlog before the first file
    /// is fetched; with it the read asks for one row more than it may keep, so
    /// the query itself answers whether the filter held more.
    #[test]
    fn a_filter_selection_reports_when_the_cap_left_works_out() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures1/artist", None)
                .unwrap();
        let mut expected = Vec::new();
        for index in 0..7 {
            let id = insert_test_post(&conn, sub_id, &format!("60{index}"));
            conn.execute(
                "UPDATE kemono_posts SET published_at = ?1, assessment_state = 'pending'
                 WHERE id = ?2",
                params![format!("2026-04-0{}T10:00:00", index + 1), id],
            )
            .unwrap();
            insert_test_file(&conn, id, "/data/a.png", "a.png", "image", "pending");
            expected.push(id);
        }
        let settings = PawchiveSettings::default();

        let (capped, truncated) =
            list_filtered_post_ids(&conn, None, &PostListFilter::default(), 5).unwrap();
        assert!(truncated, "five of seven rows is a truncated read");
        assert_eq!(
            capped,
            expected[..5].to_vec(),
            "the cap keeps the first rows"
        );

        let (exact, truncated) =
            list_filtered_post_ids(&conn, None, &PostListFilter::default(), 7).unwrap();
        assert!(!truncated, "exactly the cap is not a truncation");
        assert_eq!(exact, expected);

        // Through the freeze itself the same bound holds, and the outcome says
        // how many works the filter matched before the cap was applied.
        let frozen = record_selection_for_filter(
            &conn,
            "req-cap",
            None,
            &PostListFilter {
                day: Some("2026-04-01".to_string()),
                ..PostListFilter::default()
            },
            &[],
            &settings,
        )
        .unwrap();
        assert_eq!(frozen.matched, 1);
        assert!(!frozen.truncated);
        assert_eq!(frozen.outcome.posts, 1, "one day of the filter, one work");
    }

    /// A request creates one task, and a manifest that moved on since the review
    /// is a conflict rather than a silently different request.
    #[test]
    fn an_attempt_is_created_once_per_request_and_detects_a_moved_manifest() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures/artist", None)
                .unwrap();
        let post = insert_test_post(&conn, sub_id, "900");
        let file_id = {
            insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "pending");
            conn.query_row(
                "SELECT id FROM kemono_files WHERE post_id = ?1",
                params![post],
                |row| row.get::<_, i64>(0),
            )
            .unwrap()
        };
        let settings = PawchiveSettings::default();
        let selection = record_selection(&conn, "req-1", &[post], &[], &settings).unwrap();

        let attempt = create_attempt(&conn, "req-1", &selection.selection_id).unwrap();
        assert_eq!(attempt.posts, 1);
        assert_eq!(attempt.resources, 1);
        assert_eq!(attempt.selection_id, selection.selection_id);

        // The same request id is the same task: no second attempt, and the
        // selection is not re-materialised.
        let repeated = create_attempt(&conn, "req-1", &selection.selection_id).unwrap();
        assert_eq!(repeated.attempt_id, attempt.attempt_id);
        assert_eq!(
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_attempts"),
            1,
            "one request is one task"
        );

        // A later request id is a new task even though it names the same work.
        let second_selection = record_selection(&conn, "req-2", &[post], &[], &settings).unwrap();
        let second = create_attempt(&conn, "req-2", &second_selection.selection_id).unwrap();
        assert_ne!(second.attempt_id, attempt.attempt_id);
        assert_eq!(scalar(&conn, "SELECT COUNT(*) FROM pawchive_attempts"), 2);

        // A post whose manifest moved past the reviewed one is reported rather
        // than applied: the user approved a resource set that no longer exists.
        conn.execute(
            "UPDATE kemono_posts SET manifest_version = manifest_version + 1 WHERE id = ?1",
            params![post],
        )
        .unwrap();
        let third_selection = record_selection(&conn, "req-3", &[post], &[], &settings).unwrap();
        let third = create_attempt(&conn, "req-3", &third_selection.selection_id).unwrap();
        mark_attempt_post(&conn, &third.attempt_id, post, "conflict", 0, "清单已变更").unwrap();
        let state: String = conn
            .query_row(
                "SELECT state FROM pawchive_attempt_posts WHERE attempt_id = ?1 AND post_id = ?2",
                params![third.attempt_id, post],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(state, "conflict");
        // The conflict is recorded against the task, and it does not touch the
        // resource row the earlier delivery used.
        assert_eq!(
            conn.query_row(
                "SELECT status FROM kemono_files WHERE id = ?1",
                params![file_id],
                |row| row.get::<_, String>(0)
            )
            .unwrap(),
            "pending"
        );

        // An expired selection is refused rather than applied late.
        conn.execute(
            "UPDATE pawchive_selections SET expires_at = '2000-01-01T00:00:00+00:00'
             WHERE selection_id = ?1",
            params![selection.selection_id],
        )
        .unwrap();
        assert!(matches!(
            create_attempt(&conn, "", &selection.selection_id),
            Err(AttemptError::SelectionExpired(id)) if id == selection.selection_id
        ));

        // A selection with no resource this side may fetch is refused, so the
        // panel can report the reason instead of "downloaded 0 files".
        conn.execute(
            "UPDATE kemono_files SET present_in_manifest = 0 WHERE post_id = ?1",
            params![post],
        )
        .unwrap();
        let empty = record_selection(&conn, "req-4", &[post], &[], &settings).unwrap();
        assert!(matches!(
            create_attempt(&conn, "req-4", &empty.selection_id),
            Err(AttemptError::SelectionEmpty(id)) if id == empty.selection_id
        ));
    }

    /// A manual re-fetch of a resource whose file is already on disk gets a
    /// target of its own instead of writing over the user's arranged copy.
    #[test]
    fn a_manual_refetch_never_overwrites_the_delivered_file() {
        use tempfile::tempdir;

        let dir = tempdir().unwrap();
        let (conn, _sub_id, post) = evaluator_fixture();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "done");
        let file_id: i64 = conn
            .query_row(
                "SELECT id FROM kemono_files WHERE post_id = ?1",
                params![post],
                |row| row.get(0),
            )
            .unwrap();
        // The earlier delivery sits at a real path inside the authorized root.
        let delivered = dir.path().join("delivered/a.png");
        std::fs::create_dir_all(delivered.parent().unwrap()).unwrap();
        std::fs::write(&delivered, b"the file the user already has").unwrap();

        let attempt = {
            let settings = PawchiveSettings::default();
            let selection = record_selection(&conn, "req-manual", &[post], &[], &settings).unwrap();
            create_attempt(&conn, "req-manual", &selection.selection_id).unwrap()
        };

        let policy = DownloadPostPolicy::Manual {
            attempt_id: &attempt.attempt_id,
            force_file_ids: &[file_id],
        };
        // The pass is scoped to the resource the request named.
        assert!(!policy.excludes_file(file_id));
        assert!(
            policy.excludes_file(file_id + 1),
            "another resource is out of scope"
        );
        assert!(policy.is_manual());
        // The publish ledger keys the delivery on this attempt, which is what
        // makes a genuine re-fetch a new job instead of a hit on the old one.
        assert_eq!(
            policy.job_scope("900", 1),
            format!("900:1:{}", attempt.attempt_id)
        );
        // The target is stable per attempt and resource, and distinct from the
        // automatic name, so the delivered file is never the write target.
        let suffix = attempt_target_suffix(post, file_id, policy);
        assert_eq!(suffix.len(), 8, "a short stable suffix");
        assert_eq!(
            suffix,
            attempt_target_suffix(post, file_id, policy),
            "the same attempt and resource always lands on the same target"
        );
        let other = attempt_target_suffix(
            post,
            file_id,
            DownloadPostPolicy::Manual {
                attempt_id: "another-attempt",
                force_file_ids: &[file_id],
            },
        );
        assert_ne!(suffix, other, "a later attempt gets its own name");
        let suffixed = with_stable_suffix(&delivered, &suffix);
        assert_ne!(suffixed, delivered);
        assert!(
            suffixed.to_string_lossy().contains(&suffix),
            "{}",
            suffixed.display()
        );
        // The original file is untouched by computing the target.
        assert_eq!(
            std::fs::read(&delivered).unwrap(),
            b"the file the user already has"
        );
        // The automatic policy keeps the name it always used.
        assert_eq!(DownloadPostPolicy::Automatic.job_scope("900", 1), "900:1");
        assert!(!DownloadPostPolicy::Automatic.is_manual());
        assert!(DownloadPostPolicy::Automatic.honours_assessment());
        assert!(
            !policy.honours_assessment(),
            "a manual pass is not filtered by the derived state"
        );
    }

    /// A publish whose ledger write never landed is restored from the publish
    /// ledger instead of being fetched a second time — but only when the file
    /// at the reserved target is still the artifact the publish recorded.
    #[test]
    fn a_published_file_whose_download_row_was_not_written_is_restored() {
        use tempfile::tempdir;

        let dir = tempdir().unwrap();
        let roots = MediaRoots::identical(
            vec![dir.path().to_string_lossy().to_string()],
            vec!["test".to_string()],
        );
        let (conn, _, post) = evaluator_fixture();
        conn.execute(
            "UPDATE kemono_posts SET post_id = '900001' WHERE id = ?1",
            params![post],
        )
        .unwrap();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "downloading");
        let file_id: i64 = conn
            .query_row(
                "SELECT id FROM kemono_files WHERE post_id = ?1",
                params![post],
                |row| row.get(0),
            )
            .unwrap();
        let published = dir.path().join("a.png");
        let payload = b"published bytes";
        std::fs::write(&published, payload).unwrap();
        conn.execute(
            "INSERT INTO download_publish_jobs
                 (engine, source_job_id, manifest_version, source_identity, expected_length,
                  expected_blake3, target_path, stage)
             VALUES ('pawchive', ?1, 1, '/data/a.png', 15, ?2, ?3, 'published')",
            params![
                format!("900001:{file_id}"),
                blake3::hash(payload).to_hex().to_string(),
                published.to_string_lossy()
            ],
        )
        .unwrap();

        assert_eq!(reconcile_published_files(&conn, &roots).unwrap(), 1);
        let (status, source, job): (String, String, Option<i64>) = conn
            .query_row(
                "SELECT status, delivery_source, publish_job_id FROM kemono_files WHERE id = ?1",
                params![file_id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .unwrap();
        assert_eq!(status, "done");
        assert_eq!(source, "download");
        assert!(job.is_some());

        // A job whose file is gone restores nothing.
        std::fs::remove_file(&published).unwrap();
        conn.execute(
            "UPDATE kemono_files SET status = 'downloading', delivery_source = '' WHERE id = ?1",
            params![file_id],
        )
        .unwrap();
        assert_eq!(reconcile_published_files(&conn, &roots).unwrap(), 0);
    }

    /// Recovery is not a length check. A target replaced by a same-size file,
    /// a symlink to one, or a file outside the media roots must not be claimed
    /// as this install's own completed download.
    #[test]
    fn publish_recovery_rejects_anything_that_is_not_the_recorded_artifact() {
        use tempfile::tempdir;

        let dir = tempdir().unwrap();
        let outside = tempdir().unwrap();
        let roots = MediaRoots::identical(
            vec![dir.path().to_string_lossy().to_string()],
            vec!["test".to_string()],
        );
        let (conn, _, post) = evaluator_fixture();
        conn.execute(
            "UPDATE kemono_posts SET post_id = '900002' WHERE id = ?1",
            params![post],
        )
        .unwrap();
        let payload = b"YES";
        let target = dir.path().join("replaced.png");
        let identity = "/data/a.png";
        let expected = blake3::hash(payload).to_hex().to_string();
        insert_test_file(&conn, post, identity, "a.png", "image", "downloading");
        let file_id: i64 = conn
            .query_row(
                "SELECT id FROM kemono_files WHERE post_id = ?1",
                params![post],
                |row| row.get(0),
            )
            .unwrap();
        let job = |target: &Path| {
            format!(
                "INSERT INTO download_publish_jobs
                     (engine, source_job_id, manifest_version, source_identity, expected_length,
                      expected_blake3, target_path, stage)
                 VALUES ('pawchive', '900002:{file_id}', 1, '{identity}', 3, '{expected}', '{}', 'published')",
                target.to_string_lossy()
            )
        };
        let reset = |conn: &Connection| {
            conn.execute(
                "UPDATE kemono_files SET status = 'downloading', delivery_source = '' WHERE id = ?1",
                params![file_id],
            )
            .unwrap();
        };

        // Same length, different content.
        std::fs::write(&target, b"BAD").unwrap();
        conn.execute(&job(&target), []).unwrap();
        assert_eq!(reconcile_published_files(&conn, &roots).unwrap(), 0);

        // A symlink to a file that does hash correctly is still not the artifact
        // this ledger published.
        let real = dir.path().join("real.png");
        std::fs::write(&real, payload).unwrap();
        std::fs::remove_file(&target).unwrap();
        #[cfg(unix)]
        std::os::unix::fs::symlink(&real, &target).unwrap();
        #[cfg(not(unix))]
        std::fs::copy(&real, &target).unwrap();
        if std::fs::symlink_metadata(&target)
            .map(|meta| meta.file_type().is_symlink())
            .unwrap_or(false)
        {
            reset(&conn);
            assert_eq!(reconcile_published_files(&conn, &roots).unwrap(), 0);
        }

        // The correct bytes, but outside the authorized roots.
        let stray = outside.path().join("stray.png");
        std::fs::write(&stray, payload).unwrap();
        conn.execute(
            "UPDATE download_publish_jobs SET target_path = ?1 WHERE source_job_id = ?2",
            params![stray.to_string_lossy(), format!("900002:{file_id}")],
        )
        .unwrap();
        reset(&conn);
        assert_eq!(reconcile_published_files(&conn, &roots).unwrap(), 0);

        // The recorded artifact in place is restored, and its integrity verdict
        // is written down rather than assumed.
        conn.execute(
            "UPDATE download_publish_jobs SET target_path = ?1 WHERE source_job_id = ?2",
            params![real.to_string_lossy(), format!("900002:{file_id}")],
        )
        .unwrap();
        reset(&conn);
        assert_eq!(reconcile_published_files(&conn, &roots).unwrap(), 1);
        let (integrity, hash_source, local): (String, String, String) = conn
            .query_row(
                "SELECT integrity, hash_source, local_hash FROM kemono_files WHERE id = ?1",
                params![file_id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .unwrap();
        assert_eq!(integrity, "verified");
        assert_eq!(hash_source, "local");
        assert_eq!(local, expected);
    }

    /// A ledger row for another manifest version or another resource does not
    /// describe this delivery, however well the file matches.
    #[test]
    fn publish_recovery_requires_the_same_version_and_resource() {
        use tempfile::tempdir;

        let dir = tempdir().unwrap();
        let roots = MediaRoots::identical(
            vec![dir.path().to_string_lossy().to_string()],
            vec!["test".to_string()],
        );
        let (conn, _, post) = evaluator_fixture();
        conn.execute(
            "UPDATE kemono_posts SET post_id = '900003' WHERE id = ?1",
            params![post],
        )
        .unwrap();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "downloading");
        let file_id: i64 = conn
            .query_row(
                "SELECT id FROM kemono_files WHERE post_id = ?1",
                params![post],
                |row| row.get(0),
            )
            .unwrap();
        let target = dir.path().join("a.png");
        let payload = b"published bytes";
        std::fs::write(&target, payload).unwrap();
        let insert = |manifest_version: i64, identity: &str| {
            format!(
                "INSERT INTO download_publish_jobs
                     (engine, source_job_id, manifest_version, source_identity, expected_length,
                      expected_blake3, target_path, stage)
                 VALUES ('pawchive', '900003:{file_id}', {manifest_version}, '{identity}', 15, '{}', '{}', 'published')",
                blake3::hash(payload).to_hex().to_string(),
                target.to_string_lossy()
            )
        };

        // A row published for an older manifest of the same work.
        conn.execute(&insert(0, "/data/a.png"), []).unwrap();
        assert_eq!(reconcile_published_files(&conn, &roots).unwrap(), 0);
        conn.execute("DELETE FROM download_publish_jobs", [])
            .unwrap();

        // A row for a different resource of the same post.
        conn.execute(&insert(1, "/data/b.png"), []).unwrap();
        assert_eq!(reconcile_published_files(&conn, &roots).unwrap(), 0);
        conn.execute("DELETE FROM download_publish_jobs", [])
            .unwrap();

        // The matching row restores it.
        conn.execute(&insert(1, "/data/a.png"), []).unwrap();
        assert_eq!(reconcile_published_files(&conn, &roots).unwrap(), 1);
    }

    /// A file found in place is only presence until a comparable hash proves it.
    #[test]
    fn a_matching_source_hash_upgrades_found_content_to_proof() {
        use tempfile::tempdir;

        let dir = tempdir().unwrap();
        let (conn, _, post) = evaluator_fixture();
        let payload = b"the resource the source published";
        let published = dir.path().join("a.png");
        std::fs::write(&published, payload).unwrap();
        let source_hash = blake3::hash(payload).to_hex().to_string();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "done");
        conn.execute(
            "UPDATE kemono_files
             SET delivery_source = 'present', target_path = ?1, expected_blake3 = ?2
             WHERE post_id = ?3",
            params![published.to_string_lossy(), source_hash, post],
        )
        .unwrap();
        let settings = PawchiveSettings::default();

        // Presence alone is not proof.
        let before = reassess_post(&conn, post, &settings).unwrap();
        assert_eq!(before.state, PostState::Unverified);
        assert_eq!(before.proven_assets, 0);

        let file_id: i64 = conn
            .query_row(
                "SELECT id FROM kemono_files WHERE post_id = ?1",
                params![post],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(verify_file_hash(&conn, file_id).unwrap(), Some(true));

        let after = reassess_post(&conn, post, &settings).unwrap();
        assert_eq!(after.state, PostState::Verified);
        assert_eq!(after.proven_assets, 1);

        // A file whose content is not the resource stays unproven and is named.
        let other = dir.path().join("other.png");
        std::fs::write(&other, b"something else entirely").unwrap();
        conn.execute(
            "UPDATE kemono_files SET target_path = ?1 WHERE id = ?2",
            params![other.to_string_lossy(), file_id],
        )
        .unwrap();
        assert_eq!(verify_file_hash(&conn, file_id).unwrap(), Some(false));
        assert_eq!(
            reassess_post(&conn, post, &settings).unwrap().state,
            PostState::Unverified
        );
    }

    /// A receipt with no comparable hash must not pretend the resource is
    /// verified.
    #[test]
    fn verification_without_a_source_hash_reports_nothing_checked() {
        let (conn, _, post) = evaluator_fixture();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "pending");
        let file_id: i64 = conn
            .query_row(
                "SELECT id FROM kemono_files WHERE post_id = ?1",
                params![post],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(verify_file_hash(&conn, file_id).unwrap(), None);
    }

    /// A check that finds different content has to revoke the proof the
    /// delivery carried. Reporting the mismatch while the post still read as
    /// verified was the defect: the panel said "不一致" and the day still
    /// counted as complete.
    #[test]
    fn a_mismatched_download_loses_its_verified_state() {
        use tempfile::tempdir;

        let dir = tempdir().unwrap();
        let (conn, _, post) = evaluator_fixture();
        let settings = PawchiveSettings::default();
        let payload = b"the bytes the source published";
        let delivered = dir.path().join("a.png");
        std::fs::write(&delivered, payload).unwrap();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "done");
        conn.execute(
            "UPDATE kemono_files
             SET delivery_source = 'download', target_path = ?1, expected_length = ?2,
                 expected_blake3 = ?3, local_hash = ?3, integrity = 'verified', hash_source = 'local'
             WHERE post_id = ?4",
            params![
                delivered.to_string_lossy(),
                payload.len() as i64,
                blake3::hash(payload).to_hex().to_string(),
                post
            ],
        )
        .unwrap();
        assert_eq!(
            reassess_post(&conn, post, &settings).unwrap().state,
            PostState::Verified
        );

        // The same length, different content: only comparing the bytes finds it.
        let file_id: i64 = conn
            .query_row(
                "SELECT id FROM kemono_files WHERE post_id = ?1",
                params![post],
                |row| row.get(0),
            )
            .unwrap();
        std::fs::write(&delivered, vec![b'x'; payload.len()]).unwrap();
        assert_eq!(
            std::fs::metadata(&delivered).unwrap().len(),
            payload.len() as u64
        );
        let report = verify_post_files(&conn, post).unwrap();
        assert_eq!(report.mismatched, 1);
        let after = reassess_post(&conn, post, &settings).unwrap();
        assert_ne!(after.state, PostState::Verified, "{after:?}");
        assert_eq!(after.integrity_failed_assets, 1);
        assert!(
            !after.state.is_claimable(),
            "a local change is not a gap to refill silently"
        );
        let integrity: String = conn
            .query_row(
                "SELECT integrity FROM kemono_files WHERE id = ?1",
                params![file_id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(integrity, "mismatched");

        // A file that has gone is not the resource either, and it must not keep
        // the old proof standing.
        conn.execute(
            "UPDATE kemono_files SET integrity = '', local_hash = expected_blake3 WHERE id = ?1",
            params![file_id],
        )
        .unwrap();
        std::fs::remove_file(&delivered).unwrap();
        assert_eq!(verify_file_hash(&conn, file_id).unwrap(), Some(false));
        let gone = reassess_post(&conn, post, &settings).unwrap();
        assert_ne!(gone.state, PostState::Verified, "{gone:?}");
        assert!(!gone.state.is_claimable());
        let verdict: String = conn
            .query_row(
                "SELECT integrity FROM kemono_files WHERE id = ?1",
                params![file_id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(verdict, "missing");

        // A directory in the target's place is not a file either.
        std::fs::create_dir(&delivered).unwrap();
        assert_eq!(verify_file_hash(&conn, file_id).unwrap(), Some(false));
        let replaced: String = conn
            .query_row(
                "SELECT integrity FROM kemono_files WHERE id = ?1",
                params![file_id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(replaced, "unreadable");
    }

    /// A finished image set does not deliver the netdisk bundle beside it, and
    /// a delivered bundle does not fetch the images.
    #[test]
    fn direct_delivery_and_external_links_do_not_satisfy_each_other() {
        use tempfile::tempdir;

        let dir = tempdir().unwrap();
        let roots = MediaRoots::identical(
            vec![dir.path().to_string_lossy().to_string()],
            vec!["Media".to_string()],
        );
        let (conn, _, post) = evaluator_fixture();
        let settings = PawchiveSettings::default();
        insert_test_file(&conn, post, "/data/a.png", "a.png", "image", "done");
        set_evidence(&conn, post, "/data/a.png", "download");
        conn.execute(
            "UPDATE kemono_posts SET external_links = '[\"https://mega.nz/folder/x\"]' WHERE id = ?1",
            params![post],
        )
        .unwrap();

        // Images proven, bundle never delivered: the work is not complete.
        let images_only = reassess_post(&conn, post, &settings).unwrap();
        assert_ne!(images_only.state, PostState::Verified, "{images_only:?}");
        assert_eq!(images_only.state, PostState::External);
        assert!(images_only.external_pending);
        assert!(!images_only.state.is_settled());

        // The bundle arrives while an image is still missing: that is not
        // completion either.
        let bundle = dir.path().join("bundle.bin");
        std::fs::write(&bundle, b"bundle").unwrap();
        insert_test_file(&conn, post, "/data/b.png", "b.png", "image", "pending");
        let receipt = ExternalReceipt {
            post_id: post,
            manifest_version: 1,
            task_id: "task-mirror".to_string(),
            result: "completed".to_string(),
            output_paths: vec![bundle.to_string_lossy().to_string()],
            note: String::new(),
            bridge_id: "bridge-1".to_string(),
        };
        let bridge = ExternalBridge {
            bridge_id: "bridge-1".to_string(),
        };
        assert_eq!(
            record_external_receipt(&conn, &receipt, &roots, Some(&bridge)).unwrap(),
            ReceiptOutcome::Recorded
        );
        let bundle_only = reassess_post(&conn, post, &settings).unwrap();
        assert_ne!(bundle_only.state, PostState::Verified, "{bundle_only:?}");
        assert!(
            bundle_only.state.is_claimable(),
            "the missing image is a gap"
        );
        assert!(!bundle_only.external_pending);

        // Only when both sides are delivered does the work read as verified.
        set_evidence(&conn, post, "/data/b.png", "download");
        let both = reassess_post(&conn, post, &settings).unwrap();
        assert_eq!(both.state, PostState::Verified, "{both:?}");
        assert!(!both.external_pending);
    }

    /// Candidates come from the media index: the post's own folder first, then
    /// the same artist's files from the same days.
    #[test]
    fn candidates_come_from_the_library_index_not_a_directory_walk() {
        let conn = test_conn();
        conn.execute_batch(
            "DROP TABLE items;
             CREATE TABLE items (
                 id INTEGER PRIMARY KEY, artist_id INTEGER, file_path TEXT, file_name TEXT,
                 file_size INTEGER, content_hash TEXT, date TEXT, detected_date TEXT,
                 manual_date TEXT, missing INTEGER DEFAULT 0, folder_name TEXT DEFAULT ''
             );",
        )
        .unwrap();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures1/artist", None)
                .unwrap();
        conn.execute(
            "INSERT INTO artists (id, name, path) VALUES (1, 'artist', '/pictures1/artist')",
            [],
        )
        .unwrap();
        conn.execute(
            "UPDATE kemono_subscriptions SET artist_id = 1 WHERE id = ?1",
            params![sub_id],
        )
        .unwrap();
        let post = insert_test_post(&conn, sub_id, "900");
        conn.execute(
            "UPDATE kemono_posts SET published_at = '2026-09-14T00:00:00', title = 'A work'
             WHERE id = ?1",
            params![post],
        )
        .unwrap();
        // The folder rule is checked against the same prefix the code computes,
        // so the assertion does not depend on how the source's timezone is
        // converted: the same-day rule below is what tests the date window.
        let folder = post_folder_prefix(&conn, post).unwrap().rendered_prefix;
        conn.execute(
            "INSERT INTO items (id, artist_id, file_path, file_name, file_size, date, missing)
             VALUES (10, 1, ?1, '1.png', 10, '2026-09-14', 0)",
            params![format!("{folder}/1.png")],
        )
        .unwrap();
        conn.execute_batch(
            "INSERT INTO items (id, artist_id, file_path, file_name, file_size, date, missing)
             VALUES (11, 1, '/pictures1/artist/artist/2026-09-15 other/1.png', '1.png', 11, '2026-09-15', 0),
                    (12, 1, '/pictures1/artist/artist/2020-01-01 old/1.png', '1.png', 12, '2020-01-01', 0),
                    (13, 2, '/pictures1/other/2026-09-14 A work/1.png', '1.png', 13, '2026-09-14', 0);",
        )
        .unwrap();

        let candidates = list_post_candidates(&conn, post, None).unwrap();
        let ids: Vec<i64> = candidates.iter().map(|row| row.item_id).collect();
        // The post's own folder ranks first, the same-day neighbour follows, and
        // neither another artist's file nor a file from years away appears.
        assert_eq!(ids, vec![10, 11]);
        assert_eq!(candidates[0].reason, "folder");
        assert_eq!(candidates[1].reason, "same_day");
    }

    /// A receipt settles only the manifest it was made for, once, and only
    /// through a paired bridge that names files which actually exist.
    #[test]
    fn an_external_receipt_is_idempotent_and_version_bound() {
        use tempfile::tempdir;

        let dir = tempdir().unwrap();
        let roots = MediaRoots::identical(
            vec![dir.path().to_string_lossy().to_string()],
            vec!["Media".to_string()],
        );
        let (conn, _, post) = evaluator_fixture();
        conn.execute(
            "UPDATE kemono_posts SET external_links = '[\"https://mega.nz/folder/x\"]' WHERE id = ?1",
            params![post],
        )
        .unwrap();
        let settings = PawchiveSettings::default();
        assert_eq!(
            reassess_post(&conn, post, &settings).unwrap().state,
            PostState::External
        );

        // The delivered bundle has to be a real file: an uncreated path, an
        // empty file and a directory all describe no delivery.
        let out = dir.path().join("out.bin");
        std::fs::write(&out, b"delivered bundle").unwrap();
        let bridge = ExternalBridge {
            bridge_id: "bridge-1".to_string(),
        };
        let receipt = ExternalReceipt {
            post_id: post,
            manifest_version: 1,
            task_id: "jd-task-7".to_string(),
            result: "completed".to_string(),
            output_paths: vec![out.to_string_lossy().to_string()],
            note: String::new(),
            bridge_id: "bridge-1".to_string(),
        };
        assert_eq!(
            record_external_receipt(&conn, &receipt, &roots, Some(&bridge)).unwrap(),
            ReceiptOutcome::Recorded
        );
        assert_eq!(
            reassess_post(&conn, post, &settings).unwrap().state,
            PostState::NotRequired,
            "a completed receipt settles the external delivery"
        );

        // The same task reporting the same version again changes nothing.
        assert_eq!(
            record_external_receipt(&conn, &receipt, &roots, Some(&bridge)).unwrap(),
            ReceiptOutcome::Duplicate
        );

        // A receipt for an older manifest cannot settle a newer one.
        conn.execute(
            "UPDATE kemono_posts SET manifest_version = 2 WHERE id = ?1",
            params![post],
        )
        .unwrap();
        let stale = ExternalReceipt {
            task_id: "jd-task-8".to_string(),
            manifest_version: 1,
            ..receipt.clone()
        };
        assert_eq!(
            record_external_receipt(&conn, &stale, &roots, Some(&bridge)).unwrap(),
            ReceiptOutcome::Stale
        );
        assert_eq!(
            reassess_post(&conn, post, &settings).unwrap().state,
            PostState::External,
            "the newer manifest is not covered by the old receipt"
        );

        // A path outside the media roots is refused rather than recorded.
        let outside = ExternalReceipt {
            task_id: "jd-task-9".to_string(),
            manifest_version: 2,
            output_paths: vec!["/etc/passwd".to_string()],
            ..receipt.clone()
        };
        let err = record_external_receipt(&conn, &outside, &roots, Some(&bridge)).unwrap_err();
        assert!(
            err.to_string().contains("outside authorized media roots"),
            "{err}"
        );

        // A receipt with no task id cannot be matched or de-duplicated.
        let unnamed = ExternalReceipt {
            task_id: "  ".to_string(),
            manifest_version: 2,
            ..receipt
        };
        assert!(record_external_receipt(&conn, &unnamed, &roots, Some(&bridge)).is_err());
    }

    /// A settled external delivery is a fact about the work, not about the
    /// subscription that discovered it.
    ///
    /// The working receipt row is keyed on the post and cascades away with the
    /// subscription. If the proof lived only there, dropping a subscription and
    /// adding it back would lose the downloader's own report of a delivered
    /// bundle and the next round would ask for it again. The event is written
    /// onto the long-term ledger instead, keyed on the work identity and the
    /// resource version, so re-discovery resolves to the same version.
    #[test]
    fn a_settled_external_receipt_is_a_fetch_the_work_keeps() {
        use tempfile::tempdir;

        let dir = tempdir().unwrap();
        let roots = MediaRoots::identical(
            vec![dir.path().to_string_lossy().into_owned()],
            vec!["Media".to_string()],
        );
        let (conn, sub_id, post) = evaluator_fixture();
        conn.execute(
            "UPDATE kemono_posts SET external_links = '[\"https://mega.nz/folder/x\"]' WHERE id = ?1",
            params![post],
        )
        .unwrap();
        // The manifest has to exist on the long-term ledger before a delivery
        // can be recorded against one of its resource versions.
        let work_id = record_work_observation(&conn, post, ManifestCompleteness::Complete)
            .unwrap()
            .expect("the fixture post belongs to a subscription");

        let out = dir.path().join("bundle.bin");
        std::fs::write(&out, b"delivered bundle").unwrap();
        let bridge = ExternalBridge {
            bridge_id: "bridge-1".to_string(),
        };
        let receipt = ExternalReceipt {
            post_id: post,
            manifest_version: 1,
            task_id: "jd-task-7".to_string(),
            result: "completed".to_string(),
            output_paths: vec![out.to_string_lossy().into_owned()],
            note: String::new(),
            bridge_id: "bridge-1".to_string(),
        };
        assert_eq!(
            record_external_receipt(&conn, &receipt, &roots, Some(&bridge)).unwrap(),
            ReceiptOutcome::Recorded
        );

        let bundle_version = resource_version_id_for(
            &work_id,
            "external:https://mega.nz/folder/x",
            UNKNOWN_VERSION,
        );
        assert_eq!(
            scalar(
                &conn,
                &format!(
                    "SELECT COUNT(*) FROM pawchive_acquisition_events
                     WHERE resource_version_id = '{bundle_version}'
                       AND evidence_source = 'external_receipt'
                       AND evidence_strength = 'strong'"
                )
            ),
            1,
            "the settled receipt proves the external bundle was fetched"
        );
        // The pre-fix behaviour, asserted as the wrong answer: the work's only
        // record of the delivery sat in the working receipt row.
        assert_eq!(
            scalar(
                &conn,
                "SELECT COUNT(*) FROM pawchive_acquisition_events
                 WHERE work_id = (SELECT work_id FROM pawchive_remote_works LIMIT 1)"
            ),
            1
        );

        // The subscription goes away; the working rows it owned cascade with it.
        assert!(delete_subscription(&conn, sub_id).unwrap());
        assert_eq!(scalar(&conn, "SELECT COUNT(*) FROM kemono_posts"), 0);
        assert_eq!(
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_external_receipts"),
            1,
            "the external receipt row is preserved across subscription deletion"
        );

        let view = assess_work_from_ledger(&conn, &work_id)
            .unwrap()
            .expect("the work outlives the subscription that discovered it");
        assert_eq!(
            view.acquired_resource_versions,
            vec![bundle_version.clone()],
            "the settled external delivery is still a fetch"
        );

        // Re-adding the subscription re-discovers the same work and the same
        // bundle version, so the next round reads the delivery as already
        // fetched instead of asking for the netdisk bundle again.
        let again =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures1/artist", None)
                .unwrap();
        let repost = insert_test_post(&conn, again, "900");
        conn.execute(
            "UPDATE kemono_posts SET external_links = '[\"https://mega.nz/folder/x\"]' WHERE id = ?1",
            params![repost],
        )
        .unwrap();
        let rebound = record_work_observation(&conn, repost, ManifestCompleteness::Complete)
            .unwrap()
            .expect("the re-discovered post resolves to the same work identity");
        assert_eq!(
            rebound, work_id,
            "identity is the source quadruple, not the row"
        );
        let after = assess_work_from_ledger(&conn, &work_id).unwrap().unwrap();
        assert_eq!(
            after.acquired_resource_versions,
            vec![bundle_version],
            "re-discovery does not orphan the fetch or invent a second version"
        );
        assert!(after.requires_fetch.is_empty(), "{after:?}");
    }

    /// A receipt that settled nothing leaves no fetch behind, not even for the
    /// work it named: the refusal is the point of the check.
    #[test]
    fn a_refused_receipt_does_not_prove_a_fetch() {
        use tempfile::tempdir;

        let dir = tempdir().unwrap();
        let roots = MediaRoots::identical(
            vec![dir.path().to_string_lossy().into_owned()],
            vec!["Media".to_string()],
        );
        let (conn, _, post) = evaluator_fixture();
        conn.execute(
            "UPDATE kemono_posts SET external_links = '[\"https://mega.nz/folder/x\"]' WHERE id = ?1",
            params![post],
        )
        .unwrap();
        let work_id = record_work_observation(&conn, post, ManifestCompleteness::Complete)
            .unwrap()
            .unwrap();

        // No bridge is paired, and the named output does not exist.
        let unpaired = ExternalReceipt {
            post_id: post,
            manifest_version: 1,
            task_id: "jd-task-refused".to_string(),
            result: "completed".to_string(),
            output_paths: vec![dir.path().join("never.bin").to_string_lossy().into_owned()],
            note: String::new(),
            bridge_id: "bridge-1".to_string(),
        };
        assert!(matches!(
            record_external_receipt(&conn, &unpaired, &roots, None).unwrap(),
            ReceiptOutcome::Rejected(_)
        ));
        assert_eq!(
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_acquisition_events"),
            0,
            "a refused report settles nothing and proves nothing"
        );
        let view = assess_work_from_ledger(&conn, &work_id).unwrap().unwrap();
        assert!(view.acquired_resource_versions.is_empty(), "{view:?}");
        assert!(!view.requires_fetch.is_empty(), "the bundle is still owed");
    }

    /// An empty or unverifiable `completed` receipt settles nothing, and neither
    /// does a receipt from a bridge this install never paired.
    #[test]
    fn an_unverifiable_receipt_settles_nothing() {
        use tempfile::tempdir;

        let dir = tempdir().unwrap();
        let roots = MediaRoots::identical(
            vec![dir.path().to_string_lossy().to_string()],
            vec!["Media".to_string()],
        );
        let (conn, _, post) = evaluator_fixture();
        conn.execute(
            "UPDATE kemono_posts SET external_links = '[\"https://mega.nz/folder/x\"]' WHERE id = ?1",
            params![post],
        )
        .unwrap();
        let settings = PawchiveSettings::default();
        let bridge = ExternalBridge {
            bridge_id: "bridge-1".to_string(),
        };
        let base = ExternalReceipt {
            post_id: post,
            manifest_version: 1,
            task_id: "jd-task-empty".to_string(),
            result: "completed".to_string(),
            output_paths: Vec::new(),
            note: String::new(),
            bridge_id: "bridge-1".to_string(),
        };

        // An empty output list is not a delivery.
        let outcome = record_external_receipt(&conn, &base, &roots, Some(&bridge)).unwrap();
        assert!(
            matches!(outcome, ReceiptOutcome::Rejected(_)),
            "{outcome:?}"
        );
        assert_eq!(
            reassess_post(&conn, post, &settings).unwrap().state,
            PostState::External
        );

        // Neither is a path that does not exist, a directory, an empty file, or
        // a symlink to one that does.
        let missing = ExternalReceipt {
            task_id: "jd-task-missing".to_string(),
            output_paths: vec![dir.path().join("nope.bin").to_string_lossy().to_string()],
            ..base.clone()
        };
        assert!(matches!(
            record_external_receipt(&conn, &missing, &roots, Some(&bridge)).unwrap(),
            ReceiptOutcome::Rejected(_)
        ));
        let directory = ExternalReceipt {
            task_id: "jd-task-dir".to_string(),
            output_paths: vec![dir.path().to_string_lossy().to_string()],
            ..base.clone()
        };
        assert!(matches!(
            record_external_receipt(&conn, &directory, &roots, Some(&bridge)).unwrap(),
            ReceiptOutcome::Rejected(_)
        ));
        let empty = dir.path().join("empty.bin");
        std::fs::write(&empty, b"").unwrap();
        let zero_length = ExternalReceipt {
            task_id: "jd-task-zero".to_string(),
            output_paths: vec![empty.to_string_lossy().to_string()],
            ..base.clone()
        };
        assert!(matches!(
            record_external_receipt(&conn, &zero_length, &roots, Some(&bridge)).unwrap(),
            ReceiptOutcome::Rejected(_)
        ));
        let real = dir.path().join("real.bin");
        std::fs::write(&real, b"content").unwrap();
        let link = dir.path().join("link.bin");
        #[cfg(unix)]
        std::os::unix::fs::symlink(&real, &link).unwrap();
        #[cfg(not(unix))]
        std::fs::copy(&real, &link).unwrap();
        if std::fs::symlink_metadata(&link)
            .map(|meta| meta.file_type().is_symlink())
            .unwrap_or(false)
        {
            let symlinked = ExternalReceipt {
                task_id: "jd-task-link".to_string(),
                output_paths: vec![link.to_string_lossy().to_string()],
                ..base.clone()
            };
            assert!(matches!(
                record_external_receipt(&conn, &symlinked, &roots, Some(&bridge)).unwrap(),
                ReceiptOutcome::Rejected(_)
            ));
        }

        // With no paired bridge, even a perfect report is history only.
        let verified = ExternalReceipt {
            task_id: "jd-task-nobridge".to_string(),
            output_paths: vec![real.to_string_lossy().to_string()],
            ..base.clone()
        };
        assert!(matches!(
            record_external_receipt(&conn, &verified, &roots, None).unwrap(),
            ReceiptOutcome::Rejected(_)
        ));
        assert_eq!(
            reassess_post(&conn, post, &settings).unwrap().state,
            PostState::External,
            "nothing settled the post"
        );

        // The same report through a paired bridge settles it, so the refusal is
        // about the missing identity and not about the payload.
        assert_eq!(
            record_external_receipt(&conn, &verified, &roots, Some(&bridge)).unwrap(),
            ReceiptOutcome::Recorded
        );
        assert_eq!(
            reassess_post(&conn, post, &settings).unwrap().state,
            PostState::NotRequired
        );
    }

    /// A stale receipt is stored under its own version, so the valid receipt
    /// that arrives later still settles; and a failure followed by a completion
    /// for the same attempt is an upgrade, not a duplicate.
    #[test]
    fn a_stale_receipt_does_not_take_the_current_version_key() {
        use tempfile::tempdir;

        let dir = tempdir().unwrap();
        let roots = MediaRoots::identical(
            vec![dir.path().to_string_lossy().to_string()],
            vec!["Media".to_string()],
        );
        let (conn, _, post) = evaluator_fixture();
        conn.execute(
            "UPDATE kemono_posts SET external_links = '[\"https://mega.nz/folder/x\"]', manifest_version = 2
             WHERE id = ?1",
            params![post],
        )
        .unwrap();
        let settings = PawchiveSettings::default();
        let bridge = ExternalBridge {
            bridge_id: "bridge-1".to_string(),
        };
        let out = dir.path().join("bundle.bin");
        std::fs::write(&out, b"bundle").unwrap();
        let paths = vec![out.to_string_lossy().to_string()];

        let stale = ExternalReceipt {
            post_id: post,
            manifest_version: 1,
            task_id: "task-a".to_string(),
            result: "completed".to_string(),
            output_paths: paths.clone(),
            note: String::new(),
            bridge_id: "bridge-1".to_string(),
        };
        assert_eq!(
            record_external_receipt(&conn, &stale, &roots, Some(&bridge)).unwrap(),
            ReceiptOutcome::Stale
        );
        let took_current: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM pawchive_external_receipts
                 WHERE post_id = ?1 AND manifest_version = 2",
                params![post],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(took_current, 0, "the old report must not occupy v2");
        assert_eq!(
            reassess_post(&conn, post, &settings).unwrap().state,
            PostState::External
        );

        // The current version's own receipt still settles.
        let current = ExternalReceipt {
            manifest_version: 2,
            task_id: "task-b".to_string(),
            ..stale.clone()
        };
        assert_eq!(
            record_external_receipt(&conn, &current, &roots, Some(&bridge)).unwrap(),
            ReceiptOutcome::Recorded
        );
        assert_eq!(
            reassess_post(&conn, post, &settings).unwrap().state,
            PostState::NotRequired
        );

        // A failure for a fresh attempt is recorded, and its completion is an
        // upgrade rather than a de-duplicated no-op.
        conn.execute(
            "UPDATE kemono_posts SET manifest_version = 3 WHERE id = ?1",
            params![post],
        )
        .unwrap();
        let failed = ExternalReceipt {
            manifest_version: 3,
            task_id: "task-c".to_string(),
            result: "failed".to_string(),
            output_paths: Vec::new(),
            ..current.clone()
        };
        assert_eq!(
            record_external_receipt(&conn, &failed, &roots, Some(&bridge)).unwrap(),
            ReceiptOutcome::Recorded
        );
        assert_eq!(
            reassess_post(&conn, post, &settings).unwrap().state,
            PostState::External,
            "a failed job settles nothing"
        );
        let completed = ExternalReceipt {
            result: "completed".to_string(),
            output_paths: paths,
            ..failed.clone()
        };
        assert_eq!(
            record_external_receipt(&conn, &completed, &roots, Some(&bridge)).unwrap(),
            ReceiptOutcome::Recorded
        );
        assert_eq!(
            reassess_post(&conn, post, &settings).unwrap().state,
            PostState::NotRequired,
            "the completion of the same attempt settles it"
        );

        // A failure reported after the completion never downgrades it.
        assert_eq!(
            record_external_receipt(&conn, &failed, &roots, Some(&bridge)).unwrap(),
            ReceiptOutcome::Duplicate
        );
        assert_eq!(
            reassess_post(&conn, post, &settings).unwrap().state,
            PostState::NotRequired
        );
    }

    /// A delivered file is linked to its library item, and follows the item when
    /// the user moves it.
    #[test]
    fn evidence_links_to_its_library_item_and_follows_a_move() {
        let conn = test_conn();
        conn.execute_batch(
            "DROP TABLE items;
             CREATE TABLE items (
                 id INTEGER PRIMARY KEY, file_path TEXT UNIQUE, missing INTEGER DEFAULT 0
             );",
        )
        .unwrap();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures1/artist", None)
                .unwrap();
        let post_id = insert_test_post(&conn, sub_id, "777");
        insert_test_file(&conn, post_id, "/data/a.png", "a.png", "image", "done");
        conn.execute(
            "UPDATE kemono_files SET delivery_source = 'download', target_path = '/pictures1/artist/a.png'
             WHERE post_id = ?1",
            params![post_id],
        )
        .unwrap();
        conn.execute(
            "INSERT INTO items (id, file_path, missing) VALUES (5, '/pictures1/artist/a.png', 0)",
            [],
        )
        .unwrap();

        assert!(link_evidence_to_items(&conn).unwrap() >= 1);
        let linked: Option<i64> = conn
            .query_row(
                "SELECT evidence_item_id FROM kemono_files WHERE post_id = ?1",
                params![post_id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(linked, Some(5));

        // The library moves the file; the identity survives, so the evidence
        // follows the item instead of reading as a file that vanished.
        conn.execute(
            "UPDATE items SET file_path = '/pictures1/artist/moved/a.png' WHERE id = 5",
            [],
        )
        .unwrap();
        link_evidence_to_items(&conn).unwrap();
        let followed: String = conn
            .query_row(
                "SELECT target_path FROM kemono_files WHERE post_id = ?1",
                params![post_id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(followed, "/pictures1/artist/moved/a.png");
    }

    /// The scan turning a published artifact into a library row is the ingest
    /// handoff: the publish ledger records the item and stops reporting the job
    /// as merely published. Without it the ledger could not tell a file that is
    /// on the share from one the library actually indexed.
    #[test]
    fn a_published_job_is_marked_ingested_when_the_scan_creates_its_item() {
        let conn = test_conn();
        conn.execute_batch(
            "DROP TABLE items;
             CREATE TABLE items (
                 id INTEGER PRIMARY KEY, file_path TEXT UNIQUE, missing INTEGER DEFAULT 0,
                 file_size INTEGER DEFAULT 4, content_hash TEXT DEFAULT ''
             );",
        )
        .unwrap();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures1/artist", None)
                .unwrap();
        let post_id = insert_test_post(&conn, sub_id, "778");
        insert_test_file(&conn, post_id, "/data/b.png", "b.png", "image", "done");
        let file_id: i64 = conn
            .query_row(
                "SELECT id FROM kemono_files WHERE post_id = ?1",
                params![post_id],
                |row| row.get(0),
            )
            .unwrap();
        conn.execute(
            "INSERT INTO download_publish_jobs
                 (engine, source_job_id, manifest_version, source_identity, expected_length,
                  expected_blake3, target_path, private_temp_path, stage, created_at, updated_at)
             VALUES ('pawchive', ?1, 1, '/data/b.png', 4, 'hash', '/pictures1/artist/b.png',
                     '', 'published', 't', 't')",
            params![format!("{post_id}:{file_id}")],
        )
        .unwrap();
        let job_id: i64 = conn
            .query_row("SELECT MAX(id) FROM download_publish_jobs", [], |row| {
                row.get(0)
            })
            .unwrap();
        conn.execute(
            "UPDATE kemono_files
             SET delivery_source = 'download', target_path = '/pictures1/artist/b.png',
                 publish_job_id = ?1
             WHERE id = ?2",
            params![job_id, file_id],
        )
        .unwrap();

        // The scan has not created the row yet: the job stays published.
        link_evidence_to_items(&conn).unwrap();
        let stage: String = conn
            .query_row(
                "SELECT stage FROM download_publish_jobs WHERE id = ?1",
                params![job_id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(stage, "published");

        // The scan creates the row; the next handoff records it.
        conn.execute(
            "INSERT INTO items (id, file_path, missing) VALUES (9, '/pictures1/artist/b.png', 0)",
            [],
        )
        .unwrap();
        let digest = blake3::hash(b"data").to_hex().to_string();
        conn.execute("UPDATE items SET content_hash = ?1", params![digest])
            .unwrap();
        conn.execute(
            "UPDATE download_publish_jobs SET expected_blake3 = ?1",
            params![digest],
        )
        .unwrap();

        link_evidence_to_items(&conn).unwrap();
        let (stage, item): (String, Option<i64>) = conn
            .query_row(
                "SELECT stage, item_id FROM download_publish_jobs WHERE id = ?1",
                params![job_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(
            stage, "ingested",
            "the publish ledger learns the artifact is now indexed"
        );
        assert_eq!(item, Some(9));

        // A second handoff is a no-op, not an error.
        link_evidence_to_items(&conn).unwrap();
        let stage: String = conn
            .query_row(
                "SELECT stage FROM download_publish_jobs WHERE id = ?1",
                params![job_id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(stage, "ingested");
    }

    #[test]
    fn link_evidence_to_items_follows_move_history_for_unlinked_delivery() {
        let conn = test_conn();
        conn.execute_batch(
            "DROP TABLE items;
             CREATE TABLE items (
                 id INTEGER PRIMARY KEY, artist_id INTEGER, file_path TEXT UNIQUE, file_name TEXT, missing INTEGER DEFAULT 0,
                 file_size INTEGER DEFAULT 8, content_hash TEXT DEFAULT ''
             );
             CREATE TABLE IF NOT EXISTS move_history (
                 id INTEGER PRIMARY KEY, item_id INTEGER, artist_id INTEGER, old_path TEXT, new_path TEXT, reason TEXT, status TEXT, applied_at REAL
             );",
        )
        .unwrap();

        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures1/artist", None)
                .unwrap();
        let post_id = insert_test_post(&conn, sub_id, "888");
        insert_test_file(&conn, post_id, "/data/c.png", "c.png", "image", "done");
        let file_id: i64 = conn
            .query_row(
                "SELECT id FROM kemono_files WHERE post_id = ?1",
                params![post_id],
                |row| row.get(0),
            )
            .unwrap();

        conn.execute(
            "INSERT INTO download_publish_jobs
                 (engine, source_job_id, manifest_version, source_identity, expected_length,
                  expected_blake3, target_path, private_temp_path, stage, created_at, updated_at)
             VALUES ('pawchive', ?1, 1, '/data/c.png', 8, 'hash', '/pictures1/artist/old_name.png',
                     '', 'published', 't', 't')",
            params![format!("{post_id}:{file_id}")],
        )
        .unwrap();
        let job_id: i64 = conn
            .query_row("SELECT MAX(id) FROM download_publish_jobs", [], |row| {
                row.get(0)
            })
            .unwrap();

        conn.execute(
            "UPDATE kemono_files SET delivery_source = 'download', target_path = '/pictures1/artist/old_name.png', publish_job_id = ?1 WHERE id = ?2",
            params![job_id, file_id],
        )
        .unwrap();

        // The item was indexed and then moved to a new subfolder before link_evidence_to_items ran.
        conn.execute(
            "INSERT INTO items (id, artist_id, file_path, file_name, missing)
             VALUES (42, 1, '/pictures1/artist/2026-09-14/c.png', 'c.png', 0)",
            [],
        )
        .unwrap();
        conn.execute(
            "INSERT INTO move_history
                 (item_id, artist_id, old_path, new_path, reason, status, applied_at)
             VALUES (42, 1, '/pictures1/artist/old_name.png', '/pictures1/artist/2026-09-14/c.png', 'organize', 'applied', strftime('%s','now'))",
            [],
        )
        .unwrap();

        let digest = blake3::hash(b"contents").to_hex().to_string();
        conn.execute("UPDATE items SET content_hash = ?1", params![digest])
            .unwrap();
        conn.execute(
            "UPDATE download_publish_jobs SET expected_blake3 = ?1",
            params![digest],
        )
        .unwrap();

        // Reconcile runs: it should follow move_history to link item 42 and update target_path.
        let changed = link_evidence_to_items(&conn).unwrap();
        assert!(
            changed >= 2,
            "must link moved delivery and transition publish job"
        );

        let (target_path, evidence_item_id): (String, Option<i64>) = conn
            .query_row(
                "SELECT target_path, evidence_item_id FROM kemono_files WHERE id = ?1",
                params![file_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(target_path, "/pictures1/artist/2026-09-14/c.png");
        assert_eq!(evidence_item_id, Some(42));

        let (stage, item_id): (String, Option<i64>) = conn
            .query_row(
                "SELECT stage, item_id FROM download_publish_jobs WHERE id = ?1",
                params![job_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(stage, "ingested");
        assert_eq!(item_id, Some(42));
    }

    #[test]
    fn link_evidence_does_not_bind_new_occupant_at_reused_path() {
        let conn = Connection::open_in_memory().unwrap();
        conn.execute_batch(
            "CREATE TABLE kemono_files (
                 id INTEGER PRIMARY KEY, evidence_item_id INTEGER, target_path TEXT, updated_at TEXT
             );
             CREATE TABLE items (
                 id INTEGER PRIMARY KEY, file_path TEXT, missing INTEGER DEFAULT 0
             );
             CREATE TABLE move_history (
                 id INTEGER PRIMARY KEY, item_id INTEGER, old_path TEXT, new_path TEXT, status TEXT
             );
             INSERT INTO kemono_files VALUES (1, NULL, '/media/old.png', 't');
             INSERT INTO items VALUES (42, '/media/moved.png', 0), (99, '/media/old.png', 0);
             INSERT INTO move_history VALUES (1, 42, '/media/old.png', '/media/moved.png', 'applied');",
        )
        .unwrap();

        let changed = link_evidence_to_items(&conn).unwrap();
        assert_eq!(changed, 1);

        let (evidence_id, target_path): (Option<i64>, String) = conn
            .query_row(
                "SELECT evidence_item_id, target_path FROM kemono_files WHERE id = 1",
                [],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(
            evidence_id,
            Some(42),
            "must link moved item 42, NOT new occupant 99"
        );
        assert_eq!(target_path, "/media/moved.png");
    }

