    #[test]
    fn published_evidence_requires_a_ready_matching_digest_at_both_candidate_paths() {
        for moved in [false, true] {
            let conn = Connection::open_in_memory().unwrap();
            conn.execute_batch(
                "CREATE TABLE kemono_files (
                    id INTEGER PRIMARY KEY, evidence_item_id INTEGER, target_path TEXT,
                    expected_length INTEGER, publish_job_id INTEGER, updated_at TEXT);
                 CREATE TABLE items (
                    id INTEGER PRIMARY KEY, file_path TEXT, file_size INTEGER,
                    content_hash TEXT, hash_status TEXT, missing INTEGER);
                 CREATE TABLE download_publish_jobs (
                    id INTEGER PRIMARY KEY, expected_length INTEGER, expected_blake3 TEXT,
                    created_at REAL, stage TEXT, item_id INTEGER, updated_at TEXT);
                 CREATE TABLE move_history (
                    id INTEGER PRIMARY KEY, item_id INTEGER, old_path TEXT,
                    status TEXT, created_at REAL);
                 INSERT INTO kemono_files VALUES (1, NULL, '/media/file.png', NULL, 1, 't');
                 INSERT INTO items VALUES (10, '/media/file.png', 4, '', 'done', 0);
                 INSERT INTO download_publish_jobs VALUES (1, 4, '', 1000, 'published', NULL, 't');",
            ).unwrap();
            if moved {
                conn.execute_batch(
                    "UPDATE items SET file_path = '/media/moved.png';
                     INSERT INTO move_history VALUES (1, 10, '/media/file.png', 'applied', 1001);",
                )
                .unwrap();
            }
            let expected = blake3::hash(b"good").to_hex().to_string();
            let other = blake3::hash(b"evil").to_hex().to_string();
            conn.execute(
                "UPDATE download_publish_jobs SET expected_blake3 = ?1",
                params![expected],
            )
            .unwrap();
            for (digest, status) in [
                ("", "done"),
                (other.as_str(), "done"),
                (expected.as_str(), "pending"),
            ] {
                conn.execute(
                    "UPDATE items SET content_hash = ?1, hash_status = ?2",
                    params![digest, status],
                )
                .unwrap();
                assert_eq!(
                    link_evidence_to_items(&conn).unwrap(),
                    0,
                    "moved={moved}, status={status}"
                );
                let stage: String = conn
                    .query_row("SELECT stage FROM download_publish_jobs", [], |row| {
                        row.get(0)
                    })
                    .unwrap();
                assert_eq!(stage, "published");
            }
            conn.execute("UPDATE items SET hash_status = 'done'", [])
                .unwrap();
            assert_eq!(link_evidence_to_items(&conn).unwrap(), 2);
            let item: Option<i64> = conn
                .query_row("SELECT evidence_item_id FROM kemono_files", [], |row| {
                    row.get(0)
                })
                .unwrap();
            assert_eq!(item, Some(10));
            assert_eq!(link_evidence_to_items(&conn).unwrap(), 0);
        }
    }

