    /// The resource identity is the source's own attachment id when it
    /// publishes one, and the served path only as the fallback.
    ///
    /// The plan makes the distinction load-bearing: a path is a location that
    /// can hold different bytes after a replacement, while an attachment id
    /// names the resource itself. Which one a row used is stored next to it, so
    /// a later reader never has to guess.
    #[test]
    fn the_resource_identity_is_the_attachment_id_when_the_source_publishes_one() {
        use crate::pawchive::{normalize_remote_path, PawchiveFileRef};

        // Published id: it wins over the path.
        let with_id = PawchiveFileRef {
            id: Some("att-77".to_string()),
            name: Some("art.png".to_string()),
            path: Some("ab/cd/art.png".to_string()),
        };
        assert_eq!(
            with_id.resource_identity(),
            ("att-77".to_string(), "source_id")
        );

        // No id, or only whitespace: the path stands in, and the basis says so.
        let without_id = PawchiveFileRef {
            id: None,
            name: Some("art.png".to_string()),
            path: Some("ab/cd/art.png".to_string()),
        };
        assert_eq!(
            without_id.resource_identity(),
            ("ab/cd/art.png".to_string(), "path")
        );
        let blank_id = PawchiveFileRef {
            id: Some("   ".to_string()),
            ..with_id.clone()
        };
        assert_eq!(
            blank_id.resource_identity(),
            ("ab/cd/art.png".to_string(), "path"),
            "an empty id is not an identity"
        );

        // The served decoration names how the file is delivered, not which file
        // it is: two reads that differ only there are the same resource.
        assert_eq!(normalize_remote_path("/data/a.png?f=a.png"), "/data/a.png");
        assert_eq!(normalize_remote_path("/data/a.png#page=1"), "/data/a.png");
        assert_eq!(
            normalize_remote_path("  /data/a.png?f=a.png#x  "),
            "/data/a.png"
        );
        // A real path segment is never rewritten.
        assert_eq!(
            normalize_remote_path("/data/ab/cd/a.png"),
            "/data/ab/cd/a.png"
        );

        // The ledger stores which basis a row used.
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures/artist", None)
                .unwrap();
        let post = insert_test_post(&conn, sub_id, "900");
        let discovered = PawchivePost {
            id: "900".to_string(),
            user: "27212726".to_string(),
            service: "fanbox".to_string(),
            title: None,
            content: None,
            published: None,
            added: None,
            edited: None,
            file: None,
            attachments: vec![
                PawchiveFileRef {
                    id: Some("att-1".to_string()),
                    name: Some("one.png".to_string()),
                    path: Some("/data/one.png".to_string()),
                },
                PawchiveFileRef {
                    id: None,
                    name: Some("two.png".to_string()),
                    path: Some("/data/two.png?f=two.png".to_string()),
                },
            ],
            attachments_present: true,
            file_present: true,
            content_present: true,
            has_full: Some(true),
        };
        record_discovered_posts(&conn, sub_id, &[discovered], None).unwrap();
        let rows: Vec<(String, String, String)> = conn
            .prepare(
                "SELECT source_identity, remote_path, identity_basis FROM kemono_files
                 WHERE post_id = ?1 ORDER BY source_identity",
            )
            .unwrap()
            .query_map(params![post], |row| {
                Ok((row.get(0)?, row.get(1)?, row.get(2)?))
            })
            .unwrap()
            .collect::<rusqlite::Result<Vec<_>>>()
            .unwrap();
        assert_eq!(
            rows,
            vec![
                (
                    "/data/two.png".to_string(),
                    "/data/two.png".to_string(),
                    "path".to_string()
                ),
                (
                    "att-1".to_string(),
                    "/data/one.png".to_string(),
                    "source_id".to_string()
                ),
            ],
            "the published id keys the first resource; the second is keyed by \
             its normalized path and says so"
        );
    }

    #[test]
    fn reseen_posts_are_counted_as_new_only_once() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures1/artist", None)
                .unwrap();
        let post = PawchivePost {
            id: "1001".to_string(),
            user: "27212726".to_string(),
            service: "fanbox".to_string(),
            title: Some("Test Post".to_string()),
            content: None,
            published: Some("2026-02-01T12:00:00".to_string()),
            added: None,
            edited: None,
            file: None,
            attachments: Vec::new(),
            attachments_present: true,
            file_present: true,
            content_present: true,
            has_full: None,
        };
        let posts = std::slice::from_ref(&post);

        assert_eq!(
            record_discovered_posts(&conn, sub_id, posts, None).unwrap(),
            1
        );
        // The next round re-reads the same post to refresh it. An UPSERT reports
        // one changed row either way, so the count must not call it new again.
        assert_eq!(
            record_discovered_posts(&conn, sub_id, posts, None).unwrap(),
            0
        );
    }

    #[test]
    fn post_file_list_stays_in_creation_order_with_statuses() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures1/artist", None)
                .unwrap();
        let post_db_id = insert_test_post(&conn, sub_id, "77");
        insert_test_file(&conn, post_db_id, "0", "a.png", "image", "done");
        insert_test_file(&conn, post_db_id, "1", "b.png", "image", "failed");
        insert_test_file(&conn, post_db_id, "2", "c.png", "image", "downloading");

        let rows = list_post_files(&conn, post_db_id).unwrap();
        // Settled rows are returned too, so the index a retry uses is the row's
        // real position in the post: b.png keeps index 1 even though a.png is no
        // longer attempted. A status-filtered list would renumber it onto
        // "date 0.png", which already exists, and the retry could never win.
        assert_eq!(
            rows.iter()
                .map(|row| row.file_name.as_str())
                .collect::<Vec<_>>(),
            vec!["a.png", "b.png", "c.png"]
        );
        assert_eq!(rows[0].status, "done");
        assert_eq!(rows[1].status, "failed");
        assert_eq!(rows[2].status, "downloading");
    }

    #[test]
    fn unfinished_count_ignores_types_the_settings_exclude() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures1/artist", None)
                .unwrap();
        let post_db_id = insert_test_post(&conn, sub_id, "88");
        insert_test_file(&conn, post_db_id, "0", "a.png", "image", "pending");
        insert_test_file(&conn, post_db_id, "1", "b.mp4", "video", "pending");

        let images_only = PawchiveSettings {
            download_images: true,
            download_videos: false,
            download_archives: false,
            ..PawchiveSettings::default()
        };
        // The excluded video must not keep the post pending: otherwise it would
        // be re-selected every round and starve the ten-slot download queue.
        assert_eq!(
            count_unfinished_files(&conn, post_db_id, &images_only).unwrap(),
            1
        );

        let everything = PawchiveSettings {
            download_images: true,
            download_videos: true,
            download_archives: true,
            ..PawchiveSettings::default()
        };
        assert_eq!(
            count_unfinished_files(&conn, post_db_id, &everything).unwrap(),
            2
        );

        conn.execute(
            "UPDATE kemono_files SET status = 'done' WHERE file_name = 'a.png'",
            [],
        )
        .unwrap();
        assert_eq!(
            count_unfinished_files(&conn, post_db_id, &images_only).unwrap(),
            0
        );
    }

    #[test]
    fn custom_naming_templates_render_identity_tokens() {
        let naming = PostNamingContext::new(
            "Alice Artist",
            Some("2026-09-14T01:50:25"),
            Some("Summer Set"),
            "12595692",
            Some("patreon"),
        )
        .with_identity("27212726", "patreon");

        assert_eq!(
            naming.format_folder_path_with_template("{user}/{date} {title}/"),
            "Alice Artist/2026-09-14 Summer Set"
        );
        // {userID}/{user_id} are the creator id, never the post id.
        assert_eq!(
            naming.format_folder_path_with_template("{service}/{userID}/{date}"),
            "patreon/27212726/2026-09-14"
        );
        assert_eq!(
            naming.format_folder_path_with_template("{userID}_{id}"),
            "27212726_12595692"
        );
        assert_eq!(
            naming.format_folder_path_with_template("{site}/{user_id}"),
            "pawchive/27212726"
        );
        // An empty template falls back to the built-in default path.
        assert_eq!(
            naming.format_folder_path_with_template("   "),
            naming.format_folder_path()
        );

        assert_eq!(
            naming.format_image_filename_with_template(2, ".png", "{date} {index}.{ext}"),
            "2026-09-14 2.png"
        );
        assert_eq!(
            naming.format_image_filename_with_template(0, "jpg", "{id}_{userID}.{ext}"),
            "12595692_27212726.jpg"
        );
        // An extension already written by the template is not duplicated.
        assert_eq!(
            naming.format_image_filename_with_template(1, "png", "{index}.png"),
            "1.png"
        );

        assert_eq!(
            naming.format_attachment_filename_with_template("bonus_pack.zip", "{date} {name}"),
            "2026-09-14 bonus_pack.zip"
        );
        assert_eq!(
            naming.format_attachment_filename_with_template(
                "bonus_pack.zip",
                "{service}_{userID}_{name}"
            ),
            "patreon_27212726_bonus_pack.zip"
        );

        // Without an identity the creator tokens still render something stable
        // rather than leaving empty path segments.
        let anonymous =
            PostNamingContext::new("Bob", Some("2026-09-14T01:50:25"), Some("Set"), "42", None);
        assert_eq!(
            anonymous.format_folder_path_with_template("{service}/{userID}"),
            "pawchive/Bob"
        );
    }

    #[test]
    fn custom_naming_templates_sanitize_literals_and_do_not_reexpand_source_tokens() {
        let ctx = PostNamingContext::new(
            "Artist {id}",
            Some("2026-07-23T09:00:00Z"),
            Some("Set {date}"),
            "remote",
            Some("patreon"),
        )
        .with_identity("123", "patreon");
        for (template, expected) in [
            ("{user}/{title}", "Artist {id}/Set {date}"),
            ("{year}/{month}/{creator_id}", "2026/07/123"),
            ("../{id}/./child:bad?", "remote/child_bad_"),
            ("/{user}//固定目录/", "Artist {id}/固定目录"),
            ("C:\\outside/{id}", "C__outside/remote"),
            ("CON/NUL.txt", "_CON/_NUL.txt"),
            ("{unknown}/{broken", "{unknown}/{broken"),
        ] {
            assert_eq!(
                ctx.format_folder_path_with_template(template),
                expected,
                "{template}"
            );
        }
        assert_eq!(
            ctx.format_image_filename_with_name(2, "PNG", "photo.PNG", "{name}"),
            "photo.PNG"
        );
        assert_eq!(
            ctx.format_image_filename_with_template(2, "png", "../{index}:bad?"),
            "_2_bad_.png"
        );
        assert_eq!(
            ctx.format_image_filename_with_template(2, "png", ".."),
            "2026-07-23 2.png"
        );
        assert_eq!(
            ctx.format_attachment_filename_with_index("pack.rar", 3, "{index}.{ext}"),
            "3.rar"
        );
        assert_eq!(
            ctx.format_attachment_filename_with_template("pack.rar", "固定名称"),
            "固定名称.rar"
        );
        assert_eq!(
            ctx.format_attachment_filename_with_template("pack.rar", "../{name}"),
            "_pack.rar"
        );
        assert_eq!(
            ctx.format_attachment_filename_with_template("pack.rar", ".."),
            "pack.rar"
        );
    }

    #[test]
    fn custom_naming_templates_bound_complete_names_and_collision_suffixes() {
        let title = "画".repeat(100);
        let ctx = PostNamingContext::new("Artist", Some("2026-07-23"), Some(&title), "1", None);
        let folder = ctx.format_folder_path_with_template("{date} {title}/{title}{title}");
        for part in folder.split('/') {
            assert!(part.len() <= MAX_RENDERED_NAME_BYTES);
        }
        let image = ctx.format_image_filename_with_template(1, "png", "{title}{title}");
        let archive = ctx.format_attachment_filename_with_template("pack.rar", "{title}{name}");
        for (name, ext) in [(image, "png"), (archive, "rar")] {
            assert!(name.len() <= MAX_RENDERED_NAME_BYTES);
            assert!(name.ends_with(&format!(".{ext}")));
            let suffixed = with_stable_suffix(Path::new(&name), "12345678");
            let name = suffixed.file_name().unwrap().to_str().unwrap();
            assert!(name.len() <= MAX_RENDERED_NAME_BYTES);
            assert!(name.ends_with(&format!("_12345678.{ext}")));
        }
        let missing = PostNamingContext::new("", None, None, "../bad:id", None);
        let folder = missing.format_folder_path_with_template("./../");
        assert!(!folder.is_empty());
        assert!(Path::new(&folder)
            .components()
            .all(|c| matches!(c, std::path::Component::Normal(_))));
    }

    #[test]
    fn pawchive_sync_slot_is_single_flight() {
        // The slot is process-wide; normalise it first so the test does not
        // depend on execution order.
        finish_pawchive_sync(Ok(serde_json::json!({"reset": true})));

        assert!(try_begin_pawchive_sync(SyncTrigger::Manual));
        assert!(pawchive_sync_status().running);
        // A second trigger while a round is running must not start another, and
        // the slot keeps the trigger of the round that actually holds it.
        assert!(!try_begin_pawchive_sync(SyncTrigger::Check));
        assert_eq!(pawchive_sync_status().trigger.as_deref(), Some("manual"));

        finish_pawchive_sync(Ok(serde_json::json!({"discovered_posts": 3})));
        let status = pawchive_sync_status();
        assert!(!status.running);
        assert!(status.started_at.is_some());
        assert!(status.finished_at.is_some());
        assert!(status.last_error.is_none());
        assert_eq!(status.last_summary.unwrap()["discovered_posts"], 3);

        // A failed round records the error but keeps the last good result.
        assert!(try_begin_pawchive_sync(SyncTrigger::Scheduled));
        finish_pawchive_sync(Err(anyhow!("boom")));
        let status = pawchive_sync_status();
        assert!(!status.running);
        assert_eq!(status.last_error.as_deref(), Some("boom"));
        assert_eq!(status.last_summary.unwrap()["discovered_posts"], 3);
    }

    #[tokio::test]
    async fn sync_respects_the_master_switch_and_the_empty_case() {
        let dir = tempfile::tempdir().unwrap();
        // Both branches below record a round event, so this test writes to the
        // runtime log and has to hold the same lock the logging tests do.
        let _env = with_private_data_dir(&dir);
        let pool = Arc::new(
            DbPool::with_config(
                dir.path().join("gallery.db"),
                crate::db::DbConfig {
                    read_only: false,
                    pool_size: 1,
                },
            )
            .unwrap(),
        );
        let roots = MediaRoots::identical(
            vec![dir.path().to_string_lossy().to_string()],
            vec!["tmp".to_string()],
        );

        // Default state: the master switch is off, so a sync claims nothing.
        {
            let conn = pool.get().unwrap();
            assert!(!get_pawchive_settings(&conn).unwrap().enabled);
        }
        let off = run_pawchive_sync(Arc::clone(&pool), roots.clone(), SyncTrigger::Manual, None)
            .await
            .unwrap();
        assert_eq!(off["enabled"], false);
        assert_eq!(off["synced_subscriptions"], 0);
        assert_eq!(off["discovered_posts"], 0);

        // Enabled with no subscriptions is a no-op that still opens the gate;
        // no network request is issued because the loop body never runs.
        {
            let conn = pool.get().unwrap();
            save_pawchive_settings(
                &conn,
                &PawchiveSettings {
                    enabled: true,
                    ..PawchiveSettings::default()
                },
            )
            .unwrap();
        }
        let on = run_pawchive_sync(Arc::clone(&pool), roots, SyncTrigger::Scheduled, None)
            .await
            .unwrap();
        assert_eq!(on["enabled"], true);
        assert_eq!(on["synced_subscriptions"], 0);
        assert_eq!(on["downloaded_files"], 0);
    }

    // ── Long-term ledger ───────────────────────────────────────────────────

    fn scalar(conn: &Connection, sql: &str) -> i64 {
        conn.query_row(sql, [], |row| row.get(0)).unwrap()
    }

    fn insert_ledger_post(conn: &Connection, subscription_id: i64, post_id: &str) -> i64 {
        conn.execute(
            "INSERT INTO kemono_posts (subscription_id, post_id, title, published_at, status,
                                       created_at, updated_at, manifest_version)
             VALUES (?1, ?2, 'test', '2026-02-01T12:00:00Z', 'pending',
                     '2026-02-01T12:00:00Z', '2026-02-01T12:00:00Z', 1)",
            params![subscription_id, post_id],
        )
        .unwrap();
        conn.last_insert_rowid()
    }

    /// One subscription, one post holding one pending resource, and an explicit
    /// request naming it. The creator id is derived from the request id so a test
    /// can build more than one without colliding on the subscription's unique
    /// key.
    fn attempt_fixture(conn: &Connection, request_id: &str) -> (i64, String) {
        let sub_id = upsert_subscription(
            conn,
            "fanbox",
            &format!("creator-{request_id}"),
            None,
            "/pictures/artist",
            None,
        )
        .unwrap();
        let post = insert_test_post(conn, sub_id, request_id);
        insert_test_file(conn, post, "/data/a.png", "a.png", "image", "pending");
        let settings = PawchiveSettings::default();
        let selection = record_selection(conn, request_id, &[post], &[], &settings).unwrap();
        let attempt = create_attempt(conn, request_id, &selection.selection_id).unwrap();
        (post, attempt.attempt_id)
    }

    fn attempt_post_state(conn: &Connection, attempt_id: &str, post_id: i64) -> String {
        conn.query_row(
            "SELECT state FROM pawchive_attempt_posts WHERE attempt_id = ?1 AND post_id = ?2",
            params![attempt_id, post_id],
            |row| row.get(0),
        )
        .unwrap()
    }

    /// An explicit request is not filtered by the automatic admission rules.
    /// The fixture's every automatic gate says no — the master switch is off,
    /// the subscription is disabled, and its mode is manual — yet the pass the
    /// user asked for has to run: the switches are the round's policy, not the
    /// button the user just pressed. The bug this pins applied `claim_scope` to
    /// manual requests too, and the attempt came back "done" with zero files.
    #[test]
    fn manual_pass_admission_ignores_the_automatic_switches() {
        let conn = test_conn();
        let (post, _attempt) = attempt_fixture(&conn, "req-manual-admission");
        conn.execute(
            "UPDATE kemono_subscriptions SET mode = 'manual'
             WHERE id = (SELECT subscription_id FROM kemono_posts WHERE id = ?1)",
            params![post],
        )
        .unwrap();
        let settings = PawchiveSettings::default();
        assert!(
            !settings.enabled,
            "the fixture starts from a master switch that is off"
        );

        let policy = DownloadPostPolicy::Manual {
            attempt_id: "attempt-manual-admission",
            force_file_ids: &[],
        };
        let admitted = pass_admission_settings(&conn, post, &settings, &policy).unwrap();
        assert!(
            admitted.is_some(),
            "a manual pass is admitted despite the master switch, a disabled subscription and manual mode"
        );

        // The automatic pass over the same facts stops where it always stopped.
        let automatic =
            pass_admission_settings(&conn, post, &settings, &DownloadPostPolicy::Automatic)
                .unwrap();
        assert!(
            automatic.is_none(),
            "an automatic pass is still refused by the same switches"
        );
    }

    /// A manual pass is also not fenced in by the subscription's start date:
    /// the user named the work itself. The automatic pass over an out-of-range
    /// post stays out — that is what the start date is for.
    #[test]
    fn manual_pass_admission_ignores_the_start_date() {
        let conn = test_conn();
        let (post, _attempt) = attempt_fixture(&conn, "req-manual-range");
        conn.execute(
            "UPDATE kemono_subscriptions SET since_date = '2027-01-01'
             WHERE id = (SELECT subscription_id FROM kemono_posts WHERE id = ?1)",
            params![post],
        )
        .unwrap();
        let settings = PawchiveSettings::default();

        let policy = DownloadPostPolicy::Manual {
            attempt_id: "attempt-manual-range",
            force_file_ids: &[],
        };
        assert!(
            pass_admission_settings(&conn, post, &settings, &policy)
                .unwrap()
                .is_some(),
            "a manual pass is admitted past the start date"
        );
        assert!(
            pass_admission_settings(&conn, post, &settings, &DownloadPostPolicy::Automatic)
                .unwrap()
                .is_none(),
            "an automatic pass is still refused outside the start date"
        );
    }

    /// A reclaimed lease has to revoke the pass that held it. The reclaim cannot
    /// know whether that worker is still writing, so it takes the row past the
    /// token the worker holds instead of assuming the worker has stopped — and
    /// every write the worker makes carries that token.
    #[test]
    fn a_reclaimed_claim_cannot_settle_the_row_its_successor_owns() {
        let conn = test_conn();
        let (_post, _attempt) = attempt_fixture(&conn, "req-fence");
        let file_id = scalar(&conn, "SELECT id FROM kemono_files");

        let first = DownloadClaim::new();
        let first_token = first.claim(&conn, file_id).unwrap().unwrap();
        assert!(still_claimed(&conn, file_id, &first, first_token).unwrap());

        // The lease expires: time passes, and the row returns to the queue past
        // this pass's token.
        conn.execute(
            "UPDATE kemono_files SET claimed_at = '2020-01-01T00:00:00+00:00' WHERE id = ?1",
            params![file_id],
        )
        .unwrap();
        assert_eq!(reset_stale_download_claims(&conn, 60).unwrap(), 1);
        assert!(
            !still_claimed(&conn, file_id, &first, first_token).unwrap(),
            "an expired lease must revoke the pass that held it"
        );

        // A new pass takes it and is granted a token of its own.
        let second = DownloadClaim::new();
        let second_token = second.claim(&conn, file_id).unwrap().unwrap();
        assert!(
            second_token > first_token,
            "the claim must fence the old one"
        );
        assert!(still_claimed(&conn, file_id, &second, second_token).unwrap());
        assert!(!still_claimed(&conn, file_id, &first, first_token).unwrap());

        // The old pass's settle is refused by the same statement every settle in
        // the receive loop runs, so it can neither record a result against the
        // new owner's row nor clear the new owner's claim.
        let refused = settle_claimed_file(
            &conn,
            file_id,
            &first,
            first_token,
            "status = 'done', updated_at = ?",
            vec![Utc::now().to_rfc3339().into()],
        )
        .unwrap();
        assert!(!refused, "a fenced-out owner must not settle the row");
        let (status, owner): (String, String) = conn
            .query_row(
                "SELECT status, claimed_by FROM kemono_files WHERE id = ?1",
                params![file_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(status, "downloading");
        assert_eq!(owner, second.owner(), "the successor keeps its claim");

        // The owner that still holds the row settles normally, and the settle
        // releases the claim it held.
        let settled = settle_claimed_file(
            &conn,
            file_id,
            &second,
            second_token,
            "status = 'done', updated_at = ?",
            vec![Utc::now().to_rfc3339().into()],
        )
        .unwrap();
        assert!(settled);
        let (status, owner): (String, String) = conn
            .query_row(
                "SELECT status, claimed_by FROM kemono_files WHERE id = ?1",
                params![file_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(status, "done");
        assert_eq!(owner, "", "a settle releases the claim it held");
    }

    #[test]
    fn cancelling_an_open_attempt_stops_it_and_keeps_what_it_published() {
        let conn = test_conn();
        let sub_id = upsert_subscription(
            &conn,
            "fanbox",
            "creator-cancel",
            None,
            "/pictures/artist",
            None,
        )
        .unwrap();
        let done_post = insert_test_post(&conn, sub_id, "910");
        let open_post = insert_test_post(&conn, sub_id, "911");
        insert_test_file(&conn, done_post, "/data/a.png", "a.png", "image", "pending");
        insert_test_file(&conn, open_post, "/data/b.png", "b.png", "image", "pending");
        let settings = PawchiveSettings::default();
        let selection =
            record_selection(&conn, "req-cancel", &[done_post, open_post], &[], &settings).unwrap();
        let attempt = create_attempt(&conn, "req-cancel", &selection.selection_id).unwrap();
        mark_attempt_post(&conn, &attempt.attempt_id, done_post, "done", 1, "").unwrap();

        assert_eq!(
            cancel_attempt(&conn, &attempt.attempt_id).unwrap(),
            CancelOutcome::Cancelled { posts: 1 },
            "only the outstanding work counts as stopped"
        );
        assert_eq!(
            attempt_state(&conn, &attempt.attempt_id)
                .unwrap()
                .as_deref(),
            Some("cancelled")
        );
        // What was published stays published; the work the pass never reached is
        // recorded as cancelled rather than left queued, so the panel does not
        // report outstanding work for a request the user stopped.
        assert_eq!(
            attempt_post_state(&conn, &attempt.attempt_id, done_post),
            "done"
        );
        assert_eq!(
            attempt_post_state(&conn, &attempt.attempt_id, open_post),
            "cancelled"
        );
    }

    #[test]
    fn a_cancel_is_idempotent_and_refuses_a_finished_attempt() {
        let conn = test_conn();
        let (post, attempt_id) = attempt_fixture(&conn, "req-c1");

        assert!(matches!(
            cancel_attempt(&conn, &attempt_id).unwrap(),
            CancelOutcome::Cancelled { .. }
        ));
        // Asking again asks for the state the task is already in.
        assert_eq!(
            cancel_attempt(&conn, &attempt_id).unwrap(),
            CancelOutcome::AlreadyCancelled
        );

        // A task that finished is not reported as cancelled: there is nothing
        // left to stop, and the answer would misdescribe it.
        let settings = PawchiveSettings::default();
        let done_selection = record_selection(&conn, "req-c2", &[post], &[], &settings).unwrap();
        let done = create_attempt(&conn, "req-c2", &done_selection.selection_id).unwrap();
        mark_attempt_done(&conn, &done.attempt_id, "done", None).unwrap();
        assert_eq!(
            cancel_attempt(&conn, &done.attempt_id).unwrap(),
            CancelOutcome::AlreadyFinished
        );
        assert_eq!(
            attempt_state(&conn, &done.attempt_id).unwrap().as_deref(),
            Some("done"),
            "a refused cancel must not change the state it refused"
        );

        assert_eq!(
            cancel_attempt(&conn, "att_missing").unwrap(),
            CancelOutcome::Unknown
        );
    }

    /// Cancellation is terminal. A pass that was stopped still runs its own final
    /// settle, and without this it would report the request the user cancelled as
    /// one that finished.
    #[test]
    fn a_cancelled_attempt_is_not_settled_afterwards() {
        let conn = test_conn();
        let (_post, attempt_id) = attempt_fixture(&conn, "req-c3");
        cancel_attempt(&conn, &attempt_id).unwrap();

        mark_attempt_done(&conn, &attempt_id, "done", None).unwrap();

        assert_eq!(
            attempt_state(&conn, &attempt_id).unwrap().as_deref(),
            Some("cancelled")
        );
    }

    /// A row that cannot be read fails the read; it does not shorten the list.
    ///
    /// Every page, event list and candidate list in this module used to end
    /// `.filter_map(|row| row.ok())`, which turns a row-level read error into
    /// "no row". A work whose row could not be read therefore vanished from a
    /// page that still reported itself complete: the panel showed nine of ten
    /// works, and the tenth had no error anywhere. This is the shape of that
    /// defect, on the work list, because it is the one an operator would notice
    /// last and trust most.
    #[test]
    fn a_work_whose_row_cannot_be_read_fails_the_page_instead_of_missing_from_it() {
        let conn = test_conn();
        let sub_id = upsert_subscription(
            &conn,
            "fanbox",
            "creator-rowerr",
            None,
            "/pictures/artist",
            None,
        )
        .unwrap();
        insert_test_post(&conn, sub_id, "940");
        let unreadable = insert_test_post(&conn, sub_id, "941");

        // While every row reads, both works are on the page — so the failure
        // below is about the unreadable row and not about a broken query.
        let before = list_subscription_posts(&conn, sub_id, None, None, None).unwrap();
        assert_eq!(before.posts.len(), 2);

        // SQLite keeps a non-numeric string in an INTEGER column as TEXT, so
        // this row now reads as a type error rather than as a value.
        conn.execute(
            "UPDATE kemono_posts SET manifest_version = 'not-a-number' WHERE id = ?1",
            params![unreadable],
        )
        .unwrap();

        assert!(
            list_subscription_posts(&conn, sub_id, None, None, None).is_err(),
            "a work that cannot be read must fail the page, not disappear from it"
        );
    }

    /// A row in the real publish ledger, so a delivery can point at the job
    /// that published it the way the live paths do.
    fn insert_publish_job(conn: &Connection) -> i64 {
        conn.execute(
            "INSERT INTO download_publish_jobs
                 (engine, source_job_id, manifest_version, source_identity, expected_length,
                  expected_blake3, target_path, stage)
             VALUES ('pawchive', '1:1', 1, '/data/ab/art.png', 10, 'abc',
                     '/pictures/a/art.png', 'published')",
            [],
        )
        .unwrap();
        conn.last_insert_rowid()
    }

    fn insert_delivered_file(
        conn: &Connection,
        post_db_id: i64,
        remote_path: &str,
        delivery_source: &str,
        integrity: &str,
        publish_job_id: Option<i64>,
    ) {
        conn.execute(
            "INSERT INTO kemono_files (post_id, source_identity, remote_path, file_name, file_type,
                                       status, delivery_source, integrity, publish_job_id, target_path,
                                       verified_at, created_at, updated_at)
             VALUES (?1, ?2, ?2, 'art.png', 'image', 'done', ?3, ?4, ?5, '/pictures/a/art.png',
                     '2026-02-01T00:00:00Z', '2026-02-01T00:00:00Z', '2026-02-01T00:00:00Z')",
            params![post_db_id, remote_path, delivery_source, integrity, publish_job_id],
        )
        .unwrap();
    }

    /// A post ID is opaque text, not a number.
    ///
    /// Two IDs a 53-bit float would round onto each other have to stay two
    /// works, and the stored identity has to be the source's own string.
    #[test]
    fn the_ledger_keeps_post_identity_as_text_past_the_integer_range() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures/a", None).unwrap();
        let mut row_ids = Vec::new();
        for post_id in ["9007199254740992", "9007199254740993"] {
            row_ids.push(insert_ledger_post(&conn, sub_id, post_id));
        }

        let mut work_ids = Vec::new();
        for row_id in &row_ids {
            work_ids.push(materialize_work_ledger(&conn, *row_id).unwrap().unwrap());
        }
        assert_ne!(
            work_ids[0], work_ids[1],
            "two adjacent post IDs are two works, not one rounded identity"
        );

        let stored: Vec<String> = conn
            .prepare("SELECT post_id FROM pawchive_remote_works ORDER BY post_id")
            .unwrap()
            .query_map([], |row| row.get(0))
            .unwrap()
            .collect::<rusqlite::Result<Vec<_>>>()
            .unwrap();
        assert_eq!(
            stored,
            vec![
                "9007199254740992".to_string(),
                "9007199254740993".to_string()
            ],
            "the identity round-trips as the source wrote it"
        );
        assert_eq!(
            work_ids[0],
            work_id_for("pawchive", "fanbox", "27212726", "9007199254740992")
        );
    }

    /// The backfill advances a high-water mark instead of re-walking.
    #[test]
    fn the_ledger_migration_resumes_from_its_high_water_mark() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures/a", None).unwrap();
        insert_ledger_post(&conn, sub_id, "1001");
        insert_ledger_post(&conn, sub_id, "1002");

        let first = migrate_pawchive_ledger(&conn).unwrap();
        assert_eq!(first.posts_migrated, 2);
        assert!(first.is_ready());
        let mark = first.works_high_water_mark;

        // A second call starts where the first stopped, so there is nothing to
        // redo and the mark does not move.
        let before_idle = conn.total_changes();
        let second = migrate_pawchive_ledger(&conn).unwrap();
        assert_eq!(second.posts_migrated, 0);
        assert_eq!(second.works_high_water_mark, mark);
        assert_eq!(
            conn.total_changes(),
            before_idle,
            "a call that finds nothing to do must not write its bookkeeping again"
        );
        assert_eq!(
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_remote_works"),
            2,
            "a repeated run must not duplicate works"
        );

        // A post discovered later sits above the mark and is picked up.
        insert_ledger_post(&conn, sub_id, "1003");
        let third = migrate_pawchive_ledger(&conn).unwrap();
        assert_eq!(third.posts_migrated, 1);
        assert!(third.works_high_water_mark > mark);
        assert_eq!(
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_remote_works"),
            3
        );
    }

    /// Dropping a subscription unbinds scheduling; it does not delete history.
    #[test]
    fn deleting_a_subscription_keeps_the_acquisition_history() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures/a", None).unwrap();
        let post_db_id = insert_ledger_post(&conn, sub_id, "1001");
        let job_id = insert_publish_job(&conn);
        insert_delivered_file(
            &conn,
            post_db_id,
            "/data/ab/art.png",
            "download",
            "verified",
            Some(job_id),
        );
        materialize_work_ledger(&conn, post_db_id).unwrap();
        let work_id = work_id_for("pawchive", "fanbox", "27212726", "1001");

        assert!(delete_subscription(&conn, sub_id).unwrap());

        // The working rows cascade away. The facts about the source do not.
        assert_eq!(scalar(&conn, "SELECT COUNT(*) FROM kemono_posts"), 0);
        assert_eq!(
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_subscription_works"),
            0,
            "the scheduling binding goes with the subscription"
        );
        assert_eq!(
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_remote_works"),
            1,
            "the work outlives the subscription that found it"
        );
        assert_eq!(
            scalar(
                &conn,
                &format!(
                    "SELECT COUNT(*) FROM pawchive_acquisition_events
                     WHERE work_id = '{work_id}' AND evidence_strength = 'strong'"
                )
            ),
            1,
            "the verified fetch is still on record"
        );

        // Re-adding the subscription re-discovers the same post. The work keeps
        // its identity and the fetch it already had, so the next round has
        // nothing to download.
        let sub_again =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures/a", None).unwrap();
        let post_again = insert_ledger_post(&conn, sub_again, "1001");
        materialize_work_ledger(&conn, post_again).unwrap();
        assert_eq!(
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_remote_works"),
            1
        );
        assert_eq!(
            scalar(
                &conn,
                &format!(
                    "SELECT COUNT(*) FROM pawchive_acquisition_events
                     WHERE work_id = '{work_id}' AND evidence_strength = 'strong'"
                )
            ),
            1,
            "re-discovery must not erase or duplicate the fetch"
        );
    }

    /// Presence is not proof.
    #[test]
    fn a_legacy_done_row_is_recorded_as_presence_not_a_fetch() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures/a", None).unwrap();
        let post_db_id = insert_ledger_post(&conn, sub_id, "1001");
        insert_delivered_file(&conn, post_db_id, "/data/a.png", "legacy", "", None);
        insert_delivered_file(&conn, post_db_id, "/data/b.zip", "present", "", None);

        materialize_work_ledger(&conn, post_db_id).unwrap();

        assert_eq!(
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_acquisition_events"),
            2
        );
        assert_eq!(
            scalar(
                &conn,
                "SELECT COUNT(*) FROM pawchive_acquisition_events WHERE evidence_strength = 'strong'"
            ),
            0,
            "a legacy done and a file seen on disk are observations, not fetches"
        );
        let sources: Vec<String> = conn
            .prepare(
                "SELECT evidence_source FROM pawchive_acquisition_events ORDER BY evidence_source",
            )
            .unwrap()
            .query_map([], |row| row.get(0))
            .unwrap()
            .collect::<rusqlite::Result<Vec<_>>>()
            .unwrap();
        assert_eq!(
            sources,
            vec![
                "legacy_directory_rule".to_string(),
                "observed_on_disk".to_string()
            ]
        );
    }

    /// Running the ledger writes again adds no second copy of a fact.
    #[test]
    fn migrating_the_ledger_twice_adds_no_second_fact() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures/a", None).unwrap();
        let post_db_id = insert_ledger_post(&conn, sub_id, "1001");
        let job_id = insert_publish_job(&conn);
        insert_delivered_file(
            &conn,
            post_db_id,
            "/data/ab/art.png",
            "download",
            "verified",
            Some(job_id),
        );
        conn.execute(
            "INSERT INTO pawchive_post_decisions
                 (post_id, manifest_version, action, reason, bound_path, created_at)
             VALUES (?1, 1, 'confirm', '', '', '2026-02-02T00:00:00Z')",
            params![post_db_id],
        )
        .unwrap();

        materialize_work_ledger(&conn, post_db_id).unwrap();
        let before = (
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_resource_versions"),
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_acquisition_events"),
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_work_manifests"),
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_manifest_members"),
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_user_decisions"),
        );

        materialize_work_ledger(&conn, post_db_id).unwrap();
        migrate_pawchive_ledger(&conn).unwrap();

        let after = (
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_resource_versions"),
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_acquisition_events"),
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_work_manifests"),
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_manifest_members"),
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_user_decisions"),
        );
        assert_eq!(after, before);
        assert!(before.0 > 0 && before.1 > 0 && before.4 > 0);
    }

    /// A partial observation never becomes what the work requires.
    #[test]
    fn an_incomplete_observation_does_not_replace_a_complete_manifest() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures/a", None).unwrap();
        let post_db_id = insert_ledger_post(&conn, sub_id, "1001");
        let work_id = work_id_for("pawchive", "fanbox", "27212726", "1001");

        let insert_manifest = |manifest_id: &str, fingerprint: &str, completeness: &str| {
            conn.execute(
                "INSERT INTO pawchive_work_manifests
                     (manifest_id, work_id, member_fingerprint, completeness, source_revision,
                      observed_at, is_current)
                 VALUES (?1, ?2, ?3, ?4, '1', '2026-01-01T00:00:00Z', 0)",
                params![manifest_id, work_id, fingerprint, completeness],
            )
            .unwrap();
        };
        let current = |conn: &Connection| -> String {
            conn.query_row(
                "SELECT manifest_id FROM pawchive_work_manifests WHERE work_id = ?1 AND is_current = 1",
                params![work_id],
                |row| row.get(0),
            )
            .unwrap()
        };

        let complete = manifest_id_for(&work_id, "fp-full", "complete", "1");
        insert_manifest(&complete, "fp-full", "complete");
        set_current_manifest(&conn, &work_id, &complete, ManifestCompleteness::Complete).unwrap();

        // A summary that omitted the attachment list is stored, and stays an
        // observation: it is not evidence that the attachment was withdrawn.
        let partial = manifest_id_for(&work_id, "fp-summary", "partial", "2");
        insert_manifest(&partial, "fp-summary", "partial");
        set_current_manifest(&conn, &work_id, &partial, ManifestCompleteness::Partial).unwrap();
        assert_eq!(current(&conn), complete);
        assert_eq!(
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_work_manifests"),
            2,
            "the incomplete observation is kept, not discarded"
        );

        // A fresh complete observation does take over.
        let newer = manifest_id_for(&work_id, "fp-next", "complete", "3");
        insert_manifest(&newer, "fp-next", "complete");
        set_current_manifest(&conn, &work_id, &newer, ManifestCompleteness::Complete).unwrap();
        assert_eq!(current(&conn), newer);
        let _ = post_db_id;
    }

    /// A legacy confirmation keeps its wording and claims no scope.
    #[test]
    fn a_decision_reaches_the_ledger_when_it_is_made_and_names_what_it_covers() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures/a", None).unwrap();
        let post_db_id = insert_ledger_post(&conn, sub_id, "1001");
        insert_test_file(
            &conn,
            post_db_id,
            "ab/cd/art.png",
            "art.png",
            "image",
            "pending",
        );

        let outcome = record_post_decision(
            &conn,
            post_db_id,
            PostDecisionAction::Confirm,
            "看过",
            "/pictures/a",
            None,
        )
        .unwrap();
        assert!(matches!(outcome, DecisionOutcome::Applied(_)));

        // No restart and no backfill walk: the decision is on the ledger now,
        // which is what dropping the subscription has to find.
        let (action, scope, manifest_id, members): (String, String, String, i64) = conn
            .query_row(
                "SELECT d.action, d.scope_kind, d.manifest_id,
                        (SELECT COUNT(*) FROM pawchive_decision_members m
                         WHERE m.decision_id = d.decision_id)
                 FROM pawchive_user_decisions d",
                [],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
            )
            .unwrap();
        assert_eq!(action, "confirm");
        assert_eq!(
            scope, "exact",
            "the write point knows what was decided about"
        );
        assert!(!manifest_id.is_empty(), "and names the manifest it saw");
        assert_eq!(members, 1, "and the resource versions in it");

        // A later walk copies the same working decision. It must not add a
        // second one, and it must not take the scope back to unknown.
        migrate_pawchive_ledger(&conn).unwrap();
        assert_eq!(
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_user_decisions"),
            1
        );
        assert_eq!(
            scalar(&conn, "SELECT COUNT(*) FROM pawchive_decision_members"),
            1
        );
        assert_eq!(
            conn.query_row(
                "SELECT scope_kind FROM pawchive_user_decisions",
                [],
                |row| { row.get::<_, String>(0) }
            )
            .unwrap(),
            "exact"
        );
    }

    /// The acquisition facts are the reason the long-term ledger exists, so the
    /// projection has to answer them from the ledger alone — including after the
    /// subscription that discovered the work is gone.
    ///
    /// The other half of the answer is the distinction the plan insists on: a
    /// file this install published is a fetch, a file merely found on disk is
    /// presence, and only the first may answer an automatic requirement.
    #[test]
    fn the_projection_answers_who_fetched_what_after_the_subscription_is_gone() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures/a", None).unwrap();
        let post_db_id = insert_ledger_post(&conn, sub_id, "1001");
        let job = insert_publish_job(&conn);
        // One resource with a publish behind it, one that is only on disk.
        insert_delivered_file(
            &conn,
            post_db_id,
            "ab/cd/art.png",
            "download",
            "verified",
            Some(job),
        );
        insert_delivered_file(&conn, post_db_id, "ab/cd/extra.png", "present", "", None);

        let work_id = record_work_observation(&conn, post_db_id, ManifestCompleteness::Complete)
            .unwrap()
            .expect("the work has a subscription to take its identity from");

        // The subscription goes away. Only the scheduling binding may.
        assert!(delete_subscription(&conn, sub_id).unwrap());
        // The premise, asserted rather than assumed: the working rows the
        // subscription owned cascaded away, so the answers below can only come
        // from the long-term ledger.
        assert_eq!(scalar(&conn, "SELECT COUNT(*) FROM kemono_posts"), 0);
        assert_eq!(scalar(&conn, "SELECT COUNT(*) FROM kemono_files"), 0);

        let view = assess_work_from_ledger(&conn, &work_id)
            .unwrap()
            .expect("the work outlives the subscription that discovered it");
        assert_eq!(view.manifest_members, 2);
        assert!(
            view.manifest_complete,
            "the observation listed the whole set"
        );
        assert_eq!(
            view.acquired_resource_versions.len(),
            1,
            "a verified publish is a fetch"
        );
        assert_eq!(
            view.unproven_resource_versions.len(),
            1,
            "a file found on disk is presence, not a fetch"
        );
        assert_eq!(
            view.requires_fetch.len(),
            1,
            "and presence does not answer the requirement"
        );
        assert!(
            view.reason_codes
                .contains(&LEDGER_REASON_UNPROVEN_PRESENCE.to_string()),
            "the difference is reported, not flattened: {:?}",
            view.reason_codes
        );
        assert!(view
            .reason_codes
            .contains(&LEDGER_REASON_REQUIRES_FETCH.to_string()));
        assert!(
            !view.needs_confirmation,
            "no decision stands, so there is no scope to re-check"
        );
    }

    /// An inherited confirmation cannot be widened, and it must not silently
    /// become a bulk re-download either: it freezes the work for one review.
    ///
    /// The plan forbids rebuilding the old scope from today's type switches, so
    /// the assertion that matters is that the decision contributes *no* coverage
    /// while the manifest still holds a member. If the projection read
    /// `PawchiveSettings` it could be argued into covering the member; because
    /// it does not, the widening is not expressible.
    #[test]
    fn a_legacy_decision_freezes_the_work_instead_of_covering_it() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures/a", None).unwrap();
        let post_db_id = insert_ledger_post(&conn, sub_id, "1001");
        insert_test_file(
            &conn,
            post_db_id,
            "ab/cd/art.png",
            "art.png",
            "image",
            "pending",
        );
        conn.execute(
            "INSERT INTO pawchive_post_decisions
                 (post_id, manifest_version, action, reason, bound_path, created_at)
             VALUES (?1, 1, 'confirm', '看过', '/pictures/a', '2026-02-02T00:00:00Z')",
            params![post_db_id],
        )
        .unwrap();

        // The backfill path: an old confirmation, no recorded scope.
        let work_id = materialize_work_ledger(&conn, post_db_id).unwrap().unwrap();

        let view = assess_work_from_ledger(&conn, &work_id).unwrap().unwrap();
        assert!(view.decision_scope_unknown, "the copy claims no scope");
        assert!(
            view.covered_resource_versions.is_empty(),
            "an unknown scope covers nothing, not everything"
        );
        assert_eq!(
            view.requires_fetch.len(),
            1,
            "the member is not subtracted by a decision that never named it"
        );
        assert!(
            view.needs_confirmation,
            "and the work is held for one review rather than batch re-fetched"
        );
        assert!(view
            .reason_codes
            .contains(&LEDGER_REASON_DECISION_SCOPE_UNKNOWN.to_string()));
        assert!(
            view.reason_codes
                .contains(&LEDGER_REASON_MANIFEST_INCOMPLETE.to_string()),
            "a backfilled observation cannot claim it saw the whole set: {:?}",
            view.reason_codes
        );
    }

    /// The freeze is a review prompt, not a permanent stop: a work whose
    /// resources are all accounted for has nothing to re-check.
    #[test]
    fn a_legacy_decision_on_an_accounted_for_work_is_not_re_questioned() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures/a", None).unwrap();
        let post_db_id = insert_ledger_post(&conn, sub_id, "1001");
        let job = insert_publish_job(&conn);
        insert_delivered_file(
            &conn,
            post_db_id,
            "ab/cd/art.png",
            "download",
            "verified",
            Some(job),
        );
        conn.execute(
            "INSERT INTO pawchive_post_decisions
                 (post_id, manifest_version, action, reason, bound_path, created_at)
             VALUES (?1, 1, 'confirm', '看过', '/pictures/a', '2026-02-02T00:00:00Z')",
            params![post_db_id],
        )
        .unwrap();

        let work_id = record_work_observation(&conn, post_db_id, ManifestCompleteness::Complete)
            .unwrap()
            .unwrap();
        materialize_legacy_decisions(&conn, post_db_id, &work_id).unwrap();

        let view = assess_work_from_ledger(&conn, &work_id).unwrap().unwrap();
        assert!(view.decision_scope_unknown);
        assert!(
            view.requires_fetch.is_empty(),
            "the only member was fetched"
        );
        assert!(
            !view.needs_confirmation,
            "nothing is in question, so the work is not held back"
        );
        assert!(view
            .reason_codes
            .contains(&LEDGER_REASON_NOTHING_OUTSTANDING.to_string()));
    }

