    /// A replacement at the same path is a new version of the same resource, and
    /// the old version is kept: its acquisition history may still be the only
    /// record that those bytes were ever fetched.
    #[test]
    fn a_new_validator_at_the_same_path_keeps_the_old_version() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures/a", None).unwrap();
        let post_db_id = insert_ledger_post(&conn, sub_id, "1001");
        insert_test_file(
            &conn,
            post_db_id,
            "ab/cd/art.png",
            "art.png",
            "image",
            "pending",
        );
        let set_validator = |raw: &str| {
            conn.execute(
                "UPDATE kemono_files SET resume_validator = ?1, expected_length = 128",
                params![raw],
            )
            .unwrap();
        };

        set_validator("128\n\"etag-1\"");
        let work_id = materialize_work_ledger(&conn, post_db_id).unwrap().unwrap();
        let first = version_row(&conn, "ab/cd/art.png").unwrap().3;

        set_validator("128\n\"etag-2\"");
        materialize_work_ledger_inner(
            &conn,
            post_db_id,
            ManifestCompleteness::LegacyUnknown,
            false,
        )
        .unwrap();

        let rows: Vec<(String, String)> = conn
            .prepare(
                "SELECT version_key, resource_version_id FROM pawchive_resource_versions
                 WHERE work_id = ?1 ORDER BY version_key",
            )
            .unwrap()
            .query_map(params![work_id], |row| Ok((row.get(0)?, row.get(1)?)))
            .unwrap()
            .collect::<rusqlite::Result<Vec<_>>>()
            .unwrap();
        assert_eq!(
            rows.len(),
            2,
            "the earlier version is not overwritten: {rows:?}"
        );
        assert_eq!(rows[0].0, "\"etag-1\"");
        assert_eq!(rows[1].0, "\"etag-2\"");
        assert_eq!(
            rows[0].1, first,
            "and it keeps the identity it was recorded under"
        );
    }

    /// The property that keeps the version change from causing re-downloads: a
    /// finished download has no strong version evidence left, so a later
    /// observation cannot re-key the resource out from under its acquisition
    /// event and make the work read as never fetched.
    #[test]
    fn a_finished_download_keeps_its_unknown_version_and_its_fetch() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures/a", None).unwrap();
        let post_db_id = insert_ledger_post(&conn, sub_id, "1001");
        let job = insert_publish_job(&conn);
        insert_delivered_file(
            &conn,
            post_db_id,
            "ab/cd/art.png",
            "download",
            "verified",
            Some(job),
        );
        // Exactly the state a successful publish leaves: the resume validator
        // cleared, and the digest marked as this install's own.
        conn.execute(
            "UPDATE kemono_files
             SET expected_blake3 = 'abc123', hash_source = 'local', resume_validator = '',
                 expected_length = 128",
            [],
        )
        .unwrap();

        let work_id = record_work_observation(&conn, post_db_id, ManifestCompleteness::Complete)
            .unwrap()
            .unwrap();
        let (version_key, _, identity_basis, rv_id) = version_row(&conn, "ab/cd/art.png").unwrap();
        assert_eq!(version_key, "unknown");
        assert_eq!(
            identity_basis, "path",
            "the key is the remote path, so the ledger says so"
        );

        let before = assess_work_from_ledger(&conn, &work_id).unwrap().unwrap();
        assert_eq!(before.acquired_resource_versions, vec![rv_id.clone()]);
        assert!(before.requires_fetch.is_empty());

        // Re-observe the whole work, the way the library walk does.
        materialize_work_ledger_inner(&conn, post_db_id, ManifestCompleteness::Complete, false)
            .unwrap();

        let after = assess_work_from_ledger(&conn, &work_id).unwrap().unwrap();
        assert_eq!(
            after.acquired_resource_versions,
            vec![rv_id],
            "the fetch is still recorded against the same version"
        );
        assert!(
            after.requires_fetch.is_empty(),
            "so the work is not read as never fetched: {:?}",
            after.reason_codes
        );
    }

    /// The identity upgrade the plan requires with the move it requires.
    ///
    /// A resource the site now identifies by its own attachment id used to be
    /// keyed by the path it is served at. Re-keying it in place would leave the
    /// acquisition event pointing at a resource version that no longer exists,
    /// and the work would read as never fetched — a library-wide re-download.
    /// The move therefore carries the version row and every event that names it
    /// across in one transaction, and the reverse assertion below is the one
    /// that matters: after the move the work is *still* fetched.
    #[test]
    fn moving_a_resource_identity_carries_its_fetch_with_it() {
        let conn = test_conn();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures/a", None).unwrap();
        let post_db_id = insert_ledger_post(&conn, sub_id, "1001");
        let job = insert_publish_job(&conn);
        // A real completed download: strong evidence, keyed by the remote path.
        insert_delivered_file(
            &conn,
            post_db_id,
            "ab/cd/art.png",
            "download",
            "verified",
            Some(job),
        );
        let file_id: i64 = conn
            .query_row(
                "SELECT id FROM kemono_files WHERE post_id = ?1",
                params![post_db_id],
                |row| row.get(0),
            )
            .unwrap();
        let work_id = record_work_observation(&conn, post_db_id, ManifestCompleteness::Complete)
            .unwrap()
            .unwrap();
        let before = assess_work_from_ledger(&conn, &work_id).unwrap().unwrap();
        assert_eq!(before.acquired_resource_versions.len(), 1);
        let old_version = before.acquired_resource_versions[0].clone();

        // The source now names the attachment, and the ledger row is re-keyed.
        let outcome = move_resource_identity(&conn, file_id, "ab/cd/art.png", "att-42").unwrap();
        assert!(
            matches!(outcome, IdentityMove::Moved { ref to, .. } if to == "att-42"),
            "{outcome:?}"
        );
        let (identity, basis): (String, String) = conn
            .query_row(
                "SELECT source_identity, identity_basis FROM kemono_files WHERE id = ?1",
                params![file_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(identity, "att-42");
        assert_eq!(basis, "source_id");

        let new_version = resource_version_id_for(&work_id, "att-42", UNKNOWN_VERSION);
        assert_ne!(new_version, old_version);
        let after = assess_work_from_ledger(&conn, &work_id).unwrap().unwrap();
        assert_eq!(
            after.acquired_resource_versions,
            vec![new_version.clone()],
            "the fetch moved with the resource instead of being orphaned"
        );
        assert!(
            after.requires_fetch.is_empty(),
            "so the work is not read as never fetched: {:?}",
            after.reason_codes
        );
        let leftovers: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM pawchive_acquisition_events WHERE resource_version_id = ?1",
                params![old_version],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(leftovers, 0, "nothing is left on the old key");

        // The move is not repeatable into a re-fetch, and a second call with the
        // same evidence is a no-op rather than a second row.
        assert!(matches!(
            move_resource_identity(&conn, file_id, "ab/cd/art.png", "att-42").unwrap(),
            IdentityMove::Unchanged
        ));
        // A different id for a resource already keyed by an id is not a path-key
        // upgrade: guessing which of the two the site means would be inventing
        // identity.
        assert!(matches!(
            move_resource_identity(&conn, file_id, "ab/cd/art.png", "att-99").unwrap(),
            IdentityMove::Unchanged
        ));
        // An occupied destination is a conflict, never a merge. The conflict is
        // about the same work: `(post_id, source_identity)` is what makes one
        // resource one row, so a key already taken on this post is taken, and
        // merging would silently declare two resources one.
        insert_test_file(
            &conn,
            post_db_id,
            "att-42x",
            "taken.png",
            "image",
            "pending",
        );
        let taken_id: i64 = conn
            .query_row(
                "SELECT id FROM kemono_files WHERE source_identity = 'att-42x'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        // A second path-keyed resource on the same post whose move would collide.
        insert_test_file(
            &conn,
            post_db_id,
            "/ab/cd/second.png",
            "second.png",
            "image",
            "pending",
        );
        conn.execute("UPDATE kemono_files SET remote_path = '/ab/cd/second.png' WHERE source_identity = '/ab/cd/second.png'", []).unwrap();
        let second_id: i64 = conn
            .query_row(
                "SELECT id FROM kemono_files WHERE source_identity = '/ab/cd/second.png'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert!(matches!(
            move_resource_identity(&conn, second_id, "/ab/cd/second.png", "att-42x").unwrap(),
            IdentityMove::Conflict { .. }
        ));
        // The refused move changed nothing: not the moving row, not the
        // occupying one.
        let (identity, basis): (String, String) = conn
            .query_row(
                "SELECT source_identity, identity_basis FROM kemono_files WHERE id = ?1",
                params![second_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(identity, "/ab/cd/second.png");
        assert_eq!(basis, "path");
        let occupant: String = conn
            .query_row(
                "SELECT source_identity FROM kemono_files WHERE id = ?1",
                params![taken_id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(occupant, "att-42x");
        // An unknown row is reported, not silently ignored.
        assert!(matches!(
            move_resource_identity(&conn, 999_999, "/ab/cd/x.png", "att-1").unwrap(),
            IdentityMove::NotFound
        ));
    }

    /// Accepting a local range is a policy, not a download.
    ///
    /// The plan separates the three facts this touches: the decision covers the
    /// resource versions the user looked at, the acquisition ledger is
    /// untouched, and the work stops being a question the next preview asks.
    #[test]
    fn accepting_a_legacy_scope_covers_without_inventing_a_fetch() {
        use crate::pawchive_pairing::preview_day_pairing;

        let conn = test_conn();
        // The pairing preview reads the content-group ledger, which a writable
        // startup creates; the fixture has to stand in for that.
        crate::pawchive_groups::ensure_content_group_schema(&conn).unwrap();
        let sub_id =
            upsert_subscription(&conn, "fanbox", "27212726", None, "/pictures/a", None).unwrap();
        let post_db_id = insert_ledger_post(&conn, sub_id, "1001");
        insert_test_file(
            &conn,
            post_db_id,
            "/ab/cd/art.png",
            "art.png",
            "image",
            "pending",
        );
        conn.execute(
            "UPDATE kemono_posts SET published_at = '2026-09-14T10:00:00' WHERE id = ?1",
            params![post_db_id],
        )
        .unwrap();
        let work_id = record_work_observation(&conn, post_db_id, ManifestCompleteness::Complete)
            .unwrap()
            .unwrap();

        let before = assess_work_from_ledger(&conn, &work_id).unwrap().unwrap();
        assert_eq!(before.acquired_resource_versions, Vec::<String>::new());
        assert_eq!(before.requires_fetch.len(), 1, "the resource is still owed");

        let outcome =
            accept_legacy_scope(&conn, post_db_id, "本地旧库已确认", "/pictures/a").unwrap();
        let LegacyScopeOutcome::Accepted { covered } = outcome else {
            panic!("expected an accepted scope, got {outcome:?}");
        };
        assert_eq!(covered, 1, "the current manifest's members are covered");

        let after = assess_work_from_ledger(&conn, &work_id).unwrap().unwrap();
        assert_eq!(
            after.covered_resource_versions.len(),
            1,
            "the accepted range answers the requirement"
        );
        assert!(
            after.acquired_resource_versions.is_empty(),
            "accepting is not a fetch and must never be written as one"
        );
        assert!(
            after.requires_fetch.is_empty(),
            "an accepted scope releases the automatic requirement"
        );

        // Accepting again does not move the frozen range to today's manifest.
        assert!(matches!(
            accept_legacy_scope(&conn, post_db_id, "再看一次", "/pictures/a").unwrap(),
            LegacyScopeOutcome::Covered
        ));
        assert!(matches!(
            accept_legacy_scope(&conn, 999_999, "", "").unwrap(),
            LegacyScopeOutcome::NotFound
        ));

        // The pairing preview reads the decision: a work the user has accepted
        // is no longer offered as an open question.
        let preview = preview_day_pairing(&conn, None, "2026-09-14", false).unwrap();
        assert!(
            !preview.frozen_works.contains(&post_db_id),
            "an accepted work is not frozen: {:?}",
            preview.frozen_works
        );
    }

