    #[test]
    fn static_author_discovery_walk_21_page_and_101_page_with_budget_slicing() {
        let conn = test_conn();
        let cap = PAWCHIVE_ROUND_MAX_POSTS_PER_SUBSCRIPTION; // 2000 posts per subscription per round

        // 21-page author: 21 * 50 = 1050 posts
        let sub_21_page = auto_subscription(&conn, "fanbox", "author_21p", "/pictures/author_21p");
        let posts_21 = seed_pending_backlog(&conn, sub_21_page, 21 * 50, "2026-03-01");
        assert_eq!(posts_21.len(), 1050);

        // 101-page author: 101 * 50 = 5050 posts
        let sub_101_page =
            auto_subscription(&conn, "fanbox", "author_101p", "/pictures/author_101p");
        let posts_101 = seed_pending_backlog(&conn, sub_101_page, 101 * 50, "2026-01-01");
        assert_eq!(posts_101.len(), 5050);

        // Round 1:
        // Total outstanding = 1050 + 5050 = 6100 posts.
        // Budget slicing:
        // - author_21p: 1050 <= 2000, all 1050 included.
        // - author_101p: capped at 2000.
        // Total scheduled in Round 1 = 1050 + 2000 = 3050 posts.
        let round1 = schedule_round_order(&conn, false).unwrap();
        assert_eq!(round1.outstanding, 6100);
        assert_eq!(round1.posts.len(), 1050 + cap);
        assert!(round1.truncated());

        let count_21 = round1
            .posts
            .iter()
            .filter(|p| p.subscription_id == sub_21_page)
            .count();
        let count_101 = round1
            .posts
            .iter()
            .filter(|p| p.subscription_id == sub_101_page)
            .count();
        assert_eq!(count_21, 1050, "21-page author fits completely in round 1");
        assert_eq!(
            count_101, cap,
            "101-page author is budget-sliced at 2000 in round 1"
        );

        // Simulate completing round 1 posts for author_21p and author_101p
        conn.execute(
            "UPDATE kemono_posts SET status = 'completed', assessment_state = 'complete'
             WHERE subscription_id = ?1",
            params![sub_21_page],
        )
        .unwrap();
        conn.execute(
            "UPDATE kemono_posts SET status = 'completed', assessment_state = 'complete'
             WHERE id IN (
                 SELECT id FROM kemono_posts
                 WHERE subscription_id = ?1 AND status = 'pending'
                 LIMIT ?2
             )",
            params![sub_101_page, cap as i64],
        )
        .unwrap();

        // Round 2:
        // author_21p has 0 outstanding.
        // author_101p has 5050 - 2000 = 3050 outstanding.
        // Round 2 takes 2000 from author_101p.
        let round2 = schedule_round_order(&conn, false).unwrap();
        assert_eq!(round2.outstanding, 3050);
        assert_eq!(round2.posts.len(), cap);
        assert!(round2.truncated());

        // Simulate completing round 2
        conn.execute(
            "UPDATE kemono_posts SET status = 'completed', assessment_state = 'complete'
             WHERE id IN (
                 SELECT id FROM kemono_posts
                 WHERE subscription_id = ?1 AND status = 'pending'
                 LIMIT ?2
             )",
            params![sub_101_page, cap as i64],
        )
        .unwrap();

        // Round 3:
        // author_101p has 3050 - 2000 = 1050 outstanding.
        // Takes remaining 1050 (under cap, not truncated).
        let round3 = schedule_round_order(&conn, false).unwrap();
        assert_eq!(round3.outstanding, 1050);
        assert_eq!(round3.posts.len(), 1050);
        assert!(!round3.truncated());
    }

    #[test]
    fn acceptance_matrix_cross_day_and_cross_year_dates_timezone_alignment() {
        let conn = test_conn();
        let sub = auto_subscription(&conn, "fanbox", "cross_tz", "/pictures/cross_tz");

        // 1. Cross-year near-midnight: 2025-12-31T23:30:00+09:00 (Tokyo time)
        // Published in Japan near midnight of 2025-12-31; UTC is 2025-12-31T14:30:00Z.
        // Source date is 2025-12-31, NOT bumped to 2026-01-01.
        let p1 = insert_test_post(&conn, sub, "p_cross_year");
        conn.execute(
            "UPDATE kemono_posts SET published_at = ?1, assessment_state = 'pending' WHERE id = ?2",
            params!["2025-12-31T23:30:00+09:00", p1],
        )
        .unwrap();

        // 2. Cross-day: 2026-01-01T00:15:00Z (UTC near midnight)
        let p2 = insert_test_post(&conn, sub, "p_new_year");
        conn.execute(
            "UPDATE kemono_posts SET published_at = ?1, assessment_state = 'pending' WHERE id = ?2",
            params!["2026-01-01T00:15:00Z", p2],
        )
        .unwrap();

        // 3. Month precision: 2026-02
        let p3 = insert_test_post(&conn, sub, "p_month_only");
        conn.execute(
            "UPDATE kemono_posts SET published_at = ?1, assessment_state = 'pending' WHERE id = ?2",
            params!["2026-02", p3],
        )
        .unwrap();

        // Verify dates in ledger
        let d1: String = conn
            .query_row(
                "SELECT published_at FROM kemono_posts WHERE id = ?1",
                params![p1],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(d1, "2025-12-31T23:30:00+09:00");

        let d2: String = conn
            .query_row(
                "SELECT published_at FROM kemono_posts WHERE id = ?1",
                params![p2],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(d2, "2026-01-01T00:15:00Z");

        let d3: String = conn
            .query_row(
                "SELECT published_at FROM kemono_posts WHERE id = ?1",
                params![p3],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(d3, "2026-02");

        // WorkNamingContext preserves canonical publication day without synthesizing false 00:00
        let ctx = crate::work_naming::WorkNamingContext {
            site: "pawchive".to_string(),
            service: "fanbox".to_string(),
            creator_id: "cross_tz".to_string(),
            post_id: "p_month_only".to_string(),
            date: "2026-02".to_string(),
            date_precision: crate::pawchive_groups::DatePrecision::Month,
            ..Default::default()
        };
        let tmpl = crate::work_naming::NamingTemplateSet {
            folder: "{date} {title}".to_string(),
            image: None,
            attachment: None,
            attachment_name: None,
        };
        let rendered =
            crate::work_naming::render(&ctx, &tmpl, crate::work_naming::SemanticVersion::WorkV2);
        assert_eq!(rendered.folder_relative, "2026-02 untitled");
        assert!(rendered
            .tokens
            .iter()
            .any(|t| t.token == "{date}" && t.value == "2026-02"));
    }

    #[test]
    fn acceptance_matrix_merge_and_split_across_multi_level_archives() {
        let conn = test_conn();
        let sub = auto_subscription(&conn, "fanbox", "multi_arch", "/pictures/multi_arch");
        let post_db_id = seed_listed_post(&conn, sub, "multi_post", "2026-05-15", "pending");

        conn.execute(
            "INSERT INTO kemono_files (
                post_id, source_identity, remote_path, file_name, file_type,
                status, created_at, updated_at, identity_basis
             ) VALUES (?1, 'img-1', '/files/img.png', 'img.png', 'image', 'pending',
                       '2026-05-15T00:00:00Z', '2026-05-15T00:00:00Z', 'source_id')",
            params![post_db_id],
        )
        .unwrap();

        let _ = record_work_observation(&conn, post_db_id, ManifestCompleteness::Complete)
            .unwrap()
            .unwrap();

        // Multi-level content groups:
        // Level 1: /pictures/multi_arch/2026-05-15 Work
        // Level 2: /pictures/multi_arch/2026/2026-05-15 Nested
        // Level 3: /pictures/multi_arch/Archive/Special/2026-05-15 Deep
        crate::pawchive_groups::ensure_content_group_schema(&conn).unwrap();
        let g1 = "grp_level1";
        let g2 = "grp_level2";
        let g3 = "grp_level3";

        for (gid, rel) in [
            (g1, "2026-05-15 Work"),
            (g2, "2026/2026-05-15 Nested"),
            (g3, "Archive/Special/2026-05-15 Deep"),
        ] {
            conn.execute(
                "INSERT INTO content_groups (
                    group_id, artist_scope_id, root_relative, artist_root, date, precision, generation
                 ) VALUES (?1, (SELECT printf('artist:%d', artist_id) FROM kemono_subscriptions WHERE id = ?2),
                           ?3, '/pictures/multi_arch', '2026-05-15', 'day', 1)",
                params![gid, sub, rel],
            )
            .unwrap();
        }

        // Multiple groups on same day create candidate ambiguity
        let settings = PawchiveSettings::default();
        let d = demand_set(&conn, post_db_id, &settings).unwrap().unwrap();
        assert!(
            d.blocked_by_ambiguity,
            "multiple multi-level candidate groups block demand"
        );

        // Exclude g2 and g3
        crate::pawchive_pairing_write::set_group_baseline_exclusion(
            &conn,
            g2,
            true,
            "split archive part",
        )
        .unwrap();
        crate::pawchive_pairing_write::set_group_baseline_exclusion(
            &conn,
            g3,
            true,
            "deep archive part",
        )
        .unwrap();

        // Pair primary group g1 and accept legacy scope
        crate::pawchive_pairing_write::record_group_pairing(
            &conn,
            post_db_id,
            g1,
            "primary group pairing",
            1.0,
            false,
        )
        .unwrap();
        let scope_outcome = accept_legacy_scope(
            &conn,
            post_db_id,
            "confirmed multi-level primary group",
            "/pictures/multi_arch/2026-05-15 Work",
        )
        .unwrap();
        assert!(matches!(scope_outcome, LegacyScopeOutcome::Accepted { .. }));

        // Now demand calculation is unblocked and required resources is empty (user accepted)
        let unblocked = demand_set(&conn, post_db_id, &settings).unwrap().unwrap();
        assert!(!unblocked.blocked_by_ambiguity);
        assert!(unblocked.required_resources.is_empty());
    }

    #[test]
    fn acceptance_matrix_crash_window_races_and_recovery() {
        let conn = test_conn();
        let sub = auto_subscription(&conn, "fanbox", "crash_artist", "/pictures/crash");
        let post_db_id = seed_listed_post(&conn, sub, "crash_p1", "2026-07-01", "pending");

        // Simulate crash window 1: staged artifact ready, but crash before ledger acquisition commit
        let (work_id, _) = crate::pawchive_pairing_write::work_of_post(&conn, post_db_id)
            .unwrap()
            .unwrap();
        let r_version = "v_staged_recovered_001";

        // Record acquisition with idempotency key
        let key = format!("attempt_crash_recovery_{r_version}");
        insert_acquisition_event(
            &conn,
            &key,
            &work_id,
            r_version,
            "att_crash_1",
            EvidenceSource::PublishLedger,
            Some(1),
            "2026-07-01T12:00:00Z",
            "/pictures/crash/file.png",
            "2026-07-01T12:00:00Z",
        )
        .unwrap();

        // Simulate crash recovery: replaying the same acquisition event is idempotent
        insert_acquisition_event(
            &conn,
            &key,
            &work_id,
            r_version,
            "att_crash_1",
            EvidenceSource::PublishLedger,
            Some(1),
            "2026-07-01T12:00:00Z",
            "/pictures/crash/file.png",
            "2026-07-01T12:00:00Z",
        )
        .unwrap();

        let event_count: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM pawchive_acquisition_events WHERE idempotency_key = ?1",
                params![key],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(
            event_count, 1,
            "exactly 1 event recorded despite crash replay"
        );
    }

