    #[test]
    fn restart_and_migration_matrix_full_chain_preserves_ledger_across_resubscribe_and_restart() {
        let conn = test_conn();
        let creator_id = "889900";
        let sub_id = auto_subscription(&conn, "fanbox", creator_id, "/pictures/persisted");

        // 1. Create post and manifest with 2 resources
        let post_db_id = seed_listed_post(&conn, sub_id, "persist_post_1", "2026-09-01", "pending");
        conn.execute(
            "INSERT INTO kemono_files (
                post_id, source_identity, remote_path, file_name, file_type,
                status, created_at, updated_at, identity_basis
             ) VALUES (?1, 'img-1', '/files/img.png', 'img.png', 'image', 'pending',
                       '2026-09-01T12:00:00Z', '2026-09-01T12:00:00Z', 'source_id'),
                      (?1, 'zip-2', '/files/pkg.zip', 'pkg.zip', 'archive', 'pending',
                       '2026-09-01T12:00:00Z', '2026-09-01T12:00:00Z', 'source_id')",
            params![post_db_id],
        )
        .unwrap();

        let work_id = record_work_observation(&conn, post_db_id, ManifestCompleteness::Complete)
            .unwrap()
            .unwrap();

        let v1 = resource_version_id_for(&work_id, "img-1", UNKNOWN_VERSION);
        let v2 = resource_version_id_for(&work_id, "zip-2", UNKNOWN_VERSION);

        // 2. Acquire zip-2 and record into ledger
        insert_acquisition_event(
            &conn,
            "download_zip_key",
            &work_id,
            &v2,
            "att_persist_1",
            EvidenceSource::PublishLedger,
            Some(10),
            "2026-09-01T12:00:00Z",
            "/pictures/persisted/pkg.zip",
            "2026-09-01T12:00:00Z",
        )
        .unwrap();

        let mut settings = PawchiveSettings::default();
        settings.download_images = true;
        settings.download_archives = true;

        let d_before = demand_set(&conn, post_db_id, &settings).unwrap().unwrap();
        assert_eq!(d_before.acquired_resources, vec![v2.clone()]);
        assert_eq!(d_before.required_resources, vec![v1.clone()]);

        // 3. User extracts zip, deletes zip file, renames local folders
        // 4. User deletes the subscription
        delete_subscription(&conn, sub_id).unwrap();

        // Ledger records are preserved across subscription deletion!
        let acq_count: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM pawchive_acquisition_events WHERE work_id = ?1",
                params![work_id],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(
            acq_count, 1,
            "acquisition event must survive subscription deletion"
        );

        // 5. User re-subscribes
        let roots = MediaRoots {
            roots: vec!["/pictures".to_string()],
            labels: vec!["pictures".to_string()],
            real_paths: vec!["/pictures".to_string()],
        };
        let new_sub = add_subscription_from_url(
            &conn,
            &format!("https://kemono.cr/fanbox/user/{creator_id}"),
            Some("/pictures/persisted"),
            None,
            &roots,
        )
        .unwrap();

        // 6. Simulate restart: call ensure_pawchive_schema
        ensure_pawchive_schema(&conn).unwrap();

        // Re-link post under new subscription
        let new_post_id =
            seed_listed_post(&conn, new_sub.id, "persist_post_1", "2026-09-01", "pending");
        conn.execute(
            "INSERT INTO kemono_files (
                post_id, source_identity, remote_path, file_name, file_type,
                status, created_at, updated_at, identity_basis
             ) VALUES (?1, 'img-1', '/files/img.png', 'img.png', 'image', 'pending',
                       '2026-09-01T12:00:00Z', '2026-09-01T12:00:00Z', 'source_id'),
                      (?1, 'zip-2', '/files/pkg.zip', 'pkg.zip', 'archive', 'pending',
                       '2026-09-01T12:00:00Z', '2026-09-01T12:00:00Z', 'source_id')",
            params![new_post_id],
        )
        .unwrap();
        let _ = record_work_observation(&conn, new_post_id, ManifestCompleteness::Complete)
            .unwrap()
            .unwrap();

        // 7. Demand check: auto download will NOT re-download the deleted zip!
        let d_after = demand_set(&conn, new_post_id, &settings).unwrap().unwrap();
        assert_eq!(
            d_after.acquired_resources,
            vec![v2.clone()],
            "zip is still marked acquired in ledger"
        );
        assert_eq!(
            d_after.required_resources,
            vec![v1],
            "automatic demand only asks for remaining unacquired resources"
        );

        // 8. Explicit manual attempt can still re-download v2
        let sel = record_selection(
            &conn,
            "req_manual_refetch_001",
            &[new_post_id],
            &[],
            &settings,
        )
        .unwrap();
        let attempt = create_attempt(&conn, "req_manual_refetch_001", &sel.selection_id).unwrap();
        assert!(!attempt.attempt_id.is_empty());
    }

    #[test]
    fn restart_and_migration_matrix_manifest_retirement_and_zero_write_steady_state() {
        let conn = test_conn();
        conn.execute_batch(
            "CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at INTEGER NOT NULL);",
        )
        .unwrap();
        let sub = auto_subscription(&conn, "fanbox", "retire_author", "/pictures/retire");
        let post_db_id = seed_listed_post(&conn, sub, "retire_post", "2026-09-05", "pending");
        let (work_id, _) = crate::pawchive_pairing_write::work_of_post(&conn, post_db_id)
            .unwrap()
            .unwrap();

        // Retired manifest: explicit empty manifest
        conn.execute(
            "INSERT INTO pawchive_work_manifests (manifest_id, work_id, member_fingerprint, is_current, completeness, observed_at)
             VALUES ('man_empty', ?1, 'empty', 1, 'complete', '2026-09-05T12:00:00Z')",
            params![work_id],
        )
        .unwrap();

        let settings = PawchiveSettings::default();
        let d = demand_set(&conn, post_db_id, &settings).unwrap().unwrap();
        assert!(
            d.required_resources.is_empty(),
            "empty manifest has no requirements"
        );

        // Run migrations once to establish steady state
        ensure_pawchive_schema(&conn).unwrap();

        // Restart idempotency: running migrations again on steady state produces zero writes
        let changes_before = conn.total_changes();
        ensure_pawchive_schema(&conn).unwrap();
        let changes_after = conn.total_changes();
        assert_eq!(
            changes_before, changes_after,
            "steady state restart must perform zero writes"
        );
    }

    #[test]
    fn regression_d1_empty_template_folder_does_not_mask_day_content() {
        let dir = tempfile::tempdir().unwrap();
        let artist = dir.path().join("artist");
        fs::create_dir_all(&artist).unwrap();

        // 1. Template folder exists but is empty
        let template_folder = artist.join("2026-09-15 a title");
        fs::create_dir_all(&template_folder).unwrap();

        // 2. Another folder on the same day has extracted content
        let extracted_folder = artist.join("2026-09-15 extracted_archive");
        let nested = extracted_folder.join("nested");
        fs::create_dir_all(&nested).unwrap();
        fs::write(nested.join("a.png"), b"content bytes").unwrap();

        let ctx = PostNamingContext::new(
            "artist",
            Some("2026-09-15T12:00:00+00:00"),
            Some("a title"),
            "1001",
            Some("fanbox"),
        );
        let derived = derived_text_names(&ctx);
        let resolved = resolve_post_folder(
            &artist.to_string_lossy(),
            &ctx,
            "{date} {title}",
            &ctx.date,
            &derived,
        );

        // D1 fix: Should prefer extracted_folder which has real content over empty template folder
        assert_eq!(resolved.path, extracted_folder);
        assert_eq!(resolved.source, FOLDER_FROM_DAY);
        assert!(
            !resolved.incomplete,
            "a search that read every directory it needed is not incomplete"
        );
    }

    #[test]
    fn regression_d2_derive_assessment_unifies_date_content_policy() {
        // Test partial case: 1 proven, 9 missing, but date content is present
        let partial_evidence = PostEvidence {
            post_db_id: 1,
            required_assets: 10,
            proven_assets: 1,
            unverified_assets: 0,
            deferred_assets: 0,
            integrity_failed_assets: 0,
            observed_content: true,
            observed_unreadable: false,
            has_external_links: false,
            external_delivered: false,
            in_range: true,
            latest_decision: None,
            observed_source: FOLDER_FROM_DAY.to_string(),
        };
        let a = derive_assessment(&partial_evidence);
        assert_eq!(a.state, PostState::Verified);
        assert_eq!(a.reason, DAY_FOLDER_REASON);
        assert_eq!(a.proven_assets, 1);
        assert_eq!(a.missing_assets, 9);
        assert!(!a.state.is_claimable());

        // Test external pending case: 0 required direct assets, external links pending, but date content is present
        let external_evidence = PostEvidence {
            post_db_id: 2,
            required_assets: 0,
            proven_assets: 0,
            unverified_assets: 0,
            deferred_assets: 0,
            integrity_failed_assets: 0,
            observed_content: true,
            observed_unreadable: false,
            has_external_links: true,
            external_delivered: false,
            in_range: true,
            latest_decision: None,
            observed_source: FOLDER_FROM_DAY.to_string(),
        };
        let a = derive_assessment(&external_evidence);
        assert_eq!(a.state, PostState::Verified);
        assert_eq!(a.reason, DAY_FOLDER_REASON);
        assert!(!a.state.is_claimable());
    }

