    #[test]
    fn a_scoped_observation_reads_only_that_subscription() {
        let conn = test_conn();
        let first =
            upsert_subscription(&conn, "fanbox", "creator_one", None, "/pictures1/one", None)
                .unwrap();
        let second =
            upsert_subscription(&conn, "fanbox", "creator_two", None, "/pictures1/two", None)
                .unwrap();
        let p1 = insert_test_post(&conn, first, "p_scoped_1");
        let p2 = insert_test_post(&conn, second, "p_scoped_2");

        let all = posts_to_observe(&conn, 100, None).unwrap();
        let mut ids: Vec<i64> = all.iter().map(|row| row.post_db_id).collect();
        ids.sort_unstable();
        assert_eq!(ids, vec![p1, p2], "the panel-wide read covers both");

        let scoped = posts_to_observe(&conn, 100, Some(second)).unwrap();
        assert_eq!(scoped.len(), 1, "the per-artist read is narrowed to one");
        assert_eq!(scoped[0].post_db_id, p2);
        assert_eq!(scoped[0].subscription_id, second);

        // The digest the per-artist 核对本地 reports is scoped too: reporting the
        // other subscription's counts as this one's result would be a lie.
        let digest = reassess_subscription_posts(&conn, second).unwrap();
        assert_eq!(digest.posts, 1);
        assert_eq!(reassess_all_posts(&conn).unwrap().posts, 2);
    }

